cat > /workspace/src/utils.rs << 'RUST_EOF'
/// Convert a string to a valid HTML ID/anchor (similar to pulldown-cmark's behavior)
pub fn id_from_content(content: &str) -> String {
    let mut id = String::new();
    let mut last_was_dash = false;

    for c in content.chars() {
        if c.is_ascii_alphanumeric() || c == '-' || c == '_' {
            let lc = c.to_lowercase().next().unwrap();
            if lc == '-' {
                if !last_was_dash && !id.is_empty() {
                    id.push('-');
                    last_was_dash = true;
                }
            } else {
                id.push(lc);
                last_was_dash = false;
            }
        } else if c == ' ' {
            if !last_was_dash && !id.is_empty() {
                id.push('-');
                last_was_dash = true;
            }
        }
        // Skip other punctuation
    }

    // Remove trailing dashes
    while id.ends_with('-') {
        id.pop();
    }

    id
}

/// Escape HTML special characters
pub fn escape_html(s: &str) -> String {
    let mut result = String::with_capacity(s.len());
    for c in s.chars() {
        match c {
            '&' => result.push_str("&amp;"),
            '<' => result.push_str("&lt;"),
            '>' => result.push_str("&gt;"),
            '"' => result.push_str("&quot;"),
            '\'' => result.push_str("&#x27;"),
            _ => result.push(c),
        }
    }
    result
}

/// Normalize a path by removing ./ prefix and converting \ to /
pub fn normalize_path(path: &str) -> String {
    let p = path.replace('\\', "/");
    if p.starts_with("./") {
        p[2..].to_string()
    } else {
        p
    }
}

/// Convert a markdown link path to an HTML path
/// e.g., "chapter1/index.md" -> "chapter1/index.html"
pub fn md_to_html_path(path: &str) -> String {
    if path.ends_with(".md") {
        format!("{}.html", &path[..path.len()-3])
    } else {
        path.to_string()
    }
}

/// Get the path to root from a chapter path
/// e.g., "chapter1/sub1.html" -> "../"
/// e.g., "chapter1.html" -> ""
pub fn path_to_root(path: &str) -> String {
    let depth = path.matches('/').count();
    if depth == 0 {
        String::new()
    } else {
        "../".repeat(depth)
    }
}

/// Strip HTML tags from a string (for search index)
pub fn strip_html(s: &str) -> String {
    let mut result = String::new();
    let mut in_tag = false;
    for c in s.chars() {
        if c == '<' {
            in_tag = true;
        } else if c == '>' {
            in_tag = false;
            result.push(' ');
        } else if !in_tag {
            result.push(c);
        }
    }
    result
}

/// Log an info message
pub fn log_info(target: &str, msg: &str) {
    let now = chrono_now();
    eprintln!("{} [INFO] ({}): {}", now, target, msg);
}

fn chrono_now() -> String {
    // Simple timestamp - just use a fixed format
    use std::time::{SystemTime, UNIX_EPOCH};
    let secs = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs();

    // Convert to approximate datetime (simplified)
    let days_since_epoch = secs / 86400;
    let time_of_day = secs % 86400;

    // Approximate date calculation
    let (year, month, day) = days_to_ymd(days_since_epoch);
    let hours = time_of_day / 3600;
    let minutes = (time_of_day % 3600) / 60;
    let seconds = time_of_day % 60;

    format!("{:04}-{:02}-{:02} {:02}:{:02}:{:02}", year, month, day, hours, minutes, seconds)
}

fn days_to_ymd(days: u64) -> (u64, u64, u64) {
    // Approximate - good enough for logging
    let mut remaining = days;
    let mut year = 1970u64;

    loop {
        let days_in_year = if is_leap_year(year) { 366 } else { 365 };
        if remaining < days_in_year {
            break;
        }
        remaining -= days_in_year;
        year += 1;
    }

    let months = [31u64, if is_leap_year(year) { 29 } else { 28 }, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    let mut month = 1u64;
    for &m in &months {
        if remaining < m {
            break;
        }
        remaining -= m;
        month += 1;
    }

    (year, month, remaining + 1)
}

fn is_leap_year(year: u64) -> bool {
    (year % 4 == 0 && year % 100 != 0) || (year % 400 == 0)
}
RUST_EOF

