// Simple TOML value representation
#[derive(Debug, Clone)]
pub enum TomlValue {
    String(String),
    Integer(i64),
    Float(f64),
    Boolean(bool),
    Array(Vec<TomlValue>),
    Table(HashMap<String, TomlValue>),
    Null,
}

impl fmt::Display for TomlValue {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            TomlValue::String(s) => write!(f, "{}", s),
            TomlValue::Integer(i) => write!(f, "{}", i),
            TomlValue::Float(fl) => write!(f, "{}", fl),
            TomlValue::Boolean(b) => write!(f, "{}", b),
            TomlValue::Array(_) => write!(f, "[...]"),
            TomlValue::Table(_) => write!(f, "{{...}}"),
            TomlValue::Null => write!(f, "null"),
        }
    }
}

impl TomlValue {
    pub fn as_str(&self) -> Option<&str> {
        match self { TomlValue::String(s) => Some(s), _ => None }
    }
    pub fn as_bool(&self) -> Option<bool> {
        match self { TomlValue::Boolean(b) => Some(*b), _ => None }
    }
    pub fn as_i64(&self) -> Option<i64> {
        match self { TomlValue::Integer(i) => Some(*i), _ => None }
    }
    pub fn as_u32(&self) -> Option<u32> {
        match self { TomlValue::Integer(i) => Some(*i as u32), _ => None }
    }
    pub fn as_array(&self) -> Option<&Vec<TomlValue>> {
        match self { TomlValue::Array(a) => Some(a), _ => None }
    }
    pub fn as_table(&self) -> Option<&HashMap<String, TomlValue>> {
        match self { TomlValue::Table(t) => Some(t), _ => None }
    }
}

