                        }
                        for (k, v) in t {
                            pc.extra.insert(k.clone(), v.clone());
                        }
                    }
                    config.preprocessors.insert(name.clone(), pc);
                }
            }
        }

        config.raw = table;
        Ok(config)
    }

    pub fn get_html_config(&self) -> HtmlConfig {
        self.output.html.clone().unwrap_or_default()
    }
}

