// Simple TOML parser
pub fn parse_toml(input: &str) -> Result<HashMap<String, TomlValue>, String> {
    let mut result: HashMap<String, TomlValue> = HashMap::new();
    let mut current_table_path: Vec<String> = Vec::new();
    let mut current_array_of_tables: Option<Vec<String>> = None;

    let lines: Vec<&str> = input.lines().collect();
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i].trim();
        i += 1;

        // Skip comments and empty lines
        if line.is_empty() || line.starts_with('#') {
            continue;
        }

        // Handle array of tables [[table]]
        if line.starts_with("[[") && line.ends_with("]]") {
            let key = &line[2..line.len()-2].trim();
            let parts: Vec<String> = key.split('.').map(|s| s.trim().to_string()).collect();
            current_array_of_tables = Some(parts.clone());
            current_table_path = parts;
            // Create or append to array
            let arr_path = current_table_path.clone();
            ensure_array_entry(&mut result, &arr_path);
            continue;
        }

        // Handle table headers [table]
        if line.starts_with('[') && line.ends_with(']') && !line.starts_with("[[") {
            let key = &line[1..line.len()-1].trim();
            let parts: Vec<String> = key.split('.').map(|s| s.trim().to_string()).collect();
            current_table_path = parts;
            current_array_of_tables = None;
            // Ensure the table exists
            ensure_table(&mut result, &current_table_path);
            continue;
        }

        // Handle key = value
        if let Some(eq_pos) = line.find('=') {
            let key = line[..eq_pos].trim().to_string();
            let value_str = line[eq_pos+1..].trim();

            // Handle multiline values (arrays, etc.)
            let (value, extra_lines) = parse_value_maybe_multiline(value_str, &lines[i..]);
            i += extra_lines;

            // Set the value at the current path
            let mut full_path = current_table_path.clone();
            // Handle dotted keys
            let key_parts: Vec<String> = split_dotted_key(&key);
            full_path.extend(key_parts);

            set_value(&mut result, &full_path, value);
        }
    }

    Ok(result)
}

fn split_dotted_key(key: &str) -> Vec<String> {
    // Simple split on dots, but handle quoted keys
    let mut parts = Vec::new();
    let mut current = String::new();
    let mut in_quote = false;
    let mut quote_char = ' ';

    for c in key.chars() {
        if in_quote {
            if c == quote_char {
                in_quote = false;
            } else {
                current.push(c);
            }
        } else if c == '"' || c == '\'' {
            in_quote = true;
            quote_char = c;
        } else if c == '.' {
            if !current.is_empty() {
                parts.push(current.trim().to_string());
                current = String::new();
            }
        } else {
            current.push(c);
        }
    }
    if !current.trim().is_empty() {
        parts.push(current.trim().to_string());
    }
    parts
}

fn ensure_table(result: &mut HashMap<String, TomlValue>, path: &[String]) {
    if path.is_empty() { return; }
    let first = &path[0];
    if path.len() == 1 {
        result.entry(first.clone()).or_insert(TomlValue::Table(HashMap::new()));
    } else {
        let entry = result.entry(first.clone())
            .or_insert(TomlValue::Table(HashMap::new()));
        if let TomlValue::Table(t) = entry {
            ensure_table(t, &path[1..]);
        }
    }
}

fn ensure_array_entry(result: &mut HashMap<String, TomlValue>, path: &[String]) {
    if path.is_empty() { return; }
    if path.len() == 1 {
        let key = &path[0];
        let entry = result.entry(key.clone())
            .or_insert(TomlValue::Array(Vec::new()));
        if let TomlValue::Array(arr) = entry {
            arr.push(TomlValue::Table(HashMap::new()));
        }
    } else {
        let first = &path[0];
        let entry = result.entry(first.clone())
            .or_insert(TomlValue::Table(HashMap::new()));
        if let TomlValue::Table(t) = entry {
            ensure_array_entry(t, &path[1..]);
        }
    }
}

fn set_value(result: &mut HashMap<String, TomlValue>, path: &[String], value: TomlValue) {
    if path.is_empty() { return; }
    let key = &path[0];
    if path.len() == 1 {
        result.insert(key.clone(), value);
    } else {
        let entry = result.entry(key.clone())
            .or_insert(TomlValue::Table(HashMap::new()));
        if let TomlValue::Table(t) = entry {
            set_value(t, &path[1..], value);
        }
    }
}

fn parse_value_maybe_multiline(value_str: &str, remaining_lines: &[&str]) -> (TomlValue, usize) {
    let trimmed = value_str.trim();

    // Check if it's a multiline array
    if trimmed.starts_with('[') && !trimmed.ends_with(']') {
        // Multiline array
        let mut full = trimmed.to_string();
        let mut extra = 0;
        for line in remaining_lines {
            extra += 1;
            full.push('\n');
            full.push_str(line.trim());
            if line.contains(']') {
                break;
            }
        }
        return (parse_value(&full), extra);
    }

    (parse_value(trimmed), 0)
}

pub fn parse_value(s: &str) -> TomlValue {
    let s = s.trim();

    if s == "true" {
        return TomlValue::Boolean(true);
    }
    if s == "false" {
        return TomlValue::Boolean(false);
    }

    // String with double quotes
    if s.starts_with('"') && s.ends_with('"') && s.len() >= 2 {
        let inner = &s[1..s.len()-1];
        return TomlValue::String(unescape_toml_string(inner));
    }

    // String with single quotes
    if s.starts_with('\'') && s.ends_with('\'') && s.len() >= 2 {
        let inner = &s[1..s.len()-1];
        return TomlValue::String(inner.to_string());
    }

    // Array
    if s.starts_with('[') {
        return parse_toml_array(s);
    }

    // Inline table
    if s.starts_with('{') {
        return parse_inline_table(s);
    }

    // Number
    if let Ok(i) = s.parse::<i64>() {
        return TomlValue::Integer(i);
    }
    if let Ok(f) = s.parse::<f64>() {
        return TomlValue::Float(f);
    }

    // Fallback - treat as string
    TomlValue::String(s.to_string())
}

fn unescape_toml_string(s: &str) -> String {
    let mut result = String::new();
    let mut chars = s.chars().peekable();
    while let Some(c) = chars.next() {
        if c == '\\' {
            match chars.next() {
                Some('n') => result.push('\n'),
                Some('t') => result.push('\t'),
                Some('r') => result.push('\r'),
                Some('\\') => result.push('\\'),
                Some('"') => result.push('"'),
                Some(c) => { result.push('\\'); result.push(c); }
                None => result.push('\\'),
            }
        } else {
            result.push(c);
        }
    }
    result
}

fn parse_toml_array(s: &str) -> TomlValue {
    // Remove outer brackets
    let inner = s.trim();
    let inner = if inner.starts_with('[') && inner.ends_with(']') {
        &inner[1..inner.len()-1]
    } else {
        inner
    };

    let mut items = Vec::new();
    let mut current = String::new();
    let mut depth = 0;
    let mut in_string = false;
    let mut string_char = ' ';

    for c in inner.chars() {
        if in_string {
            if c == string_char {
                in_string = false;
                current.push(c);
            } else {
                current.push(c);
            }
        } else {
            match c {
                '"' | '\'' => {
                    in_string = true;
                    string_char = c;
                    current.push(c);
                }
                '[' | '{' => { depth += 1; current.push(c); }
                ']' | '}' => { depth -= 1; current.push(c); }
                ',' if depth == 0 => {
                    let trimmed = current.trim().to_string();
                    if !trimmed.is_empty() && trimmed != "#" {
                        // Skip comments
                        if !trimmed.starts_with('#') {
                            items.push(parse_value(&trimmed));
                        }
                    }
                    current = String::new();
                }
                '#' if depth == 0 => {
                    // Rest is comment
                    break;
                }
                '\n' | '\r' => {
                    // Newlines in multiline arrays - just skip
                }
                _ => current.push(c),
            }
        }
    }

    let trimmed = current.trim().to_string();
    if !trimmed.is_empty() && !trimmed.starts_with('#') {
        items.push(parse_value(&trimmed));
    }

    TomlValue::Array(items)
}

fn parse_inline_table(s: &str) -> TomlValue {
    let inner = if s.starts_with('{') && s.ends_with('}') {
        &s[1..s.len()-1]
    } else {
        s
    };

    let mut table = HashMap::new();
    // Simple parsing for inline tables
    for pair in inner.split(',') {
        let pair = pair.trim();
        if let Some(eq_pos) = pair.find('=') {
            let key = pair[..eq_pos].trim().to_string();
            let val = pair[eq_pos+1..].trim();
            table.insert(key, parse_value(val));
        }
    }

    TomlValue::Table(table)
}
