                if let Some(v) = book_table.get("title") {
                    config.book.title = Some(v.to_string());
                }
                if let Some(v) = book_table.get("authors") {
                    if let Some(arr) = v.as_array() {
                        config.book.authors = arr.iter().map(|a| a.to_string()).collect();
                    }
                }
                if let Some(v) = book_table.get("description") {
                    config.book.description = Some(v.to_string());
                }
                if let Some(v) = book_table.get("src") {
                    config.book.src = v.to_string();
                }
                if let Some(v) = book_table.get("language") {
                    config.book.language = v.to_string();
                }
                if let Some(v) = book_table.get("text-direction") {
                    config.book.text_direction = Some(v.to_string());
                }
                if let Some(v) = book_table.get("multilingual") {
                    config.book.multilingual = v.as_bool().unwrap_or(false);
                }
            }
        }

        if let Some(build_val) = table.get("build") {
            if let Some(build_table) = build_val.as_table() {
                if let Some(v) = build_table.get("build-dir") {
                    config.build.build_dir = PathBuf::from(v.to_string());
                }
                if let Some(v) = build_table.get("create-missing") {
                    config.build.create_missing = v.as_bool().unwrap_or(true);
                }
                if let Some(v) = build_table.get("use-default-preprocessors") {
                    config.build.use_default_preprocessors = v.as_bool().unwrap_or(true);
                }
                if let Some(v) = build_table.get("extra-watch-dirs") {
                    if let Some(arr) = v.as_array() {
                        config.build.extra_watch_dirs = arr.iter()
                            .map(|a| PathBuf::from(a.to_string()))
                            .collect();
                    }
                }
            }
        }

        if let Some(rust_val) = table.get("rust") {
            if let Some(rust_table) = rust_val.as_table() {
                if let Some(v) = rust_table.get("edition") {
                    config.rust.edition = v.to_string();
                }
            }
        }

        // Parse output
        if let Some(output_val) = table.get("output") {
            if let Some(output_table) = output_val.as_table() {
                if let Some(html_val) = output_table.get("html") {
                    let mut html_config = HtmlConfig::default();
                    if let Some(html_table) = html_val.as_table() {
                        parse_html_config(&mut html_config, html_table);
                    }
                    config.output.html = Some(html_config);
                }
                if output_table.contains_key("markdown") {
                    config.output.markdown = Some(MarkdownConfig::default());
                }
                for (k, v) in output_table {
                    if k != "html" && k != "markdown" {
                        config.output.others.insert(k.clone(), v.clone());
                    }
                }
            }
        }

        // Parse preprocessors
        if let Some(pre_val) = table.get("preprocessor") {
            if let Some(pre_table) = pre_val.as_table() {
                for (name, val) in pre_table {
                    let mut pc = PreprocessorConfig::default();
                    if let Some(t) = val.as_table() {
                        if let Some(v) = t.get("command") {
                            pc.command = Some(v.to_string());
                        }
                        if let Some(v) = t.get("after") {
                            if let Some(arr) = v.as_array() {
                                pc.after = arr.iter().map(|a| a.to_string()).collect();
                            }
                        }
                        if let Some(v) = t.get("before") {
                            if let Some(arr) = v.as_array() {
                                pc.before = arr.iter().map(|a| a.to_string()).collect();
                            }
                        }
                        if let Some(v) = t.get("optional") {
                            pc.optional = v.as_bool().unwrap_or(false);
                        }
                        for (k, v) in t {
                            pc.extra.insert(k.clone(), v.clone());
                        }
                    }
                    config.preprocessors.insert(name.clone(), pc);
                }
            }
        }

        config.raw = table;
        Ok(config)
    }

    pub fn get_html_config(&self) -> HtmlConfig {
        self.output.html.clone().unwrap_or_default()
    }
}

