        BookIter { stack: vec![self.sections.iter()] }
    }
}

pub struct BookIter<'a> {
    stack: Vec<std::slice::Iter<'a, BookItem>>,
}

impl<'a> Iterator for BookIter<'a> {
    type Item = &'a BookItem;

    fn next(&mut self) -> Option<Self::Item> {
        loop {
            if let Some(iter) = self.stack.last_mut() {
                if let Some(item) = iter.next() {
                    if let BookItem::Chapter(ch) = item {
                        if !ch.sub_items.is_empty() {
                            // We'll handle sub-items by pushing them
                            // But we return the current item first
                        }
                    }
                    return Some(item);
                } else {
                    self.stack.pop();
                }
            } else {
                return None;
            }
        }
    }
}

/// Load a book from a directory and config
pub fn load_book(root: &Path, config: &Config, dest_dir: Option<&Path>) -> Result<Book, String> {
    let src_dir = root.join(&config.book.src);

    // Parse SUMMARY.md
    let summary_path = src_dir.join("SUMMARY.md");
    let summary_content = std::fs::read_to_string(&summary_path)
        .map_err(|e| format!("Failed to read SUMMARY.md: {}", e))?;

    let mut book = parse_summary(&summary_content, &src_dir)?;

    // Create missing files if configured
    if config.build.create_missing {
        create_missing_files(&mut book, &src_dir)?;
    }

    // Load chapter content
    load_chapter_content(&mut book.sections, &src_dir)?;

    Ok(book)
}

fn create_missing_files(book: &mut Book, src_dir: &Path) -> Result<(), String> {
    create_missing_in_items(&mut book.sections, src_dir)
}

fn create_missing_in_items(items: &mut Vec<BookItem>, src_dir: &Path) -> Result<(), String> {
    for item in items.iter_mut() {
        if let BookItem::Chapter(ch) = item {
            if let Some(path) = &ch.source_path {
                let full_path = src_dir.join(path);
                if !full_path.exists() {
                    // Create parent directories
                    if let Some(parent) = full_path.parent() {
                        std::fs::create_dir_all(parent)
                            .map_err(|e| format!("Failed to create dir: {}", e))?;
                    }
                    // Create stub file
                    let content = format!("# {}\n", ch.name);
                    std::fs::write(&full_path, &content)
                        .map_err(|e| format!("Failed to create file {:?}: {}", full_path, e))?;
                }
            }
            create_missing_in_items(&mut ch.sub_items, src_dir)?;
        }
    }
    Ok(())
}

fn load_chapter_content(items: &mut Vec<BookItem>, src_dir: &Path) -> Result<(), String> {
    for item in items.iter_mut() {
        if let BookItem::Chapter(ch) = item {
            if let Some(path) = &ch.source_path {
                let full_path = src_dir.join(path);
                match std::fs::read_to_string(&full_path) {
                    Ok(content) => ch.content = content,
                    Err(e) => {
                        return Err(format!("Failed to read {:?}: {}", full_path, e));
                    }
