#[derive(Debug)]
enum SummaryToken {
    Heading(String),
    ListItem { indent: usize, text: String, link: Option<String> },
    Separator,
    Other,
}

fn parse_summary_items(content: &str) -> Vec<BookItem> {
    let tokens = tokenize_summary(content);
    build_items_from_tokens(&tokens)
}

fn tokenize_summary(content: &str) -> Vec<SummaryToken> {
    let mut tokens = Vec::new();

    for line in content.lines() {
        // Skip the title line (# Summary)
        if line.trim().starts_with('#') {
            // Check if it's h1 - part title
            let heading_text = line.trim().trim_start_matches('#').trim().to_string();
            if line.trim().starts_with("# ") && !line.trim().starts_with("## ") {
                // Could be "# Summary" (ignore) or "# Part Title" (add as part)
                // We'll figure this out in the builder
                tokens.push(SummaryToken::Heading(heading_text));
            }
            continue;
        }

        // Separator line
        let trimmed = line.trim();
        if trimmed.starts_with("---") && trimmed.chars().all(|c| c == '-') {
            tokens.push(SummaryToken::Separator);
            continue;
        }

        // List item
        if let Some(item) = parse_list_item(line) {
            tokens.push(item);
            continue;
        }
    }

    tokens
}

fn parse_list_item(line: &str) -> Option<SummaryToken> {
    // Count leading spaces/tabs for indentation
    let indent = line.chars().take_while(|&c| c == ' ' || c == '\t').count();
    let trimmed = &line[indent..];

    // Check if it's a list item (-, *, digits.)
    let rest = if trimmed.starts_with("- ") || trimmed.starts_with("* ") {
        &trimmed[2..]
    } else if let Some(pos) = trimmed.find(". ") {
        if trimmed[..pos].chars().all(|c| c.is_ascii_digit()) {
            &trimmed[pos+2..]
        } else {
            return None;
        }
    } else {
        return None;
    };

    // Parse [text](link) or just [text]() or [text]
    let (text, link) = parse_markdown_link(rest.trim());

    Some(SummaryToken::ListItem { indent, text, link })
}

fn parse_markdown_link(s: &str) -> (String, Option<String>) {
    // Parse [text](link)
    if s.starts_with('[') {
        if let Some(close_bracket) = find_close_bracket(s, 0) {
            let text = s[1..close_bracket].to_string();
            let rest = &s[close_bracket+1..];
            if rest.starts_with('(') {
                if let Some(close_paren) = rest.find(')') {
                    let link = rest[1..close_paren].trim().to_string();
                    return (text, if link.is_empty() { None } else { Some(link) });
                }
            }
            return (text, None);
        }
    }
    (s.to_string(), None)
}

fn find_close_bracket(s: &str, start: usize) -> Option<usize> {
    let chars: Vec<char> = s.chars().collect();
    let mut depth = 0;
    let mut i = start;
    while i < chars.len() {
        match chars[i] {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 { return Some(i); }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

// State machine to parse summary
struct SummaryParser {
    prefix_done: bool,
    numbered_started: bool,
    suffix_started: bool,
    items: Vec<BookItem>,
}

fn build_items_from_tokens(tokens: &[SummaryToken]) -> Vec<BookItem> {
    let mut items: Vec<BookItem> = Vec::new();
    let mut prefix_done = false;
    let mut numbered_started = false;
    let mut suffix_started = false;

    // We need to handle nested list items
    // Process tokens to build nested structure
    let mut flat_items: Vec<(usize, BookItem)> = Vec::new();
    let mut in_numbered_section = false;

    for token in tokens {
        match token {
            SummaryToken::Heading(title) => {
                // Check if it's just "Summary" - skip
                if title.to_lowercase() == "summary" {
                    continue;
                }
                prefix_done = true;
                in_numbered_section = true;
                numbered_started = true;
                flat_items.push((0, BookItem::PartTitle(title.clone())));
            }
            SummaryToken::Separator => {
                prefix_done = true;
                flat_items.push((0, BookItem::Separator));
                if numbered_started {
                    suffix_started = true;
                }
            }
            SummaryToken::ListItem { indent, text, link } => {
                let chapter = Chapter {
                    name: text.clone(),
                    content: String::new(),
                    number: None,
                    sub_items: Vec::new(),
                    path: link.as_ref().map(|l| {
                        let p = crate::utils::normalize_path(l);
                        // Convert .md path to output path
                        PathBuf::from(&p)
                    }),
                    source_path: link.as_ref().map(|l| {
                        let p = crate::utils::normalize_path(l);
                        PathBuf::from(&p)
                    }),
                    parent_names: Vec::new(),
                    is_prefix: !prefix_done && !numbered_started,
                    is_suffix: suffix_started,
                };

                if *indent == 0 && !prefix_done {
                    // Could be prefix
                    if !numbered_started {
                        flat_items.push((0, BookItem::Chapter(chapter)));
                    } else {
                        prefix_done = true;
                        numbered_started = true;
                        flat_items.push((0, BookItem::Chapter(chapter)));
                    }
                } else {
                    prefix_done = true;
                    if !suffix_started {
                        numbered_started = true;
                    }
                    flat_items.push((*indent, BookItem::Chapter(chapter)));
                }
            }
            SummaryToken::Other => {}
        }
    }

    // Now build nested structure from flat list with indentation levels
    build_nested(flat_items)
}

fn build_nested(flat: Vec<(usize, BookItem)>) -> Vec<BookItem> {
    let mut result: Vec<BookItem> = Vec::new();
    let mut i = 0;

    while i < flat.len() {
        let (indent, item) = &flat[i];

        if *indent == 0 {
            // Top level - but check if next items are children
            if let BookItem::Chapter(mut ch) = item.clone() {
                i += 1;
                // Collect children
                while i < flat.len() {
                    let (child_indent, _) = &flat[i];
                    if *child_indent > 0 {
                        // This is a child - collect all at this level
                        let (children, consumed) = collect_children(&flat[i..], *child_indent);
                        ch.sub_items = children;
                        i += consumed;
                        break;
                    } else {
                        break;
                    }
                }
                result.push(BookItem::Chapter(ch));
            } else {
                result.push(item.clone());
                i += 1;
            }
        } else {
            // Skip items that should have been consumed as children
            i += 1;
        }
    }

    result
}

fn collect_children(flat: &[(usize, BookItem)], base_indent: usize) -> (Vec<BookItem>, usize) {
    let mut result = Vec::new();
    let mut i = 0;

    while i < flat.len() {
        let (indent, item) = &flat[i];

        if *indent < base_indent {
            break;
        }

        if *indent == base_indent {
            if let BookItem::Chapter(mut ch) = item.clone() {
                i += 1;
                // Collect sub-children
                while i < flat.len() {
                    let (child_indent, _) = &flat[i];
                    if *child_indent > base_indent {
                        let (children, consumed) = collect_children(&flat[i..], *child_indent);
                        ch.sub_items = children;
                        i += consumed;
                        break;
                    } else {
                        break;
                    }
                }
                result.push(BookItem::Chapter(ch));
            } else {
                result.push(item.clone());
                i += 1;
            }
        } else {
            // Higher indent - shouldn't happen normally
            i += 1;
        }
    }

    (result, i)
}

fn assign_section_numbers(items: &mut Vec<BookItem>, counter: &mut Vec<u32>) {
