    // Parse [text](link) or just [text]() or [text]
    let (text, link) = parse_markdown_link(rest.trim());

    Some(SummaryToken::ListItem { indent, text, link })
}

fn parse_markdown_link(s: &str) -> (String, Option<String>) {
    // Parse [text](link)
    if s.starts_with('[') {
        if let Some(close_bracket) = find_close_bracket(s, 0) {
            let text = s[1..close_bracket].to_string();
            let rest = &s[close_bracket+1..];
            if rest.starts_with('(') {
                if let Some(close_paren) = rest.find(')') {
                    let link = rest[1..close_paren].trim().to_string();
                    return (text, if link.is_empty() { None } else { Some(link) });
                }
            }
            return (text, None);
        }
    }
    (s.to_string(), None)
}

fn find_close_bracket(s: &str, start: usize) -> Option<usize> {
    let chars: Vec<char> = s.chars().collect();
    let mut depth = 0;
    let mut i = start;
    while i < chars.len() {
        match chars[i] {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 { return Some(i); }
            }
            _ => {}
        }
        i += 1;
    }
    None
}

