    numbered_started: bool,
    suffix_started: bool,
    items: Vec<BookItem>,
}

fn build_items_from_tokens(tokens: &[SummaryToken]) -> Vec<BookItem> {
    let mut items: Vec<BookItem> = Vec::new();
    let mut prefix_done = false;
    let mut numbered_started = false;
    let mut suffix_started = false;

    // We need to handle nested list items
    // Process tokens to build nested structure
    let mut flat_items: Vec<(usize, BookItem)> = Vec::new();
    let mut in_numbered_section = false;

    for token in tokens {
        match token {
            SummaryToken::Heading(title) => {
                // Check if it's just "Summary" - skip
                if title.to_lowercase() == "summary" {
                    continue;
                }
                prefix_done = true;
                in_numbered_section = true;
                numbered_started = true;
                flat_items.push((0, BookItem::PartTitle(title.clone())));
            }
            SummaryToken::Separator => {
                prefix_done = true;
                flat_items.push((0, BookItem::Separator));
                if numbered_started {
                    suffix_started = true;
                }
            }
            SummaryToken::ListItem { indent, text, link } => {
                let chapter = Chapter {
                    name: text.clone(),
                    content: String::new(),
                    number: None,
                    sub_items: Vec::new(),
                    path: link.as_ref().map(|l| {
                        let p = crate::utils::normalize_path(l);
                        // Convert .md path to output path
                        PathBuf::from(&p)
                    }),
                    source_path: link.as_ref().map(|l| {
                        let p = crate::utils::normalize_path(l);
                        PathBuf::from(&p)
                    }),
                    parent_names: Vec::new(),
                    is_prefix: !prefix_done && !numbered_started,
                    is_suffix: suffix_started,
                };

                if *indent == 0 && !prefix_done {
                    // Could be prefix
                    if !numbered_started {
                        flat_items.push((0, BookItem::Chapter(chapter)));
                    } else {
                        prefix_done = true;
                        numbered_started = true;
                        flat_items.push((0, BookItem::Chapter(chapter)));
                    }
                } else {
                    prefix_done = true;
                    if !suffix_started {
                        numbered_started = true;
                    }
                    flat_items.push((*indent, BookItem::Chapter(chapter)));
                }
            }
            SummaryToken::Other => {}
        }
    }

    // Now build nested structure from flat list with indentation levels
    build_nested(flat_items)
}

fn build_nested(flat: Vec<(usize, BookItem)>) -> Vec<BookItem> {
    let mut result: Vec<BookItem> = Vec::new();
    let mut i = 0;

    while i < flat.len() {
        let (indent, item) = &flat[i];

        if *indent == 0 {
            // Top level - but check if next items are children
            if let BookItem::Chapter(mut ch) = item.clone() {
                i += 1;
                // Collect children
                while i < flat.len() {
                    let (child_indent, _) = &flat[i];
                    if *child_indent > 0 {
                        // This is a child - collect all at this level
                        let (children, consumed) = collect_children(&flat[i..], *child_indent);
                        ch.sub_items = children;
                        i += consumed;
                        break;
                    } else {
                        break;
                    }
                }
                result.push(BookItem::Chapter(ch));
            } else {
                result.push(item.clone());
                i += 1;
            }
        } else {
            // Skip items that should have been consumed as children
            i += 1;
        }
    }

    result
}

fn collect_children(flat: &[(usize, BookItem)], base_indent: usize) -> (Vec<BookItem>, usize) {
    let mut result = Vec::new();
    let mut i = 0;

    while i < flat.len() {
        let (indent, item) = &flat[i];

        if *indent < base_indent {
            break;
        }

        if *indent == base_indent {
            if let BookItem::Chapter(mut ch) = item.clone() {
                i += 1;
                // Collect sub-children
                while i < flat.len() {
                    let (child_indent, _) = &flat[i];
                    if *child_indent > base_indent {
                        let (children, consumed) = collect_children(&flat[i..], *child_indent);
                        ch.sub_items = children;
                        i += consumed;
                        break;
                    } else {
                        break;
                    }
                }
                result.push(BookItem::Chapter(ch));
            } else {
                result.push(item.clone());
                i += 1;
            }
        } else {
            // Higher indent - shouldn't happen normally
            i += 1;
        }
    }

    (result, i)
}

fn assign_section_numbers(items: &mut Vec<BookItem>, counter: &mut Vec<u32>) {
    // Track prefix/suffix state
    let mut in_numbered = false;
    let mut numbered_count = 0u32;

    // First pass: determine which items are numbered
    for item in items.iter_mut() {
        match item {
            BookItem::Chapter(ch) => {
                if ch.is_prefix || ch.is_suffix {
                    ch.number = None;
                } else {
                    // numbered chapter
                    if counter.is_empty() {
                        numbered_count += 1;
                        let mut my_counter = counter.clone();
                        my_counter.push(numbered_count);
                        ch.number = Some(SectionNumber(my_counter.clone()));
                        assign_section_numbers(&mut ch.sub_items, &mut my_counter);
                    } else {
                        numbered_count += 1;
                        let mut my_counter = counter.clone();
                        my_counter.push(numbered_count);
                        ch.number = Some(SectionNumber(my_counter.clone()));
                        assign_section_numbers(&mut ch.sub_items, &mut my_counter);
                    }
                }
            }
            _ => {}
        }
    }
}

/// More sophisticated parsing that properly handles prefix/suffix/numbered
pub fn parse_summary_v2(content: &str) -> Result<Book, String> {
    let mut book = Book::new();
    book.sections = parse_summary_detailed(content);
    Ok(book)
}

#[derive(Debug, Clone, PartialEq)]
enum SummarySection {
    Prefix,
    Numbered,
    Suffix,
}

fn parse_summary_detailed(content: &str) -> Vec<BookItem> {
    let lines: Vec<&str> = content.lines().collect();
    let mut items: Vec<(usize, SummarySection, BookItem)> = Vec::new();

    let mut section = SummarySection::Prefix;
    let mut numbered_started = false;

    for line in &lines {
        let trimmed = line.trim();

        // Skip empty lines
        if trimmed.is_empty() { continue; }

        // Skip the title (# Summary)
        if trimmed == "# Summary" { continue; }

        // Part title (h1 heading that's not "# Summary")
        if trimmed.starts_with("# ") && !trimmed.starts_with("## ") {
            let title = trimmed[2..].trim().to_string();
            numbered_started = true;
            section = SummarySection::Numbered;
            items.push((0, section.clone(), BookItem::PartTitle(title)));
            continue;
        }

        // Separator
        if trimmed.starts_with("---") && trimmed.chars().all(|c| c == '-') {
            if numbered_started {
                section = SummarySection::Suffix;
            }
            items.push((0, section.clone(), BookItem::Separator));
            continue;
        }

        // List item
        if let Some((indent, text, link)) = parse_list_item_v2(line) {
            let is_prefix = section == SummarySection::Prefix && !numbered_started;
            let is_suffix = section == SummarySection::Suffix;

            if !is_prefix && !is_suffix {
                numbered_started = true;
                section = SummarySection::Numbered;
            }

            let chapter = Chapter {
                name: text,
                content: String::new(),
                number: None,
                sub_items: Vec::new(),
                path: link.as_ref().map(|l| PathBuf::from(crate::utils::normalize_path(l))),
                source_path: link.as_ref().map(|l| PathBuf::from(crate::utils::normalize_path(l))),
                parent_names: Vec::new(),
                is_prefix,
                is_suffix,
            };

            items.push((indent, section.clone(), BookItem::Chapter(chapter)));
            continue;
        }

        // Prefix/suffix link without list marker (e.g., "[Introduction](intro.md)")
        if trimmed.starts_with('[') {
            let (text, link) = parse_markdown_link(trimmed);
            let is_prefix = !numbered_started;
            let is_suffix = section == SummarySection::Suffix;

            if !is_prefix && !is_suffix {
                // This is actually after numbered - must be suffix
                // But how do we know? Suffix chapters are at top level with no list marker
                // after numbered chapters
            }

            let chapter = Chapter {
                name: text,
                content: String::new(),
                number: None,
                sub_items: Vec::new(),
                path: link.as_ref().map(|l| PathBuf::from(crate::utils::normalize_path(l))),
                source_path: link.as_ref().map(|l| PathBuf::from(crate::utils::normalize_path(l))),
                parent_names: Vec::new(),
                is_prefix,
                is_suffix,
            };

            items.push((0, section.clone(), BookItem::Chapter(chapter)));
        }
    }

    // Build nested structure
    build_nested_v2(items)
}

fn parse_list_item_v2(line: &str) -> Option<(usize, String, Option<String>)> {
    let indent_chars: usize = line.chars().take_while(|&c| c == ' ' || c == '\t').count();
    // Normalize: tabs count as spaces (or as indent levels)
    let indent = indent_chars;
    let trimmed = line[indent..].trim_start();

    let rest = if trimmed.starts_with("- ") || trimmed.starts_with("* ") {
        &trimmed[2..]
    } else if let Some(pos) = trimmed.find(". ") {
        if trimmed[..pos].chars().all(|c| c.is_ascii_digit()) {
            &trimmed[pos+2..]
        } else {
            return None;
        }
    } else {
        return None;
    };

    let rest = rest.trim();
    let (text, link) = parse_markdown_link(rest);

    Some((indent, text, link))
}

fn build_nested_v2(flat: Vec<(usize, SummarySection, BookItem)>) -> Vec<BookItem> {
    if flat.is_empty() { return Vec::new(); }

    // Find the minimum indent of list items (to normalize)
    let min_list_indent = flat.iter()
        .filter(|(_, _, item)| matches!(item, BookItem::Chapter(_)))
        .map(|(indent, _, _)| *indent)
        .filter(|&i| i > 0)
        .min()
        .unwrap_or(2);

    // Normalize indents: 0 stays 0, others become level 1, 2, etc.
    let normalized: Vec<(usize, SummarySection, BookItem)> = flat.into_iter().map(|(indent, section, item)| {
        if indent == 0 {
            (0, section, item)
        } else {
            // Normalize to level based on steps
            let level = if min_list_indent > 0 { indent / min_list_indent } else { 1 };
            (level, section, item)
        }
    }).collect();

    // Build nested from normalized
    let mut result = Vec::new();
    let mut i = 0;

    while i < normalized.len() {
        let (indent, _, _) = &normalized[i];
        if *indent == 0 {
            let (_, _, item) = normalized[i].clone();
            if let BookItem::Chapter(mut ch) = item {
                i += 1;
                // Collect children (items with indent > 0)
                while i < normalized.len() && normalized[i].0 > 0 {
                    let end = find_same_level_end(&normalized[i..], normalized[i].0);
                    let children = build_nested_from_slice(&normalized[i..i+end]);
                    ch.sub_items.extend(children);
                    i += end;
                }
                result.push(BookItem::Chapter(ch));
            } else {
                result.push(item);
                i += 1;
            }
        } else {
            // Skip orphaned sub-items
            i += 1;
        }
    }

    result
}

fn find_same_level_end(items: &[(usize, SummarySection, BookItem)], level: usize) -> usize {
    // Find how many items at this level (and their children)
    let mut count = 0;
    let mut i = 0;
    while i < items.len() {
        if items[i].0 < level {
            break;
        }
        count += 1;
        i += 1;
    }
    count
}

fn build_nested_from_slice(items: &[(usize, SummarySection, BookItem)]) -> Vec<BookItem> {
    if items.is_empty() { return Vec::new(); }

    let base_level = items[0].0;
    let mut result = Vec::new();
    let mut i = 0;

    while i < items.len() {
        let (level, _, item) = &items[i];
        if *level == base_level {
            if let BookItem::Chapter(mut ch) = item.clone() {
                i += 1;
                // Collect children
                while i < items.len() && items[i].0 > base_level {
                    let end = find_same_level_end(&items[i..], items[i].0);
                    let children = build_nested_from_slice(&items[i..i+end]);
                    ch.sub_items.extend(children);
                    i += end;
                }
                result.push(BookItem::Chapter(ch));
            } else {
                result.push(item.clone());
                i += 1;
            }
        } else if *level > base_level {
            i += 1; // Skip - should have been consumed
        } else {
            break; // Lower level - stop
        }
    }

    result
}

/// Assign section numbers after parsing
pub fn number_book(book: &mut Book) {
    number_items(&mut book.sections, &[]);
}

fn number_items(items: &mut Vec<BookItem>, parent: &[u32]) {
    let mut counter = 0u32;
    for item in items.iter_mut() {
        if let BookItem::Chapter(ch) = item {
            if ch.is_prefix || ch.is_suffix {
                number_items(&mut ch.sub_items, parent);
            } else {
                counter += 1;
                let mut nums = parent.to_vec();
                nums.push(counter);
                ch.number = Some(SectionNumber(nums.clone()));
                number_items(&mut ch.sub_items, &nums);
            }
        }
    }
}

/// Set parent names for chapters
pub fn set_parent_names(book: &mut Book) {
    set_parent_names_in_items(&mut book.sections, &[]);
}

fn set_parent_names_in_items(items: &mut Vec<BookItem>, parents: &[String]) {
    for item in items.iter_mut() {
        if let BookItem::Chapter(ch) = item {
            ch.parent_names = parents.to_vec();
            let mut new_parents = parents.to_vec();
            new_parents.push(ch.name.clone());
            set_parent_names_in_items(&mut ch.sub_items, &new_parents);
        }
    }
}

/// Flatten book items into a list with chapter references
pub fn flatten_book<'a>(sections: &'a Vec<BookItem>) -> Vec<&'a Chapter> {
    let mut result = Vec::new();
    for item in sections {
        match item {
            BookItem::Chapter(ch) => {
                result.push(ch);
                result.extend(flatten_book(&ch.sub_items));
            }
            _ => {}
        }
    }
    result
}
