use std::collections::HashMap;
use crate::utils::{id_from_content, escape_html};

/// Convert markdown to HTML
/// Returns (html, headings_for_search)
pub fn markdown_to_html(content: &str, src_dir: Option<&std::path::Path>) -> String {
    let mut parser = MarkdownParser::new(content);
    parser.parse()
}

struct MarkdownParser<'a> {
    content: &'a str,
    heading_ids: HashMap<String, usize>,
}

impl<'a> MarkdownParser<'a> {
    fn new(content: &'a str) -> Self {
        MarkdownParser {
            content,
            heading_ids: HashMap::new(),
        }
    }

    fn get_heading_id(&mut self, text: &str) -> String {
        let base = id_from_content(text);
        let count = self.heading_ids.entry(base.clone()).or_insert(0);
        let id = if *count == 0 {
            base.clone()
        } else {
            format!("{}-{}", base, count)
        };
        *count += 1;
        id
    }

    fn parse(&mut self) -> String {
        let lines: Vec<&str> = self.content.lines().collect();
        let mut output = String::new();
        let mut i = 0;

        while i < lines.len() {
            let line = lines[i];

            // Blank line
            if line.trim().is_empty() {
                i += 1;
                continue;
            }

            // ATX Headings (# ## ### etc.)
            if let Some(heading) = parse_atx_heading(line) {
                let (level, text) = heading;
                let id = self.get_heading_id(&text);
                let html_text = self.render_inline(&text);
                output.push_str(&format!(
                    "<h{} id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h{}>\n",
                    level, id, id, html_text, level
                ));
                i += 1;
                continue;
            }

            // Setext-style headings
            if i + 1 < lines.len() {
                let next = lines[i + 1];
                if next.trim().chars().all(|c| c == '=') && !next.trim().is_empty() {
                    let text = line.trim();
                    let id = self.get_heading_id(text);
                    let html_text = self.render_inline(text);
                    output.push_str(&format!(
                        "<h1 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h1>\n",
                        id, id, html_text
                    ));
                    i += 2;
                    continue;
                }
                if next.trim().chars().all(|c| c == '-') && !next.trim().is_empty() && next.trim().len() >= 2 {
                    let text = line.trim();
                    let id = self.get_heading_id(text);
                    let html_text = self.render_inline(text);
                    output.push_str(&format!(
                        "<h2 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h2>\n",
                        id, id, html_text
                    ));
                    i += 2;
                    continue;
                }
            }

            // Horizontal rule
            {
                let t = line.trim();
                if (t.chars().all(|c| c == '-' || c == ' ') && t.chars().filter(|&c| c == '-').count() >= 3)
                    || (t.chars().all(|c| c == '*' || c == ' ') && t.chars().filter(|&c| c == '*').count() >= 3)
                    || (t.chars().all(|c| c == '_' || c == ' ') && t.chars().filter(|&c| c == '_').count() >= 3) {
                    if !t.contains('-') || t.replace('-', "").replace(' ', "").is_empty() {
                        // Make sure it's only horizontal rule chars
                        let only_dashes = t.chars().all(|c| c == '-' || c == ' ');
                        let only_stars = t.chars().all(|c| c == '*' || c == ' ');
                        let only_unders = t.chars().all(|c| c == '_' || c == ' ');
                        if (only_dashes || only_stars || only_unders) {
                            output.push_str("<hr />\n");
                            i += 1;
                            continue;
                        }
                    }
                }
            }

            // Fenced code block
            if line.trim_start().starts_with("```") || line.trim_start().starts_with("~~~") {
                let fence_char = if line.trim_start().starts_with("```") { '`' } else { '~' };
                let fence_str = if fence_char == '`' { "```" } else { "~~~" };
                let indent = line.len() - line.trim_start().len();
                let rest = line.trim_start().trim_start_matches(fence_char);
                let lang = rest.trim().to_string();
                let mut code_lines = Vec::new();
                i += 1;
                while i < lines.len() {
                    let cl = lines[i];
                    // Check for closing fence
                    let cl_trimmed = cl.trim_start();
                    if cl_trimmed.starts_with(fence_str) {
                        let remaining = cl_trimmed.trim_start_matches(fence_char).trim();
                        if remaining.is_empty() || !remaining.starts_with('`') {
                            i += 1;
                            break;
                        }
                    }
                    // Remove indent if any
                    let cl_stripped = if indent > 0 && cl.len() >= indent {
                        &cl[indent.min(cl.len())..]
                    } else {
                        cl
                    };
                    code_lines.push(cl_stripped.to_string());
                    i += 1;
                }
                let code_html = self.render_code_block(&lang, &code_lines);
                output.push_str(&code_html);
                continue;
            }

            // Indented code block (4 spaces or tab)
            if line.starts_with("    ") || line.starts_with("\t") {
                let mut code_lines = Vec::new();
                while i < lines.len() && (lines[i].starts_with("    ") || lines[i].starts_with("\t") || lines[i].trim().is_empty()) {
                    let cl = lines[i];
                    if cl.trim().is_empty() {
                        code_lines.push(String::new());
                    } else if cl.starts_with("    ") {
                        code_lines.push(cl[4..].to_string());
                    } else if cl.starts_with("\t") {
                        code_lines.push(cl[1..].to_string());
                    } else {
                        break;
                    }
                    i += 1;
                }
                // Remove trailing blank lines
                while code_lines.last().map_or(false, |l: &String| l.trim().is_empty()) {
                    code_lines.pop();
                }
                let code_content: String = code_lines.iter().map(|l| escape_html(l)).collect::<Vec<_>>().join("\n");
                output.push_str(&format!("<pre><code>{}\n</code></pre>\n", code_content));
                continue;
            }

            // HTML block (starts with HTML tag)
            if is_html_block_start(line) {
                let mut html_lines = Vec::new();
                // Collect until blank line (for type 1-5) or end
                let html_end_condition = get_html_block_end_condition(line);
                while i < lines.len() {
                    let hl = lines[i];
                    html_lines.push(hl);
                    i += 1;
                    if should_end_html_block(&html_lines, html_end_condition, hl) {
                        break;
                    }
                }
                output.push_str(&html_lines.join("\n"));
                output.push('\n');
                continue;
            }

            // Blockquote
            if line.trim_start().starts_with("> ") || line.trim_start() == ">" {
                let (bq_html, consumed) = self.parse_blockquote(&lines[i..]);
                output.push_str(&bq_html);
                i += consumed;
                continue;
            }

            // Table
            if is_table_line(&lines, i) {
                let (table_html, consumed) = parse_table(&lines[i..], self);
                output.push_str(&table_html);
                i += consumed;
                continue;
            }

            // Unordered list
            if is_unordered_list_item(line) {
                let (list_html, consumed) = self.parse_list(&lines[i..], false);
                output.push_str(&list_html);
                i += consumed;
                continue;
            }

            // Ordered list
            if is_ordered_list_item(line) {
                let (list_html, consumed) = self.parse_list(&lines[i..], true);
                output.push_str(&list_html);
                i += consumed;
                continue;
            }

            // Paragraph
            {
                let (para_html, consumed) = self.parse_paragraph(&lines[i..]);
                output.push_str(&para_html);
                i += consumed;
                continue;
            }
        }

        output
    }

    fn render_code_block(&mut self, lang: &str, code_lines: &[String]) -> String {
        // Parse language annotations
        let parts: Vec<&str> = lang.split(',').collect();
        let base_lang = parts[0].trim();

        let is_rust = base_lang == "rust";
        let has_ignore = parts.iter().any(|&p| p.trim() == "ignore");
        let has_no_run = parts.iter().any(|&p| p.trim() == "no_run");
        let has_no_playground = parts.iter().any(|&p| p.trim() == "no_playground");

        let is_playground = is_rust && !has_ignore && !has_no_playground;

        if is_rust && !has_ignore {
            // Process hidelines (# prefixed lines become boring)
            let mut processed_lines: Vec<String> = Vec::new();
            let mut has_main = false;
            let mut has_shebang = false;

            for line in code_lines {
                if line.trim() == "fn main() {" || line.trim().starts_with("fn main(") {
                    has_main = true;
                }
                if line.starts_with("#!") && !line.starts_with("# ") && !line.starts_with("##") {
                    has_shebang = true;
                }
            }

            // Check if any lines start with # (hidden lines)
            let has_hidden = code_lines.iter().any(|l| l.starts_with("# ") || l == "#" || (l.starts_with('#') && !l.starts_with("#!")));

            // Render the code
            let mut rendered = String::new();

            // If no main function, add boring wrapper
            let needs_main_wrapper = !has_main && !has_shebang;

            if needs_main_wrapper {
                rendered.push_str("<span class=\"boring\">#![allow(unused)]\n</span>");
                rendered.push_str("<span class=\"boring\">fn main() {\n</span>");
            }

            for line in code_lines {
                if (line.starts_with("# ") || line == "#" || (line.starts_with('#') && !line.starts_with("#!"))) {
                    // Hidden line - remove leading # and space
                    let hidden_content = if line.starts_with("# ") {
                        &line[2..]
                    } else if line == "#" {
                        ""
                    } else {
                        &line[1..]
                    };
                    rendered.push_str(&format!("<span class=\"boring\">{}\n</span>", escape_html(hidden_content)));
                } else {
                    rendered.push_str(&escape_html(line));
                    rendered.push('\n');
                }
            }

            if needs_main_wrapper {
                rendered.push_str("<span class=\"boring\">}</span>");
            }

            // Build language class
            let lang_class = if lang.is_empty() {
                "rust".to_string()
            } else {
                lang.replace(",", " ").split_whitespace()
                    .map(|p| p.trim())
                    .collect::<Vec<_>>()
                    .join(" ")
            };

            if is_playground {
                format!("<pre><pre class=\"playground\"><code class=\"language-{}\">{}</code></pre></pre>\n", 
                    lang_class, rendered)
            } else {
                format!("<pre><code class=\"language-{}\">{}</code></pre>\n",
                    lang_class, rendered)
            }
        } else {
            // Non-rust code block
            let code_content: String = code_lines.iter()
                .map(|l| escape_html(l))
                .collect::<Vec<_>>()
                .join("\n");

            if lang.is_empty() {
                format!("<pre><code>{}\n</code></pre>\n", code_content)
            } else {
                // Clean up language for class
                let lang_class = lang.replace(",", " ").split_whitespace()
                    .map(|p| p.trim())
                    .collect::<Vec<_>>()
                    .join(" ");
                format!("<pre><code class=\"language-{}\">{}\n</code></pre>\n", lang_class, code_content)
            }
        }
    }

    fn parse_blockquote<'b>(&mut self, lines: &'b [&'b str]) -> (String, usize) {
        let mut bq_content_lines = Vec::new();
        let mut consumed = 0;

        for line in lines {
            let trimmed = line.trim_start();
            if trimmed.starts_with("> ") {
                bq_content_lines.push(&trimmed[2..]);
                consumed += 1;
            } else if trimmed == ">" {
                bq_content_lines.push("");
                consumed += 1;
            } else if line.trim().is_empty() && consumed > 0 {
                // Blank line inside blockquote? Check if next line continues
                bq_content_lines.push("");
                consumed += 1;
                // If next line doesn't start with >, stop
                break;
            } else {
                break;
            }
        }

        // Remove trailing blank lines
        while bq_content_lines.last().map_or(false, |l| l.trim().is_empty()) {
            bq_content_lines.pop();
        }

        let inner_md = bq_content_lines.join("\n");
        let mut inner_parser = MarkdownParser::new("");
        // We need to parse the inner content
        let temp_content = bq_content_lines.iter().cloned().collect::<Vec<&str>>().join("\n");
        let mut temp_parser = MarkdownParser {
            content: "",
            heading_ids: HashMap::new(),
        };
        // Parse the inner content properly by treating blank lines as paragraph separators
        let inner_html = parse_blockquote_content(&bq_content_lines, &mut temp_parser);

        (format!("<blockquote>\n{}</blockquote>\n", inner_html), consumed)
    }

    fn parse_list<'b>(&mut self, lines: &'b [&'b str], ordered: bool) -> (String, usize) {
        parse_list_items(lines, ordered, self)
    }

    fn parse_paragraph<'b>(&mut self, lines: &'b [&'b str]) -> (String, usize) {
        let mut para_lines = Vec::new();
        let mut consumed = 0;

        for line in lines {
            if line.trim().is_empty() {
                consumed += 1;
                break;
            }
            // Check if this line starts a new block
            if consumed > 0 && (
                parse_atx_heading(line).is_some() ||
                line.trim_start().starts_with("```") ||
                line.trim_start().starts_with("~~~") ||
                line.trim_start().starts_with("> ") ||
                line.trim_start() == ">" ||
                is_unordered_list_item(line) ||
                is_ordered_list_item(line) ||
                is_html_block_start(line) ||
                (line.starts_with("    ") || line.starts_with("\t"))
            ) {
                break;
            }
            para_lines.push(*line);
            consumed += 1;
        }

        if para_lines.is_empty() {
            return (String::new(), consumed);
        }

        // Handle setext headings
        if para_lines.len() >= 2 {
            let last = para_lines.last().unwrap();
            if last.trim().chars().all(|c| c == '=') && !last.trim().is_empty() {
                let text = para_lines[..para_lines.len()-1].join("\n").trim().to_string();
                let id = self.get_heading_id(&text);
                let html_text = self.render_inline(&text);
                return (format!("<h1 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h1>\n", id, id, html_text), consumed);
            }
            if last.trim().chars().all(|c| c == '-') && !last.trim().is_empty() && last.trim().len() >= 2 {
                let text = para_lines[..para_lines.len()-1].join("\n").trim().to_string();
                let id = self.get_heading_id(&text);
                let html_text = self.render_inline(&text);
                return (format!("<h2 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h2>\n", id, id, html_text), consumed);
            }
        }

        let text = para_lines.join("\n");
        let rendered = self.render_inline(&text);

        (format!("<p>{}</p>\n", rendered), consumed)
    }

    pub fn render_inline(&self, text: &str) -> String {
        render_inline_markup(text)
    }
}

fn parse_blockquote_content(lines: &[&str], parser: &mut MarkdownParser) -> String {
    // Split on blank lines and parse each segment
    let content = lines.join("\n");
    // Re-parse the content
    let mut sub_parser = MarkdownParser {
        content: &content,
        heading_ids: HashMap::new(),
    };
    // We need a new owned string
    let content_owned = content.clone();
    let mut sp = MarkdownParser {
        content: "",
        heading_ids: HashMap::new(),
    };
    parse_block_content_str(&content_owned, &mut sp)
}

fn parse_block_content_str(content: &str, parser: &mut MarkdownParser) -> String {
    // Mini re-entrant parser for blockquote content
    let lines: Vec<&str> = content.lines().collect();
    let mut output = String::new();
    let mut i = 0;

    // Group into paragraphs separated by blank lines
    while i < lines.len() {
        let line = lines[i];

        if line.trim().is_empty() {
            i += 1;
            continue;
        }

        // ATX heading
        if let Some((level, text)) = parse_atx_heading(line) {
            let id = id_from_content(&text);
            let html_text = render_inline_markup(&text);
            output.push_str(&format!("<h{} id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h{}>\n",
                level, id, id, html_text, level));
            i += 1;
            continue;
        }

        // Collect paragraph
        let mut para = Vec::new();
        while i < lines.len() && !lines[i].trim().is_empty() {
            para.push(lines[i]);
            i += 1;
        }

        if !para.is_empty() {
            let text = para.join("\n");
            let rendered = render_inline_markup(&text);
            output.push_str(&format!("<p>{}</p>\n", rendered));
        }
    }

    output
}

fn parse_atx_heading(line: &str) -> Option<(u8, String)> {
    let trimmed = line.trim_start();
    if !trimmed.starts_with('#') { return None; }

    let mut level = 0u8;
    for c in trimmed.chars() {
        if c == '#' { level += 1; } else { break; }
    }

    if level > 6 { return None; }

    // After #s must be space or end
    let rest = &trimmed[level as usize..];
    if !rest.is_empty() && !rest.starts_with(' ') && !rest.starts_with('\t') {
        return None;
    }

    let text = rest.trim().trim_end_matches('#').trim().to_string();
    Some((level, text))
}

fn is_html_block_start(line: &str) -> bool {
    let t = line.trim_start();
    if t.starts_with('<') {
        // Check for HTML tags
        if t.starts_with("</") || t.starts_with("<!--") {
            return true;
        }
        // Check for block-level HTML tags
        let tag_end = t[1..].find(|c: char| !c.is_alphanumeric()).unwrap_or(t.len()-1);
        let tag = &t[1..tag_end+1].to_lowercase();
        let block_tags = ["address", "article", "aside", "base", "basefont", "blockquote", 
                         "body", "caption", "center", "col", "colgroup", "dd", "details", 
                         "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure",
                         "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6",
                         "head", "header", "hr", "html", "iframe", "legend", "li", "link",
                         "main", "menu", "menuitem", "meta", "nav", "noframes", "ol", "optgroup",
                         "option", "p", "param", "search", "section", "summary", "table", "tbody",
                         "td", "tfoot", "th", "thead", "title", "tr", "track", "ul"];
        return block_tags.contains(&tag.as_str());
    }
    false
}

fn get_html_block_end_condition(line: &str) -> u8 {
    // Simple: end on blank line
    6
}

fn should_end_html_block(lines: &[&str], condition: u8, current: &str) -> bool {
    // Type 6: end on blank line
    current.trim().is_empty()
}

fn is_table_line(lines: &[&str], i: usize) -> bool {
    if i + 1 >= lines.len() { return false; }
    let line = lines[i];
    let next = lines[i + 1];

    // Table header requires a separator line
    let is_separator = next.trim().contains('|') && 
        next.trim().chars().all(|c| c == '|' || c == '-' || c == ':' || c == ' ');

    line.contains('|') && is_separator
}

fn parse_table<'a>(lines: &[&'a str], parser: &mut MarkdownParser) -> (String, usize) {
    if lines.len() < 2 { return (String::new(), 0); }

    let header_line = lines[0];
    let sep_line = lines[1];

    // Parse header cells
    let headers: Vec<&str> = split_table_cells(header_line);

    // Parse alignment from separator
    let alignments: Vec<&str> = split_table_cells(sep_line);

    let mut html = String::from("<div class=\"table-wrapper\"><table><thead><tr>");
    for h in &headers {
        html.push_str(&format!("<th>{}</th>", parser.render_inline(h.trim())));
    }
    html.push_str("</tr></thead><tbody>\n");

    let mut consumed = 2;
    for line in &lines[2..] {
        if line.trim().is_empty() { break; }
        if !line.contains('|') { break; }

        let cells = split_table_cells(line);
        html.push_str("<tr>");
        for (idx, cell) in cells.iter().enumerate() {
            if idx < headers.len() {
                html.push_str(&format!("<td>{}</td>", parser.render_inline(cell.trim())));
            }
        }
        html.push_str("</tr>\n");
        consumed += 1;
    }

    html.push_str("</tbody></table>\n</div>\n");
    (html, consumed)
}

fn split_table_cells(line: &str) -> Vec<&str> {
    let line = line.trim();
    let line = if line.starts_with('|') { &line[1..] } else { line };
    let line = if line.ends_with('|') { &line[..line.len()-1] } else { line };
    line.split('|').collect()
}

fn is_unordered_list_item(line: &str) -> bool {
    let t = line.trim_start();
    t.starts_with("- ") || t.starts_with("* ") || t.starts_with("+ ")
}

fn is_ordered_list_item(line: &str) -> bool {
    let t = line.trim_start();
    // 1. or 1) pattern
    let mut chars = t.chars();
    let mut digit_count = 0;
    while let Some(c) = chars.next() {
        if c.is_ascii_digit() {
            digit_count += 1;
        } else if (c == '.' || c == ')') && digit_count > 0 {
            let rest: String = chars.collect();
            return rest.starts_with(' ') || rest.is_empty();
        } else {
            return false;
        }
    }
    false
}

fn parse_list_items<'a>(lines: &[&'a str], ordered: bool, parser: &mut MarkdownParser) -> (String, usize) {
    let list_tag = if ordered { "ol" } else { "ul" };
    let mut html = format!("<{}>\n", list_tag);
    let mut consumed = 0;

    // Determine the base indent
    let base_indent = lines[0].len() - lines[0].trim_start().len();

    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        let indent = line.len() - line.trim_start().len();

        if line.trim().is_empty() {
            // Blank line - might be between items or end of list
            // Look ahead to see if list continues
            if i + 1 < lines.len() {
                let next = lines[i + 1];
                let next_indent = next.len() - next.trim_start().len();
                if next_indent >= base_indent && (is_unordered_list_item(next) || is_ordered_list_item(next)) {
                    // List continues
                    i += 1;
                    consumed += 1;
                    continue;
                } else if next_indent > base_indent && !next.trim().is_empty() {
                    // Continuation of previous item
                    i += 1;
                    consumed += 1;
                    continue;
                }
            }
            consumed += 1;
            break;
        }

        if indent < base_indent {
            break;
        }

        if indent == base_indent && (is_unordered_list_item(line) || is_ordered_list_item(line)) {
            // Parse this list item
            let (item_content, item_rest_start) = extract_list_item_start(line);
            let mut item_lines = vec![item_rest_start.to_string()];
            i += 1;
            consumed += 1;

            // Collect continuation lines and sub-items
            while i < lines.len() {
                let next_line = lines[i];
                if next_line.trim().is_empty() {
                    // Blank line might be inside a loose list item
                    if i + 1 < lines.len() {
                        let nn = lines[i + 1];
                        let nn_indent = nn.len() - nn.trim_start().len();
                        if nn_indent > base_indent {
                            item_lines.push(String::new());
                            item_lines.push(nn[base_indent + 2..].to_string());
                            i += 2;
                            consumed += 2;
                            continue;
                        } else if nn_indent == base_indent && (is_unordered_list_item(nn) || is_ordered_list_item(nn)) {
                            // Next sibling item
                            item_lines.push(String::new()); // blank between items
                            break;
                        }
                    }
                    item_lines.push(String::new());
                    i += 1;
                    consumed += 1;
                    break;
                }
                let next_indent = next_line.len() - next_line.trim_start().len();
                if next_indent <= base_indent {
                    break;
                }
                // This is a sub-item or continuation
                let stripped = if next_indent > base_indent {
                    let spaces = " ".repeat(base_indent + 2);
                    if next_line.starts_with(&spaces) {
                        next_line[base_indent + 2..].to_string()
                    } else {
                        next_line[next_indent..].to_string()
                    }
                } else {
                    next_line.trim_start().to_string()
                };
                item_lines.push(stripped);
                i += 1;
                consumed += 1;
            }

            // Process item_lines to render
            let item_html = render_list_item_content(&item_lines, parser);
            html.push_str(&format!("<li>{}</li>", item_html));
            html.push('\n');
        } else {
            break;
        }
    }

    html.push_str(&format!("</{}>\n", list_tag));
    (html, consumed)
}

fn extract_list_item_start(line: &str) -> (String, &str) {
    let t = line.trim_start();
    if t.starts_with("- ") || t.starts_with("* ") || t.starts_with("+ ") {
        (t[..1].to_string(), &t[2..])
    } else {
        // Ordered: "1. " or "1) "
        let pos = t.find(|c: char| c == '.' || c == ')').unwrap_or(0);
        let rest = &t[pos+1..].trim_start_matches(' ');
        (t[..pos+1].to_string(), rest)
    }
}

fn render_list_item_content(lines: &[String], parser: &mut MarkdownParser) -> String {
    // Check if this is a "loose" list item (has blank lines)
    let is_loose = lines.iter().any(|l| l.trim().is_empty());

    if !is_loose && lines.len() == 1 {
        // Simple single-line item
        return parser.render_inline(lines[0].trim());
    }

    // Multi-line or loose item
    let content = lines.join("\n");
    let mut result = String::new();

    if is_loose {
        // Parse as block content
        result = parse_block_content_str(&content, parser);
    } else {
        // Check for sub-lists
        let has_sublist = lines.iter().any(|l| is_unordered_list_item(l) || is_ordered_list_item(l));
        if has_sublist {
            // Mix of text and sub-list
            let sub_lines: Vec<&str> = lines.iter().map(|s| s.as_str()).collect();
            let mut i = 0;
            while i < sub_lines.len() {
                let l = sub_lines[i];
                if l.trim().is_empty() {
                    i += 1;
                    continue;
                }
                if is_unordered_list_item(l) {
                    let (sub_html, consumed) = parse_list_items(&sub_lines[i..], false, parser);
                    result.push_str(&sub_html);
                    i += consumed;
                } else if is_ordered_list_item(l) {
                    let (sub_html, consumed) = parse_list_items(&sub_lines[i..], true, parser);
                    result.push_str(&sub_html);
                    i += consumed;
                } else {
                    result.push_str(&parser.render_inline(l.trim()));
                    i += 1;
                }
            }
        } else {
            // Just render as inline
            let text = lines.iter()
                .filter(|l| !l.trim().is_empty())
                .cloned()
                .collect::<Vec<_>>()
                .join("\n");
            result = parser.render_inline(&text);
        }
    }

    result
}

/// Render inline markdown markup
pub fn render_inline_markup(text: &str) -> String {
    let mut result = String::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        // Escape sequences
        if c == '\\' && i + 1 < chars.len() {
            let next = chars[i + 1];
            if "\\`*_{}[]()#+-.!|".contains(next) {
                result.push(match next {
                    '&' => { result.push_str("&amp;"); i += 2; continue; }
                    '<' => { result.push_str("&lt;"); i += 2; continue; }
                    '>' => { result.push_str("&gt;"); i += 2; continue; }
                    _ => next,
                });
                i += 2;
                continue;
            }
        }

        // HTML entities pass through
        if c == '&' {
            // Check for entity
            let rest: String = chars[i..].iter().collect();
            if let Some(semi) = rest.find(';') {
                let entity = &rest[..semi+1];
                if is_valid_entity(entity) {
                    result.push_str(entity);
                    i += entity.chars().count();
                    continue;
                }
            }
            result.push_str("&amp;");
            i += 1;
            continue;
        }

        // HTML passthrough
        if c == '<' {
            let rest: String = chars[i..].iter().collect();
            if let Some(end) = rest.find('>') {
                let tag = &rest[..end+1];
                // Check if it's a valid HTML tag or autolink
                if is_inline_html_tag(tag) || is_autolink(tag) {
                    result.push_str(tag);
                    i += tag.chars().count();
                    continue;
                }
            }
            result.push_str("&lt;");
            i += 1;
            continue;
        }

        // Escape HTML chars  
        if c == '>' {
            result.push_str("&gt;");
            i += 1;
            continue;
        }

        // Code span
        if c == '`' {
            // Count backticks
            let mut bt_count = 0;
            while i + bt_count < chars.len() && chars[i + bt_count] == '`' {
                bt_count += 1;
            }
            let bt_str: String = std::iter::repeat('`').take(bt_count).collect();
            let search_start = i + bt_count;
            // Find matching closing backticks
            let remaining: String = chars[search_start..].iter().collect();
            if let Some(close_pos) = remaining.find(&bt_str) {
                let code_content = &remaining[..close_pos];
                // Collapse whitespace
                let collapsed = code_content.trim().replace('\n', " ");
                result.push_str(&format!("<code>{}</code>", escape_html(&collapsed)));
                i = search_start + close_pos + bt_count;
                continue;
            }
            // No matching close, output literal
            result.push_str(&bt_str);
            i += bt_count;
            continue;
        }

        // Strikethrough ~~text~~
        if c == '~' && i + 1 < chars.len() && chars[i + 1] == '~' {
            let remaining: String = chars[i+2..].iter().collect();
            if let Some(end) = remaining.find("~~") {
                let content = &remaining[..end];
                let rendered = render_inline_markup(content);
                result.push_str(&format!("<del>{}</del>", rendered));
                i += 2 + end + 2;
                continue;
            }
        }

        // Bold and italic
        if c == '*' || c == '_' {
            let marker = c;
            // Count markers
            let mut mc = 0;
            while i + mc < chars.len() && chars[i + mc] == marker {
                mc += 1;
            }

            if mc >= 3 {
                // Try ***text*** - bold italic
                let rest: String = chars[i+3..].iter().collect();
                let close_str: String = std::iter::repeat(marker).take(3).collect();
                if let Some(end) = rest.find(&close_str) {
                    let content = &rest[..end];
                    let rendered = render_inline_markup(content);
                    result.push_str(&format!("<em><strong>{}</strong></em>", rendered));
                    i += 3 + end + 3;
                    continue;
                }
            }

            if mc >= 2 {
                // Try **text** - bold
                let rest: String = chars[i+2..].iter().collect();
                let close_str: String = std::iter::repeat(marker).take(2).collect();
                if let Some(end) = rest.find(&close_str) {
                    // Make sure it's not just spaces
                    let content = &rest[..end];
                    if !content.is_empty() {
                        let rendered = render_inline_markup(content);
                        result.push_str(&format!("<strong>{}</strong>", rendered));
                        i += 2 + end + 2;
                        continue;
                    }
                }
            }

            if mc >= 1 {
                // Try *text* - italic
                let rest: String = chars[i+1..].iter().collect();
                if let Some(end) = rest.find(marker) {
                    let content = &rest[..end];
                    if !content.is_empty() && !content.starts_with(' ') && !content.ends_with(' ') {
                        let rendered = render_inline_markup(content);
                        result.push_str(&format!("<em>{}</em>", rendered));
                        i += 1 + end + 1;
                        continue;
                    }
                }
            }

            // Output literal
            result.push(escape_char(c));
            i += 1;
            continue;
        }

        // Links and images
        if c == '!' && i + 1 < chars.len() && chars[i + 1] == '[' {
            // Image
            if let Some((alt, href, title, end)) = parse_link_or_image(&chars, i + 1) {
                let title_attr = if let Some(t) = title {
                    format!(" title=\"{}\"", escape_html(&t))
                } else {
                    String::new()
                };
                result.push_str(&format!("<img src=\"{}\" alt=\"{}\"{}  />", 
                    escape_html(&href), escape_html(&alt), title_attr));
                // Fix: remove extra space
                result = result.replace("\"  />", "\" />");
                i = end;
                continue;
            }
            result.push('!');
            i += 1;
            continue;
        }

        if c == '[' {
            // Link
            if let Some((text, href, title, end)) = parse_link_or_image(&chars, i) {
                let rendered_text = render_inline_markup(&text);
                // Convert .md links to .html
                let href = convert_link(&href);
                let title_attr = if let Some(t) = title {
                    format!(" title=\"{}\"", escape_html(&t))
                } else {
                    String::new()
                };
                result.push_str(&format!("<a href=\"{}\"{}>{}</a>", 
                    escape_html(&href), title_attr, rendered_text));
                i = end;
                continue;
            }
        }

        // Default - output char with HTML escaping
        result.push_str(&match c {
            '&' => "&amp;".to_string(),
            '<' => "&lt;".to_string(),
            '>' => "&gt;".to_string(),
            '"' => "\"".to_string(), // Don't escape quotes in inline text
            _ => c.to_string(),
        });
        i += 1;
    }

    result
}

fn escape_char(c: char) -> char { c }

fn is_valid_entity(s: &str) -> bool {
    s.starts_with("&") && s.ends_with(";") && s.len() > 2
}

fn is_inline_html_tag(s: &str) -> bool {
    // Simple check for inline HTML tags
    s.starts_with('<') && s.ends_with('>')
}

fn is_autolink(s: &str) -> bool {
    s.starts_with('<') && s.ends_with('>') && 
    (s.contains("://") || s.contains('@'))
}

fn convert_link(href: &str) -> String {
    if href.ends_with(".md") && !href.starts_with("http") && !href.starts_with('#') {
        format!("{}.html", &href[..href.len()-3])
    } else {
        href.to_string()
    }
}

fn parse_link_or_image(chars: &[char], start: usize) -> Option<(String, String, Option<String>, usize)> {
    // Parse [text](href "title") starting at [ position
    if start >= chars.len() || chars[start] != '[' { return None; }

    // Find matching ]
    let mut depth = 0;
    let mut i = start;
    let text_start = start + 1;
    let mut text_end = None;

    while i < chars.len() {
        match chars[i] {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 {
                    text_end = Some(i);
                    break;
                }
            }
            _ => {}
        }
        i += 1;
    }

    let text_end = text_end?;
    let text: String = chars[text_start..text_end].iter().collect();

    // Check for (href)
    let after = text_end + 1;
    if after >= chars.len() || chars[after] != '(' {
        return None;
    }

    // Find matching )
    let href_start = after + 1;
    let mut paren_depth = 1;
    let mut j = href_start;
    while j < chars.len() && paren_depth > 0 {
        match chars[j] {
            '(' => paren_depth += 1,
            ')' => {
                paren_depth -= 1;
                if paren_depth == 0 { break; }
            }
            _ => {}
        }
        j += 1;
    }

    if j >= chars.len() { return None; }

    let href_content: String = chars[href_start..j].iter().collect();

    // Parse href and optional title
    let (href, title) = parse_href_and_title(&href_content);

    Some((text, href, title, j + 1))
}

fn parse_href_and_title(s: &str) -> (String, Option<String>) {
    let s = s.trim();

    // Handle <href> form
    if s.starts_with('<') {
        if let Some(end) = s.find('>') {
            let href = s[1..end].to_string();
            return (href, None);
        }
    }

    // Split on whitespace before title
    let mut href = String::new();
    let mut title = None;

    let mut in_angle = false;
    let mut in_title = false;
    let mut title_char = '"';
    let mut title_content = String::new();
    let mut href_done = false;

    let chars: Vec<char> = s.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];
        if !href_done {
            if c == '"' || c == '\'' {
                href_done = true;
                in_title = true;
                title_char = c;
                i += 1;
                continue;
            } else if c == ' ' || c == '\t' {
                href_done = true;
                i += 1;
                continue;
            } else {
                href.push(c);
            }
        } else if in_title {
            if c == title_char {
                title = Some(title_content.clone());
                break;
            } else {
                title_content.push(c);
            }
        } else {
            if c == '"' || c == '\'' {
                in_title = true;
                title_char = c;
            }
        }
        i += 1;
    }

    (href.trim().to_string(), title)
}

