    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];
        if !href_done {
            if c == '"' || c == '\'' {
                href_done = true;
                in_title = true;
                title_char = c;
                i += 1;
                continue;
            } else if c == ' ' || c == '\t' {
