use std::path::{Path, PathBuf};
use crate::book::{Book, BookItem, Chapter};

/// Apply preprocessors to the book
pub fn preprocess(book: &mut Book, src_dir: &Path, use_defaults: bool) -> Result<(), String> {
    if use_defaults {
        // Apply index preprocessor: README.md -> index.md treatment
        apply_index_preprocessor(book);
        // Apply links preprocessor: {{#include ...}} etc.
        apply_links_preprocessor(book, src_dir)?;
    }
    Ok(())
}

/// Index preprocessor: renames README.md references to index.md
fn apply_index_preprocessor(book: &mut Book) {
    process_index_items(&mut book.sections);
}

fn process_index_items(items: &mut Vec<BookItem>) {
    for item in items.iter_mut() {
        if let BookItem::Chapter(ch) = item {
            if let Some(path) = &ch.path {
                if path.file_name().map_or(false, |n| n == "README.md") {
                    // Convert README.md to index.md
                    let new_path = path.with_file_name("index.md");
                    ch.path = Some(new_path);
                }
            }
            if let Some(sp) = &ch.source_path {
                // Keep source_path as README.md for reading
                // but path (for output) should be index.md
            }
            process_index_items(&mut ch.sub_items);
        }
    }
}

/// Links preprocessor: handles {{#include}}, {{#playground}}, {{#rustdoc_include}}
pub fn apply_links_preprocessor(book: &mut Book, src_dir: &Path) -> Result<(), String> {
    process_links_items(&mut book.sections, src_dir)
}

fn process_links_items(items: &mut Vec<BookItem>, src_dir: &Path) -> Result<(), String> {
    for item in items.iter_mut() {
        if let BookItem::Chapter(ch) = item {
            if !ch.content.is_empty() {
                let chapter_dir = if let Some(sp) = &ch.source_path {
                    src_dir.join(sp).parent().map(|p| p.to_path_buf())
                        .unwrap_or_else(|| src_dir.to_path_buf())
                } else {
                    src_dir.to_path_buf()
                };
                ch.content = process_links_in_content(&ch.content, &chapter_dir)?;
            }
            process_links_items(&mut ch.sub_items, src_dir)?;
        }
    }
    Ok(())
}

fn process_links_in_content(content: &str, chapter_dir: &Path) -> Result<String, String> {
    let mut result = String::new();
    let mut remaining = content;

    while let Some(start) = remaining.find("{{#") {
        result.push_str(&remaining[..start]);
        remaining = &remaining[start..];

        if let Some(end) = remaining.find("}}") {
            let directive = &remaining[..end+2];
            let inner = &directive[3..directive.len()-2].trim();

            let replacement = process_directive(inner, chapter_dir)?;
            result.push_str(&replacement);
            remaining = &remaining[end+2..];
        } else {
            // No closing }}, output as-is
            result.push_str(&remaining[..3]);
            remaining = &remaining[3..];
        }
    }

    result.push_str(remaining);
    Ok(result)
}

fn process_directive(directive: &str, chapter_dir: &Path) -> Result<String, String> {
    if directive.starts_with("include") {
        let args = directive["include".len()..].trim();
        process_include(args, chapter_dir)
    } else if directive.starts_with("rustdoc_include") {
        let args = directive["rustdoc_include".len()..].trim();
        process_rustdoc_include(args, chapter_dir)
    } else if directive.starts_with("playground") {
        let args = directive["playground".len()..].trim();
        process_playground(args, chapter_dir)
    } else {
        // Unknown directive - pass through
        Ok(format!("{{{{#{}}}}}", directive))
    }
}

fn process_include(args: &str, chapter_dir: &Path) -> Result<String, String> {
    // Parse: filename or filename:start or filename:start:end or filename::end
    let (file_path, range) = parse_include_args(args);
    let full_path = chapter_dir.join(file_path);

    let content = std::fs::read_to_string(&full_path)
        .map_err(|e| format!("Failed to read include file {:?}: {}", full_path, e))?;

    let lines: Vec<&str> = content.lines().collect();
    let selected = apply_line_range(&lines, range);

    Ok(selected.join("\n"))
}

fn process_rustdoc_include(args: &str, chapter_dir: &Path) -> Result<String, String> {
    // Same as include but wraps in code block markers
    let (file_path, range) = parse_include_args(args);
    let full_path = chapter_dir.join(file_path);

    let content = std::fs::read_to_string(&full_path)
        .map_err(|e| format!("Failed to read rustdoc_include file {:?}: {}", full_path, e))?;

    let lines: Vec<&str> = content.lines().collect();

    // For rustdoc_include, only include lines that are NOT in the range (hide others with #)
    // Actually: selected lines are shown, others are prefixed with # (hidden)
    let (start, end) = match range {
        Some((s, e)) => (s, e),
        None => (0, lines.len()),
    };

    let mut result_lines = Vec::new();
    for (idx, line) in lines.iter().enumerate() {
        if idx >= start && idx < end {
            result_lines.push(line.to_string());
        } else {
            result_lines.push(format!("# {}", line));
        }
    }

    Ok(result_lines.join("\n"))
}

fn process_playground(args: &str, chapter_dir: &Path) -> Result<String, String> {
    // {{#playground file.rs editable}} -> renders as a rust code block
    let parts: Vec<&str> = args.splitn(2, ' ').collect();
    let file_path = parts[0];
    let attributes = if parts.len() > 1 { parts[1] } else { "" };

    let full_path = chapter_dir.join(file_path);
    let content = std::fs::read_to_string(&full_path)
        .map_err(|e| format!("Failed to read playground file {:?}: {}", full_path, e))?;

    // Return as a rust code block with attributes
    let lang = if attributes.is_empty() {
        "rust".to_string()
    } else {
        format!("rust,{}", attributes)
    };

    Ok(format!("```{}\n{}\n```", lang, content.trim_end()))
}

fn parse_include_args(args: &str) -> (&str, Option<(usize, usize)>) {
    if let Some(colon_pos) = args.find(':') {
        let file = &args[..colon_pos];
        let range_str = &args[colon_pos+1..];

        let range = parse_range(range_str);
        (file, Some(range))
    } else {
        (args, None)
    }
}

fn parse_range(range_str: &str) -> (usize, usize) {
    let parts: Vec<&str> = range_str.splitn(2, ':').collect();

    let start = parts[0].trim().parse::<usize>().map(|n| n.saturating_sub(1)).unwrap_or(0);
    let end = if parts.len() > 1 {
        parts[1].trim().parse::<usize>().unwrap_or(usize::MAX)
    } else {
        start + 1
    };

    (start, end)
}

fn apply_line_range<'a>(lines: &[&'a str], range: Option<(usize, usize)>) -> Vec<&'a str> {
    match range {
        None => lines.to_vec(),
        Some((start, end)) => {
            let end = end.min(lines.len());
            let start = start.min(end);
            lines[start..end].to_vec()
        }
    }
}
