fn process_links_items(items: &mut Vec<BookItem>, src_dir: &Path) -> Result<(), String> {
    for item in items.iter_mut() {
        if let BookItem::Chapter(ch) = item {
            if !ch.content.is_empty() {
                let chapter_dir = if let Some(sp) = &ch.source_path {
                    src_dir.join(sp).parent().map(|p| p.to_path_buf())
                        .unwrap_or_else(|| src_dir.to_path_buf())
