use std::collections::HashMap;
use crate::book::{Book, BookItem, Chapter};

#[derive(Debug)]
pub struct SearchIndex {
    pub doc_urls: Vec<String>,
    pub documents: Vec<SearchDocument>,
    pub search_options: SearchOptions,
}

#[derive(Debug)]
pub struct SearchDocument {
    pub id: usize,
    pub title: String,
    pub body: String,
    pub breadcrumbs: String,
    pub url: String,
}

#[derive(Debug)]
pub struct SearchOptions {
    pub limit_results: u32,
    pub teaser_word_count: u32,
    pub use_boolean_and: bool,
    pub boost_title: u32,
    pub boost_hierarchy: u32,
    pub boost_paragraph: u32,
    pub expand: bool,
}

impl SearchIndex {
    pub fn new(options: SearchOptions) -> Self {
        SearchIndex {
            doc_urls: Vec::new(),
            documents: Vec::new(),
            search_options: options,
        }
    }

    pub fn add_document(&mut self, title: &str, body: &str, breadcrumbs: &str, url: &str) {
        let id = self.documents.len();
        self.doc_urls.push(url.to_string());
        self.documents.push(SearchDocument {
            id,
            title: title.to_string(),
            body: body.to_string(),
            breadcrumbs: breadcrumbs.to_string(),
            url: url.to_string(),
        });
    }

    /// Generate the searchindex.js file content
    pub fn generate_js(&self) -> String {
        // Generate the elasticlunr-compatible search index
        let index = self.build_index();
        let json = self.to_json(&index);

        format!("window.search = Object.assign(window.search, JSON.parse({}));", 
                escape_js_string(&json))
    }

    fn build_index(&self) -> IndexData {
        let mut doc_store = DocumentStore::new();
        let mut inv_index = InvertedIndex::new();

        for doc in &self.documents {
            let doc_info = DocInfo {
                title: word_count(&doc.title) as u32,
                body: word_count(&doc.body) as u32,
                breadcrumbs: word_count(&doc.breadcrumbs) as u32,
            };
            doc_store.add(doc.id.to_string(), doc.clone(), doc_info);

            // Index words
            let id_str = doc.id.to_string();
            index_field(&mut inv_index, "title", &doc.title, &id_str);
            index_field(&mut inv_index, "body", &doc.body, &id_str);
            index_field(&mut inv_index, "breadcrumbs", &doc.breadcrumbs, &id_str);
        }

        IndexData { doc_store, inv_index }
    }

    fn to_json(&self, index: &IndexData) -> String {
        let opts = &self.search_options;

        // Generate doc_urls array
        let doc_urls_json = format!("[{}]", 
            self.doc_urls.iter()
                .map(|u| format!("\"{}\"", escape_json_str(u)))
                .collect::<Vec<_>>()
                .join(",")
        );

        // Generate document store
        let doc_info_json = generate_doc_info_json(&index.doc_store);
        let docs_json = generate_docs_json(&index.doc_store);

        // Generate inverted index
        let title_index = generate_field_index(&index.inv_index, "title");
        let body_index = generate_field_index(&index.inv_index, "body");
        let breadcrumbs_index = generate_field_index(&index.inv_index, "breadcrumbs");

        let bool_str = if opts.use_boolean_and { "\"AND\"" } else { "\"OR\"" };

        format!(
            r#"{{"doc_urls":{},"index":{{"documentStore":{{"docInfo":{},"docs":{},"length":{},"save":true}},"fields":["title","body","breadcrumbs"],"index":{{"body":{{"root":{}}},"breadcrumbs":{{"root":{}}},"title":{{"root":{}}}}},"lang":"English","pipeline":["trimmer","stopWordFilter","stemmer"],"ref":"id","version":"0.9.5"}},"results_options":{{"limit_results":{},"teaser_word_count":{}}},"search_options":{{"bool":{},"expand":{},"fields":{{"body":{{"boost":{}}},"breadcrumbs":{{"boost":{}}},"title":{{"boost":{}}}}}}}}}"#,
            doc_urls_json,
            doc_info_json,
            docs_json,
            self.documents.len(),
            body_index,
            breadcrumbs_index,
            title_index,
            opts.limit_results,
            opts.teaser_word_count,
            bool_str,
            if opts.expand { "true" } else { "false" },
            opts.boost_paragraph,
            opts.boost_hierarchy,
            opts.boost_title,
        )
    }
}

fn word_count(s: &str) -> usize {
    s.split_whitespace().count()
}

fn index_field(inv_index: &mut InvertedIndex, field: &str, text: &str, doc_id: &str) {
    let tokens = tokenize(text);
    let mut term_counts: HashMap<String, f64> = HashMap::new();

    for token in &tokens {
        *term_counts.entry(token.clone()).or_insert(0.0) += 1.0;
    }

    let total = tokens.len() as f64;
    for (term, count) in term_counts {
        let tf = if total > 0.0 { count.sqrt() } else { 0.0 };
        inv_index.add(field, &term, doc_id, tf);
    }
}

fn tokenize(text: &str) -> Vec<String> {
    // Simple tokenizer: split on whitespace and punctuation, lowercase
    let stripped = strip_html_tags(text);
    stripped.split(|c: char| !c.is_alphanumeric())
        .filter(|t| !t.is_empty() && t.len() > 1)
        .map(|t| t.to_lowercase())
        .collect()
}

fn strip_html_tags(text: &str) -> String {
    let mut result = String::new();
    let mut in_tag = false;
    for c in text.chars() {
        if c == '<' { in_tag = true; }
        else if c == '>' { in_tag = false; }
        else if !in_tag { result.push(c); }
    }
    result
}

fn escape_json_str(s: &str) -> String {
    s.replace('\\', "\\\\")
     .replace('"', "\\\"")
     .replace('\n', "\\n")
     .replace('\r', "\\r")
     .replace('\t', "\\t")
}

fn escape_js_string(s: &str) -> String {
    let escaped = s.replace('\\', "\\\\")
                   .replace('\'', "\\'");
    format!("'{}'", escaped)
}

// Simplified data structures for the index

struct DocumentStore {
    doc_info: HashMap<String, DocInfo>,
    docs: HashMap<String, SearchDocument>,
}

#[derive(Debug)]
struct DocInfo {
    title: u32,
    body: u32,
    breadcrumbs: u32,
}

impl DocumentStore {
    fn new() -> Self {
        DocumentStore {
            doc_info: HashMap::new(),
            docs: HashMap::new(),
        }
    }

    fn add(&mut self, id: String, doc: SearchDocument, info: DocInfo) {
        self.doc_info.insert(id.clone(), info);
        self.docs.insert(id, doc);
    }
}

struct InvertedIndex {
    // field -> term -> doc_id -> tf
    data: HashMap<String, HashMap<String, HashMap<String, f64>>>,
}

impl InvertedIndex {
    fn new() -> Self {
        InvertedIndex { data: HashMap::new() }
    }

    fn add(&mut self, field: &str, term: &str, doc_id: &str, tf: f64) {
        self.data.entry(field.to_string())
            .or_default()
            .entry(term.to_string())
            .or_default()
            .insert(doc_id.to_string(), tf);
    }
}

struct IndexData {
    doc_store: DocumentStore,
    inv_index: InvertedIndex,
}

fn generate_doc_info_json(store: &DocumentStore) -> String {
    let mut sorted_ids: Vec<&String> = store.doc_info.keys().collect();
    sorted_ids.sort_by(|a, b| {
        a.parse::<usize>().unwrap_or(0).cmp(&b.parse::<usize>().unwrap_or(0))
    });

    let entries: Vec<String> = sorted_ids.iter().map(|id| {
        let info = &store.doc_info[*id];
        format!("\"{}\":{{\"body\":{},,\"breadcrumbs\":{},,\"title\":{}}}",
            id, info.body, info.breadcrumbs, info.title)
        .replace(",,", ",")
    }).collect();

    format!("{{{}}}", entries.join(","))
}

fn generate_docs_json(store: &DocumentStore) -> String {
    let mut sorted_ids: Vec<&String> = store.docs.keys().collect();
    sorted_ids.sort_by(|a, b| {
        a.parse::<usize>().unwrap_or(0).cmp(&b.parse::<usize>().unwrap_or(0))
    });

    let entries: Vec<String> = sorted_ids.iter().map(|id| {
        let doc = &store.docs[*id];
        format!("\"{}\":{{\"body\":\"{}\",\"breadcrumbs\":\"{}\",\"id\":\"{}\",\"title\":\"{}\"}}",
            id,
            escape_json_str(&doc.body),
            escape_json_str(&doc.breadcrumbs),
            id,
            escape_json_str(&doc.title))
    }).collect();

    format!("{{{}}}", entries.join(","))
}

fn generate_field_index(inv_index: &InvertedIndex, field: &str) -> String {
    if let Some(field_data) = inv_index.data.get(field) {
        // Build the trie-like structure that elasticlunr uses
        build_trie(field_data)
    } else {
        "{\"df\":0,\"docs\":{}}".to_string()
    }
}

fn build_trie(terms: &HashMap<String, HashMap<String, f64>>) -> String {
    // Build a trie structure compatible with elasticlunr
    // This is a simplified version
    let mut sorted_terms: Vec<(&String, &HashMap<String, f64>)> = terms.iter().collect();
    sorted_terms.sort_by_key(|(t, _)| t.as_str());

    // Build character-by-character trie
    struct TrieNode {
        children: HashMap<char, Box<TrieNode>>,
        df: usize,
        docs: HashMap<String, f64>,
    }

    impl TrieNode {
        fn new() -> Self {
            TrieNode {
                children: HashMap::new(),
                df: 0,
                docs: HashMap::new(),
            }
        }

        fn insert(&mut self, term: &str, docs: &HashMap<String, f64>) {
            if term.is_empty() {
                self.df = docs.len();
                self.docs = docs.clone();
            } else {
                let c = term.chars().next().unwrap();
                let rest = &term[c.len_utf8()..];
                self.children.entry(c).or_insert_with(|| Box::new(TrieNode::new()))
                    .insert(rest, docs);
            }
        }

        fn to_json(&self) -> String {
            let docs_json = if self.docs.is_empty() {
                "{}".to_string()
            } else {
                let mut sorted: Vec<(&String, &f64)> = self.docs.iter().collect();
                sorted.sort_by_key(|(id, _)| id.parse::<usize>().unwrap_or(0));
                let entries: Vec<String> = sorted.iter()
                    .map(|(id, tf)| format!("\"{}\":{{\"tf\":{:.1}}}", id, tf))
                    .collect();
                format!("{{{}}}", entries.join(","))
            };

            let children_json: Vec<String> = {
                let mut chars: Vec<char> = self.children.keys().cloned().collect();
                chars.sort();
                chars.iter().map(|c| {
                    format!("\"{}\":{}", 
                        if *c == '"' { "\\\"".to_string() } 
                        else if *c == '\\' { "\\\\".to_string() }
                        else { c.to_string() },
                        self.children[c].to_json())
                }).collect()
            };

            if self.df == 0 && children_json.is_empty() {
                format!("{{\"df\":0,\"docs\":{}}}", docs_json)
            } else if children_json.is_empty() {
                format!("{{\"df\":{},\"docs\":{}}}", self.df, docs_json)
            } else {
                format!("{{\"df\":{},\"docs\":{},{}}}", 
                    self.df, docs_json, children_json.join(","))
            }
        }
    }

    let mut root = TrieNode::new();
    for (term, docs) in sorted_terms {
        root.insert(term, docs);
    }

    root.to_json()
}

/// Build search index from book chapters
pub fn build_search_index(
    chapters: &[(String, &str, &str, &str)], // (url, title, body, breadcrumbs)
    options: crate::config::SearchConfig,
) -> SearchIndex {
    let search_opts = SearchOptions {
        limit_results: options.limit_results,
        teaser_word_count: options.teaser_word_count,
        use_boolean_and: options.use_boolean_and,
        boost_title: options.boost_title,
        boost_hierarchy: options.boost_hierarchy,
        boost_paragraph: options.boost_paragraph,
        expand: options.expand,
    };

    let mut index = SearchIndex::new(search_opts);

    for (url, title, body, breadcrumbs) in chapters {
        index.add_document(title, body, breadcrumbs, url);
    }

    index
}
