use std::path::{Path, PathBuf};
use std::collections::HashMap;
use crate::config::{Config, HtmlConfig};
use crate::book::{Book, BookItem, Chapter, SectionNumber, flatten_book};
use crate::theme::Theme;
use crate::search::{SearchIndex, SearchOptions, build_search_index};
use crate::utils::{escape_html, id_from_content, path_to_root, log_info};
use crate::markdown::markdown_to_html;

/// Renders a book to HTML
pub struct HtmlRenderer {
    theme: Theme,
    html_config: HtmlConfig,
}

impl HtmlRenderer {
    pub fn new(html_config: HtmlConfig, theme_dir: Option<&Path>) -> Self {
        let theme = Theme::load(theme_dir);
        HtmlRenderer { theme, html_config }
    }

    pub fn render(&self, book: &Book, dest: &Path, book_title: &str, 
                  config: &Config) -> Result<(), String> {
        let html_config = &self.html_config;

        // Create destination directory
        std::fs::create_dir_all(dest).map_err(|e| e.to_string())?;

        // Copy theme files
        self.theme.copy_to(dest, html_config)?;

        // Write nojekyll file
        std::fs::write(dest.join(".nojekyll"), 
            "This file makes sure that Github Pages doesn't process mdBook's output.\n")
            .map_err(|e| e.to_string())?;

        // Get all chapters in order
        let all_chapters = collect_chapters(&book.sections);

        // Build TOC HTML
        let toc_html = self.build_toc_html(&book.sections, false);
        let toc_html_with_target = self.build_toc_html(&book.sections, true);

        // Write toc.js
        let toc_js = generate_toc_js(&self.theme, &toc_html);
        std::fs::write(dest.join("toc.js"), &toc_js).map_err(|e| e.to_string())?;

        // Write toc.html
        let toc_html_page = self.render_toc_html_page(&toc_html_with_target, book_title, config);
        std::fs::write(dest.join("toc.html"), &toc_html_page).map_err(|e| e.to_string())?;

        // Collect search data
        let mut search_chapters: Vec<(String, String, String, String)> = Vec::new(); // (url, title, body, breadcrumbs)

        // Render each chapter
        for (idx, chapter_info) in all_chapters.iter().enumerate() {
            let chapter = chapter_info.chapter;

            if chapter.path.is_none() {
                continue; // Skip draft chapters
            }

            let output_path = get_chapter_output_path(chapter);
            let output_file = dest.join(&output_path);

            // Create parent directory if needed
            if let Some(parent) = output_file.parent() {
                std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
            }

            let prev = if idx > 0 { Some(&all_chapters[idx-1]) } else { None };
            let next = if idx + 1 < all_chapters.len() { Some(&all_chapters[idx+1]) } else { None };

            // Extract path_to_root from output path
            let ptr = path_to_root(&output_path);

            // Render the chapter
            let html = self.render_chapter(
                chapter, book_title, config, &toc_html, 
                &ptr, prev, next
            )?;

            std::fs::write(&output_file, &html).map_err(|e| e.to_string())?;

            // Also generate search entries
            if html_config.search.enable {
                let content_html = crate::markdown::markdown_to_html(&chapter.content, None);
                collect_search_entries(
                    &content_html, &output_path, chapter, 
                    chapter_info.parents.as_deref().unwrap_or(""),
                    &mut search_chapters
                );
            }
        }

        // The first chapter should also be index.html
        if let Some(first) = all_chapters.first() {
            let first_path = get_chapter_output_path(first.chapter);
            let src_file = dest.join(&first_path);
            let index_file = dest.join("index.html");
            if !index_file.exists() && src_file.exists() {
                std::fs::copy(&src_file, &index_file).map_err(|e| e.to_string())?;
            }
        }

        // Generate print.html
        if html_config.print.enable {
            let print_html = self.render_print_page(&all_chapters, book_title, config)?;
            std::fs::write(dest.join("print.html"), &print_html).map_err(|e| e.to_string())?;
        }

        // Generate 404.html
        let page_404 = self.render_404_page(book_title, config);
        std::fs::write(dest.join("404.html"), &page_404).map_err(|e| e.to_string())?;

        // Generate search index
        if html_config.search.enable {
            let search_refs: Vec<(String, &str, &str, &str)> = search_chapters.iter()
                .map(|(url, title, body, bc)| (url.clone(), title.as_str(), body.as_str(), bc.as_str()))
                .collect();
            let index = build_search_index(
                &search_refs.iter().map(|(u, t, b, bc)| (u.clone(), *t, *b, *bc)).collect::<Vec<_>>(),
                html_config.search.clone()
            );
            let search_js = index.generate_js();

            // searchindex.js is the search data + toc.js concatenated
            let searchindex_content = format!("{}", search_js);
            std::fs::write(dest.join("searchindex.js"), &searchindex_content)
                .map_err(|e| e.to_string())?;
        }

        // Handle redirect pages
        for (from_path, to_url) in &html_config.redirect {
            let redirect_file = dest.join(from_path.trim_start_matches('/'));
            if let Some(parent) = redirect_file.parent() {
                std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
            }
            let redirect_html = generate_redirect_html(to_url);
            std::fs::write(&redirect_file, &redirect_html).map_err(|e| e.to_string())?;
        }

        // Copy source files that aren't .md
        if let Some(src_dir_name) = config.book.src.as_str().parse::<PathBuf>().ok() {
            // We'll handle this in the build command
        }

        Ok(())
    }

