    fn build_toc_html(&self, sections: &[BookItem], with_target: bool) -> String {
        let items_html = self.build_toc_items(sections, with_target);
        format!("<ol class=\"chapter\">{}</ol>", items_html)
    }

    fn build_toc_items(&self, items: &[BookItem], with_target: bool) -> String {
        let mut html = String::new();

        for item in items {
            match item {
                BookItem::Chapter(ch) => {
                    let is_affix = ch.is_prefix || ch.is_suffix;
                    let classes = if is_affix {
                        "chapter-item expanded affix "
                    } else {
                        "chapter-item expanded "
                    };

                    let target_attr = if with_target { " target=\"_parent\"" } else { "" };

                    let link = if let Some(path) = &ch.path {
                        let path_str = path.to_string_lossy();
                        // Convert .md to .html
                        let html_path = if path_str.ends_with(".md") {
                            format!("{}.html", &path_str[..path_str.len()-3])
                        } else {
                            path_str.to_string()
                        };
                        let html_path = html_path.replace('\\', "/");

                        if is_affix {
                            // No number for prefix/suffix
                            format!("<a href=\"{}\"{}>{}</a>", html_path, target_attr, escape_html(&ch.name))
                        } else if let Some(num) = &ch.number {
                            format!("<a href=\"{}\"{} ><strong aria-hidden=\"true\">{}</strong> {}</a>",
                                html_path, target_attr, 
                                num_to_display(num),
                                escape_html(&ch.name))
                        } else {
                            format!("<a href=\"{}\"{}>{}</a>", html_path, target_attr, escape_html(&ch.name))
                        }
                    } else {
                        // Draft chapter
                        if let Some(num) = &ch.number {
                            format!("<div><strong aria-hidden=\"true\">{}</strong> {}</div>",
                                num_to_display(num), escape_html(&ch.name))
                        } else {
                            format!("<div>{}</div>", escape_html(&ch.name))
                        }
                    };

                    html.push_str(&format!("<li class=\"{}\">", classes));
                    html.push_str(&link);
                    html.push_str("</li>");

                    if !ch.sub_items.is_empty() {
                        html.push_str("<li><ol class=\"section\">");
                        html.push_str(&self.build_toc_items(&ch.sub_items, with_target));
                        html.push_str("</ol></li>");
                    }
                }
                BookItem::Separator => {
                    html.push_str("<li class=\"chapter-item expanded affix \">");
                    html.push_str("<li class=\"spacer\"></li>");
                }
                BookItem::PartTitle(title) => {
                    html.push_str("<li class=\"chapter-item expanded affix \">");
                    html.push_str(&format!("<li class=\"part-title\">{}</li>", escape_html(title)));
                }
            }
        }

        html
    }
}

