enum HtmlSegment {
    Heading(u8, String, String), // level, id, text
    Content(String),
}

fn split_by_headings(html: &str) -> Vec<HtmlSegment> {
    let mut segments = Vec::new();
    let mut current_content = String::new();
    let mut i = 0;
    let bytes = html.as_bytes();

    while i < html.len() {
        // Check for heading tag
        if html[i..].starts_with("<h") && i + 2 < html.len() {
            let level_char = html.as_bytes().get(i + 2).copied().unwrap_or(0) as char;
            if level_char >= '1' && level_char <= '6' {
                // Check for id attribute  
                if !current_content.is_empty() {
                    segments.push(HtmlSegment::Content(current_content.clone()));
                    current_content.clear();
                }

                // Find the end of the heading tag and extract id
                if let Some(end) = html[i..].find("</h") {
                    let heading_html = &html[i..i+end+5];
                    let level = (level_char as u8) - b'0';
                    let id = extract_id_from_heading(heading_html);
                    let text = extract_text_from_heading(heading_html);
                    segments.push(HtmlSegment::Heading(level, id, text));

                    // Find the complete closing tag
                    if let Some(close_end) = html[i+end..].find('>') {
                        i += end + close_end + 1;
                    } else {
                        i += end + 5;
                    }
                    continue;
                }
            }
        }

        current_content.push(html.as_bytes()[i] as char);
        i += 1;
    }

    if !current_content.is_empty() {
        segments.push(HtmlSegment::Content(current_content));
    }

    segments
}

fn extract_id_from_heading(html: &str) -> String {
    // Extract id="..." attribute
    if let Some(id_pos) = html.find("id=\"") {
        let start = id_pos + 4;
        if let Some(end) = html[start..].find('"') {
            return html[start..start+end].to_string();
        }
    }
    String::new()
}

fn extract_text_from_heading(html: &str) -> String {
    // Extract the text content of the heading (strip HTML tags)
    crate::utils::strip_html(html)
        .trim()
        .to_string()
}

/// Render a Handlebars template with simple variable substitution
/// This is a SIMPLIFIED version that handles the index.hbs template
fn render_hbs_template(
    template: &str,
    vars: &[(&str, &str)],
    bools: &[(&str, bool)],
    path_to_root: &str,
) -> String {
    let vars_map: HashMap<&str, &str> = vars.iter().cloned().collect();
    let bools_map: HashMap<&str, bool> = bools.iter().cloned().collect();

    render_hbs_node(template, &vars_map, &bools_map, path_to_root)
}

fn render_hbs_node(
    template: &str,
    vars: &HashMap<&str, &str>,
    bools: &HashMap<&str, bool>,
    path_to_root: &str,
) -> String {
    let mut result = String::new();
    let mut i = 0;
    let chars: Vec<char> = template.chars().collect();

    while i < chars.len() {
        if i + 1 < chars.len() && chars[i] == '{' && chars[i + 1] == '{' {
            // Find the end of the expression
            let start = i + 2;
            let mut j = start;
            let mut brace_count = 0;
            let triple = i + 2 < chars.len() && chars[i + 2] == '{';
            let actual_start = if triple { start + 1 } else { start };
            let mut j = actual_start;

            while j < chars.len() {
                if chars[j] == '}' {
                    if triple {
                        if j + 2 < chars.len() && chars[j+1] == '}' && chars[j+2] == '}' {
                            break;
                        }
                    } else {
                        if j + 1 < chars.len() && chars[j+1] == '}' {
                            break;
                        }
                    }
                }
                j += 1;
            }

            let expr: String = chars[actual_start..j].iter().collect();
            let expr = expr.trim();
            let end_skip = if triple { 3 } else { 2 };

            if expr.starts_with("#if ") {
                let cond = &expr[4..].trim();
                let val = bools.get(cond).copied().unwrap_or(false) 
                    || (bools.contains_key(cond) && *bools.get(cond).unwrap());

                // Find the matching {{/if}}
                let after = &template[j + end_skip..];
                let (if_body, else_body, skip) = find_if_else_end(after);

                if val {
                    result.push_str(&render_hbs_node(&if_body, vars, bools, path_to_root));
                } else if let Some(eb) = else_body {
                    result.push_str(&render_hbs_node(&eb, vars, bools, path_to_root));
                }

                i = j + end_skip + skip;
                // We need to find proper character position
                // For now, let's use byte-based approach
                let remaining = &template[j + end_skip..];
                let (_, _, skip_chars) = find_if_else_end_chars(remaining);
                i = j + end_skip + skip_chars;
                continue;
            }

            if expr.starts_with("/if") || expr.starts_with("/each") || expr.starts_with("/with")
                || expr.starts_with("/previous") || expr.starts_with("/next")
                || expr.starts_with("else") {
                // These are handled by their opening tag
                i = j + end_skip;
                continue;
            }

            if expr.starts_with("#each ") {
                let arr_name = expr[6..].trim();
                // Get the array value
                if let Some(arr_str) = vars.get(arr_name) {
                    // Simple: treat as comma-separated list
                }
                // Skip the each block for now
                let after = &template[j + end_skip..];
                let (_, _, skip_chars) = find_block_end_chars(after, &format!("/each"));
                i = j + end_skip + skip_chars;
                continue;
            }

            if expr.starts_with("#previous") {
                let prev_val = vars.get("prev_nav").copied().unwrap_or("");
                if !prev_val.is_empty() {
                    let after = &template[j + end_skip..];
                    let (block_body, skip_chars) = find_block_body_chars(after, "/previous");
                    let rendered_body = render_hbs_node(&block_body, vars, bools, path_to_root);
                    result.push_str(&rendered_body);
                    i = j + end_skip + skip_chars;
                } else {
                    let after = &template[j + end_skip..];
                    let (_, skip_chars) = find_block_body_chars(after, "/previous");
                    i = j + end_skip + skip_chars;
                }
                continue;
            }

            if expr.starts_with("#next") {
                let next_val = vars.get("next_nav").copied().unwrap_or("");
                if !next_val.is_empty() {
                    let after = &template[j + end_skip..];
                    let (block_body, skip_chars) = find_block_body_chars(after, "/next");
                    let rendered_body = render_hbs_node(&block_body, vars, bools, path_to_root);
                    result.push_str(&rendered_body);
                    i = j + end_skip + skip_chars;
                } else {
                    let after = &template[j + end_skip..];
                    let (_, skip_chars) = find_block_body_chars(after, "/next");
                    i = j + end_skip + skip_chars;
                }
                continue;
            }

            if expr.starts_with("> ") || expr.starts_with(">") {
                // Partial - render partial template
                let partial_name = expr.trim_start_matches('>').trim();
                // For now, just skip partials (they render nothing for our case)
                i = j + end_skip;
                continue;
            }

            // Variable substitution
            if triple {
                // {{{var}}} - raw HTML
                if let Some(val) = vars.get(expr) {
                    result.push_str(val);
                } else if expr.starts_with("resource \"") || expr.starts_with("resource \"") {
                    // Handle resource helper
                    let res_name = expr.trim_start_matches("resource").trim().trim_matches('"');
                    result.push_str(&format!("{}{}", path_to_root, res_name));
                } else {
                    // Try with resource helper
                    result.push_str(&format!("{{{{{{{}}}}}}}", expr));
                }
            } else {
                // {{var}} - HTML escaped
                if let Some(val) = vars.get(expr) {
                    result.push_str(&escape_html(val));
                } else if expr.starts_with("resource ") {
                    // Handle resource helper: resource "filename"
                    let res_name = expr["resource ".len()..].trim().trim_matches('"');
                    result.push_str(&format!("{}{}", path_to_root, res_name));
                } else {
                    // Not found - leave empty
                }
            }

            i = j + end_skip;
            continue;
        }

        result.push(chars[i]);
        i += 1;
    }

    result
}

fn find_if_else_end(template: &str) -> (String, Option<String>, usize) {
    // Find {{/if}} and optionally {{else}}
    find_if_else_end_chars(template).0
    // We'll do a simpler version
}

fn find_if_else_end_chars(template: &str) -> ((String, Option<String>, usize), String, Option<String>, usize) {
    let result = find_if_block(template);
    (result.clone(), result.0, result.1, result.2)
}

fn find_if_block(template: &str) -> (String, Option<String>, usize) {
    // Find the end of an #if block
    let mut depth = 1;
    let mut i = 0;
    let mut if_end = 0;
    let mut else_start = None;

    while i < template.len() {
        if template[i..].starts_with("{{#if ") || template[i..].starts_with("{{#each ") {
            depth += 1;
            i += 4;
        } else if template[i..].starts_with("{{/if}}") {
            depth -= 1;
            if depth == 0 {
                let if_body = template[..if_end].to_string();
                let else_body = else_start.map(|s| template[s..if_end].to_string());
                return (if_body, else_body, i + 7);
            }
        } else if template[i..].starts_with("{{/each}}") {
            depth -= 1;
            if depth == 0 {
                return (template[..i].to_string(), None, i + 9);
            }
        } else if template[i..].starts_with("{{else}}") && depth == 1 {
            if_end = i;
            else_start = Some(i + 8);
            i += 8;
            continue;
        }

        if_end = i + 1;
        i += 1;
    }

    (template.to_string(), None, template.len())
}

fn find_block_end_chars(template: &str, end_tag: &str) -> (String, Option<String>, usize) {
    let search = format!("{{{{{}}}}}}}", end_tag);
    if let Some(pos) = template.find(&search) {
        (template[..pos].to_string(), None, pos + search.len())
    } else {
        (template.to_string(), None, template.len())
    }
}

fn find_block_body_chars(template: &str, end_tag: &str) -> (String, usize) {
    let search = format!("{{{{{}}}}}}}", end_tag);
    if let Some(pos) = template.find(&search) {
        (template[..pos].to_string(), pos + search.len())
    } else {
        (template.to_string(), template.len())
    }
}

