/// Copy non-MD source files to destination
pub fn copy_source_files(src_dir: &Path, dest_dir: &Path) -> Result<(), String> {
    for entry in walkdir(src_dir) {
        let entry = entry?;
        if entry.is_file() {
            let rel = entry.strip_prefix(src_dir).map_err(|e| e.to_string())?;
            let ext = rel.extension().and_then(|e| e.to_str()).unwrap_or("");
            if ext != "md" {
                let dest = dest_dir.join(rel);
                if let Some(parent) = dest.parent() {
                    std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
                }
                std::fs::copy(&entry, &dest).map_err(|e| e.to_string())?;
            }
        }
    }
    Ok(())
}

fn walkdir(dir: &Path) -> Vec<Result<PathBuf, String>> {
    let mut result = Vec::new();
    match std::fs::read_dir(dir) {
        Err(e) => result.push(Err(e.to_string())),
        Ok(entries) => {
            for entry in entries.flatten() {
                let path = entry.path();
                if path.is_dir() {
                    result.extend(walkdir(&path));
                } else {
                    result.push(Ok(path));
                }
            }
        }
    }
    result
}
