        let toc_html_page = self.render_toc_html_page(&toc_html_with_target, book_title, config);
        std::fs::write(dest.join("toc.html"), &toc_html_page).map_err(|e| e.to_string())?;

        // Collect search data
        let mut search_chapters: Vec<(String, String, String, String)> = Vec::new(); // (url, title, body, breadcrumbs)

        // Render each chapter
        for (idx, chapter_info) in all_chapters.iter().enumerate() {
            let chapter = chapter_info.chapter;

            if chapter.path.is_none() {
                continue; // Skip draft chapters
            }

            let output_path = get_chapter_output_path(chapter);
            let output_file = dest.join(&output_path);

            // Create parent directory if needed
            if let Some(parent) = output_file.parent() {
                std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
            }

            let prev = if idx > 0 { Some(&all_chapters[idx-1]) } else { None };
            let next = if idx + 1 < all_chapters.len() { Some(&all_chapters[idx+1]) } else { None };

            // Extract path_to_root from output path
            let ptr = path_to_root(&output_path);

            // Render the chapter
            let html = self.render_chapter(
                chapter, book_title, config, &toc_html, 
                &ptr, prev, next
            )?;

            std::fs::write(&output_file, &html).map_err(|e| e.to_string())?;

            // Also generate search entries
            if html_config.search.enable {
                let content_html = crate::markdown::markdown_to_html(&chapter.content, None);
                collect_search_entries(
                    &content_html, &output_path, chapter, 
                    chapter_info.parents.as_deref().unwrap_or(""),
                    &mut search_chapters
                );
            }
        }

        // The first chapter should also be index.html
        if let Some(first) = all_chapters.first() {
            let first_path = get_chapter_output_path(first.chapter);
            let src_file = dest.join(&first_path);
            let index_file = dest.join("index.html");
            if !index_file.exists() && src_file.exists() {
                std::fs::copy(&src_file, &index_file).map_err(|e| e.to_string())?;
            }
        }

        // Generate print.html
        if html_config.print.enable {
            let print_html = self.render_print_page(&all_chapters, book_title, config)?;
            std::fs::write(dest.join("print.html"), &print_html).map_err(|e| e.to_string())?;
        }

        // Generate 404.html
        let page_404 = self.render_404_page(book_title, config);
        std::fs::write(dest.join("404.html"), &page_404).map_err(|e| e.to_string())?;

        // Generate search index
        if html_config.search.enable {
            let search_refs: Vec<(String, &str, &str, &str)> = search_chapters.iter()
                .map(|(url, title, body, bc)| (url.clone(), title.as_str(), body.as_str(), bc.as_str()))
                .collect();
            let index = build_search_index(
                &search_refs.iter().map(|(u, t, b, bc)| (u.clone(), *t, *b, *bc)).collect::<Vec<_>>(),
                html_config.search.clone()
            );
            let search_js = index.generate_js();

            // searchindex.js is the search data + toc.js concatenated
            let searchindex_content = format!("{}", search_js);
            std::fs::write(dest.join("searchindex.js"), &searchindex_content)
                .map_err(|e| e.to_string())?;
        }

        // Handle redirect pages
        for (from_path, to_url) in &html_config.redirect {
            let redirect_file = dest.join(from_path.trim_start_matches('/'));
            if let Some(parent) = redirect_file.parent() {
                std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
            }
            let redirect_html = generate_redirect_html(to_url);
            std::fs::write(&redirect_file, &redirect_html).map_err(|e| e.to_string())?;
        }

        // Copy source files that aren't .md
        if let Some(src_dir_name) = config.book.src.as_str().parse::<PathBuf>().ok() {
            // We'll handle this in the build command
        }

        Ok(())
    }

    fn render_chapter(
        &self,
        chapter: &Chapter,
        book_title: &str,
        config: &Config,
        toc_html: &str,
        path_to_root: &str,
        prev: Option<&ChapterInfo>,
        next: Option<&ChapterInfo>,
    ) -> Result<String, String> {
        let html_config = &self.html_config;
        let content_html = markdown_to_html(&chapter.content, None);

        let title = if book_title.is_empty() {
            chapter.name.clone()
        } else {
            format!("{} - {}", chapter.name, book_title)
        };

        let page_title = if book_title.is_empty() {
            chapter.name.clone()
        } else {
            format!("{} - {}", chapter.name, book_title)
        };

        let default_theme = html_config.default_theme.as_deref().unwrap_or("light");
        let dark_theme = html_config.preferred_dark_theme.as_deref().unwrap_or("navy");
        let language = &config.book.language;
        let text_dir = config.book.text_direction.as_deref().unwrap_or("ltr");
        let description = config.book.description.as_deref().unwrap_or("");

        let template = std::str::from_utf8(&self.theme.index_hbs)
            .map_err(|e| e.to_string())?;

        let prev_nav = prev.map(|p| {
            let path = get_chapter_output_path(p.chapter);
            let path = if path_to_root.is_empty() { path } else { path };
            format!(r#"<a rel="prev" href="{path_to_root}{path}" class="mobile-nav-chapters previous" title="Previous chapter" aria-label="Previous chapter" aria-keyshortcuts="Left">
                                <i class="fa fa-angle-left"></i>
                            </a>"#, path_to_root=path_to_root, path=path)
        }).unwrap_or_default();

        let next_nav = next.map(|n| {
            let path = get_chapter_output_path(n.chapter);
            format!(r#"<a rel="next prefetch" href="{path_to_root}{path}" class="mobile-nav-chapters next" title="Next chapter" aria-label="Next chapter" aria-keyshortcuts="Right">
                                <i class="fa fa-angle-right"></i>
                            </a>"#, path_to_root=path_to_root, path=path)
        }).unwrap_or_default();

        let prev_nav_wide = prev.map(|p| {
            let path = get_chapter_output_path(p.chapter);
            format!(r#"    <a rel="prev" href="{path_to_root}{path}" class="nav-chapters previous" title="Previous chapter" aria-label="Previous chapter" aria-keyshortcuts="Left">
                        <i class="fa fa-angle-left"></i>
                    </a>"#, path_to_root=path_to_root, path=path)
        }).unwrap_or_default();

        let next_nav_wide = next.map(|n| {
            let path = get_chapter_output_path(n.chapter);
            format!(r#"    <a rel="next prefetch" href="{path_to_root}{path}" class="nav-chapters next" title="Next chapter" aria-label="Next chapter" aria-keyshortcuts="Right">
                        <i class="fa fa-angle-right"></i>
                    </a>"#, path_to_root=path_to_root, path=path)
        }).unwrap_or_default();

        let print_link = if html_config.print.enable {
            format!(r#"<a href="{path_to_root}print.html" title="Print this book" aria-label="Print this book">
                            <i id="print-button" class="fa fa-print"></i>
                        </a>"#, path_to_root=path_to_root)
        } else {
            String::new()
        };

        let git_edit_link = if let Some(template) = &html_config.edit_url_template {
            if let Some(sp) = &chapter.source_path {
                let path_str = sp.to_string_lossy();
                let url = template.replace("{path}", &path_str);
                format!(r#"<a href="{}" title="Suggest an edit" aria-label="Suggest an edit">
                            <i class="fa fa-edit"></i>
                        </a>"#, url)
            } else { String::new() }
        } else if let Some(repo_url) = &html_config.git_repository_url {
            // No edit link without template
            String::new()
        } else {
            String::new()
        };

        let additional_css_links: String = html_config.additional_css.iter()
            .map(|css| format!("<link rel=\"stylesheet\" href=\"{path_to_root}{css}\">\n", 
                path_to_root=path_to_root, css=css))
            .collect();

        let additional_js_scripts: String = html_config.additional_js.iter()
            .map(|js| format!("<script src=\"{path_to_root}{js}\"></script>\n", 
                path_to_root=path_to_root, js=js))
            .collect();

        let mathjax_support = html_config.mathjax_support;
        let search_enabled = html_config.search.enable;
        let search_js = html_config.search.enable && html_config.search.copy_js;
        let copy_fonts = html_config.copy_fonts;
        let playground_copyable = html_config.playground.copyable;
        let playground_line_numbers = html_config.playground.line_numbers;

        // Render the template
        let rendered = render_hbs_template(
            template,
            &[
                ("language", language.as_str()),
                ("default_theme", default_theme),
                ("text_direction", text_dir),
                ("title", &page_title),
                ("description", description),
                ("path_to_root", path_to_root),
                ("preferred_dark_theme", dark_theme),
                ("content", &content_html),
                ("book_title", book_title),
                ("prev_nav", &prev_nav),
                ("next_nav", &next_nav),
                ("prev_nav_wide", &prev_nav_wide),
                ("next_nav_wide", &next_nav_wide),
                ("print_link", &print_link),
                ("git_edit_link", &git_edit_link),
                ("additional_css_links", &additional_css_links),
                ("additional_js_scripts", &additional_js_scripts),
            ],
            &[
                ("is_print", false),
                ("search_enabled", search_enabled),
                ("search_js", search_js),
                ("copy_fonts", copy_fonts),
                ("playground_copyable", playground_copyable),
                ("playground_line_numbers", playground_line_numbers),
                ("mathjax_support", mathjax_support),
                ("favicon_svg", true),
                ("favicon_png", true),
                ("print_enable", html_config.print.enable),
                ("base_url", false),
                ("live_reload_endpoint", false),
                ("playground_js", false),
                ("fragment_map", false),
            ],
            path_to_root,
        );

        Ok(rendered)
    }

    fn render_toc_html_page(&self, toc_html: &str, book_title: &str, config: &Config) -> String {
        let html_config = &self.html_config;
        let default_theme = html_config.default_theme.as_deref().unwrap_or("light");
        let language = &config.book.language;
        let text_dir = config.book.text_direction.as_deref().unwrap_or("ltr");
        let copy_fonts = html_config.copy_fonts;

        format!(
r#"<!DOCTYPE HTML>
<html lang="{language}" class="{default_theme}" dir="{text_dir}">
    <head>
        <!-- sidebar iframe generated using mdBook

        This is a frame, and not included directly in the page, to control the total size of the
        book. The TOC contains an entry for each page, so if each page includes a copy of the TOC,
        the total size of the page becomes O(n**2).

        The frame is only used as a fallback when JS is turned off. When it's on, the sidebar is
        instead added to the main page by `toc.js` instead. The JavaScript mode is better
        because, when running in a `file:///` URL, the iframed page would not be Same-Origin as
        the rest of the page, so the sidebar and the main page theme would fall out of sync.
        -->
        <meta charset="UTF-8">
        <meta name="robots" content="noindex">
        <!-- Custom HTML head -->
        <meta name="viewport" content="width=device-width, initial-scale=1">
        <meta name="theme-color" content="#ffffff">
        <link rel="stylesheet" href="css/variables.css">
        <link rel="stylesheet" href="css/general.css">
        <link rel="stylesheet" href="css/chrome.css">
        <link rel="stylesheet" href="css/print.css" media="print">
        <!-- Fonts -->
        <link rel="stylesheet" href="FontAwesome/css/font-awesome.css">
        {fonts_link}<!-- Custom theme stylesheets -->
    </head>
    <body class="sidebar-iframe-inner">
        {toc_html}
    </body>
</html>"#,
            language=escape_html(language),
            default_theme=default_theme,
            text_dir=text_dir,
            fonts_link=if copy_fonts { "<link rel=\"stylesheet\" href=\"fonts/fonts.css\">\n        " } else { "" },
            toc_html=toc_html,
        )
    }

