    fn build_toc_html(&self, sections: &[BookItem], with_target: bool) -> String {
        let items_html = self.build_toc_items(sections, with_target);
        format!("<ol class=\"chapter\">{}</ol>", items_html)
    }

    fn build_toc_items(&self, items: &[BookItem], with_target: bool) -> String {
        let mut html = String::new();

        for item in items {
            match item {
                BookItem::Chapter(ch) => {
                    let is_affix = ch.is_prefix || ch.is_suffix;
                    let classes = if is_affix {
                        "chapter-item expanded affix "
                    } else {
                        "chapter-item expanded "
                    };

                    let target_attr = if with_target { " target=\"_parent\"" } else { "" };

                    let link = if let Some(path) = &ch.path {
                        let path_str = path.to_string_lossy();
                        // Convert .md to .html
                        let html_path = if path_str.ends_with(".md") {
                            format!("{}.html", &path_str[..path_str.len()-3])
                        } else {
                            path_str.to_string()
                        };
                        let html_path = html_path.replace('\\', "/");

                        if is_affix {
                            // No number for prefix/suffix
                            format!("<a href=\"{}\"{}>{}</a>", html_path, target_attr, escape_html(&ch.name))
                        } else if let Some(num) = &ch.number {
                            format!("<a href=\"{}\"{} ><strong aria-hidden=\"true\">{}</strong> {}</a>",
                                html_path, target_attr, 
                                num_to_display(num),
                                escape_html(&ch.name))
                        } else {
                            format!("<a href=\"{}\"{}>{}</a>", html_path, target_attr, escape_html(&ch.name))
                        }
                    } else {
                        // Draft chapter
                        if let Some(num) = &ch.number {
                            format!("<div><strong aria-hidden=\"true\">{}</strong> {}</div>",
                                num_to_display(num), escape_html(&ch.name))
                        } else {
                            format!("<div>{}</div>", escape_html(&ch.name))
                        }
                    };

                    html.push_str(&format!("<li class=\"{}\">", classes));
                    html.push_str(&link);
                    html.push_str("</li>");

                    if !ch.sub_items.is_empty() {
                        html.push_str("<li><ol class=\"section\">");
                        html.push_str(&self.build_toc_items(&ch.sub_items, with_target));
                        html.push_str("</ol></li>");
                    }
                }
                BookItem::Separator => {
                    html.push_str("<li class=\"chapter-item expanded affix \">");
                    html.push_str("<li class=\"spacer\"></li>");
                }
                BookItem::PartTitle(title) => {
                    html.push_str("<li class=\"chapter-item expanded affix \">");
                    html.push_str(&format!("<li class=\"part-title\">{}</li>", escape_html(title)));
                }
            }
        }

        html
    }
}

fn num_to_display(num: &SectionNumber) -> String {
    let s = num.display();
    format!("{}.", s)
}

fn generate_toc_js(theme: &Theme, toc_html: &str) -> String {
    // The toc.js is the static JS from theme with the innerHTML set to the book's TOC
    let static_js = std::str::from_utf8(&theme.toc_js).unwrap_or("");

    // Find the line with innerHTML and replace it
    // The template toc.js has:
    // this.innerHTML = '...';

    // We need to replace the static toc.js content's innerHTML with our generated TOC
    // But the static toc.js from the theme contains sample data
    // Let's find the pattern and replace it

    let toc_escaped = toc_html.replace('\\', "\\\\").replace('\'', "\\'");

    // Find the innerHTML = line and replace it
    if let Some(pos) = static_js.find("this.innerHTML = '") {
        let end = static_js[pos..].find("';").unwrap_or(0);
        if end > 0 {
            let before = &static_js[..pos];
            let after = &static_js[pos + end + 2..];
            return format!("{}this.innerHTML = '{}';{}", before, toc_escaped, after);
        }
    }

    // Fallback: generate complete toc.js
    generate_complete_toc_js(&toc_escaped)
}

fn generate_complete_toc_js(toc_html: &str) -> String {
    format!(r#"// Populate the sidebar
//
// This is a script, and not included directly in the page, to control the total size of the book.
// The TOC contains an entry for each page, so if each page includes a copy of the TOC,
// the total size of the page becomes O(n**2).
class MDBookSidebarScrollbox extends HTMLElement {{
    constructor() {{
        super();
    }}
    connectedCallback() {{
        this.innerHTML = '{}';
        // Set the current, active page, and reveal it if it's hidden
        let current_page = document.location.href.toString().split("#")[0].split("?")[0];
        if (current_page.endsWith("/")) {{
            current_page += "index.html";
        }}
        var links = Array.prototype.slice.call(this.querySelectorAll("a"));
        var l = links.length;
        for (var i = 0; i < l; ++i) {{
            var link = links[i];
            var href = link.getAttribute("href");
            if (href && !href.startsWith("#") && !/^(?:[a-z+]+:)?\/\//.test(href)) {{
                link.href = path_to_root + href;
            }}
            // The "index" page is supposed to alias the first chapter in the book.
            if (link.href === current_page || (i === 0 && path_to_root === "" && current_page.endsWith("/index.html"))) {{
                link.classList.add("active");
                var parent = link.parentElement;
                if (parent && parent.classList.contains("chapter-item")) {{
                    parent.classList.add("expanded");
                }}
                while (parent) {{
                    if (parent.tagName === "LI" && parent.previousElementSibling) {{
                        if (parent.previousElementSibling.classList.contains("chapter-item")) {{
                            parent.previousElementSibling.classList.add("expanded");
                        }}
                    }}
                    parent = parent.parentElement;
                }}
            }}
        }}
        // Track and set sidebar scroll position
        this.addEventListener('click', function(e) {{
            if (e.target.tagName === 'A') {{
                sessionStorage.setItem('sidebar-scroll', this.scrollTop);
            }}
        }}, {{ passive: true }});
        var sidebarScrollTop = sessionStorage.getItem('sidebar-scroll');
        sessionStorage.removeItem('sidebar-scroll');
        if (sidebarScrollTop) {{
            // preserve sidebar scroll position when navigating via links within sidebar
            this.scrollTop = sidebarScrollTop;
        }} else {{
            // scroll sidebar to current active section when navigating via "next/previous chapter" buttons
            var activeSection = document.querySelector('#sidebar .active');
            if (activeSection) {{
                activeSection.scrollIntoView({{ block: 'center' }});
            }}
        }}
        // Toggle buttons
        var sidebarAnchorToggles = document.querySelectorAll('#sidebar a.toggle');
        function toggleSection(ev) {{
            ev.currentTarget.parentElement.classList.toggle('expanded');
        }}
        Array.from(sidebarAnchorToggles).forEach(function (el) {{
            el.addEventListener('click', toggleSection);
        }});
    }}
}}
window.customElements.define("mdbook-sidebar-scrollbox", MDBookSidebarScrollbox);"#, toc_html)
}

pub struct ChapterInfo<'a> {
    pub chapter: &'a Chapter,
    pub parents: Option<String>,
}

fn collect_chapters<'a>(sections: &'a Vec<BookItem>) -> Vec<ChapterInfo<'a>> {
    let mut result = Vec::new();
    collect_chapters_from_items(sections, &[], &mut result);
    result
}

fn collect_chapters_from_items<'a>(
    items: &'a Vec<BookItem>, 
    parent_names: &[&str],
    result: &mut Vec<ChapterInfo<'a>>
) {
    for item in items {
        if let BookItem::Chapter(ch) = item {
            if ch.path.is_none() && !ch.sub_items.is_empty() {
                // Draft chapter with sub-items? Unusual but handle
            }
            let parents_str = if parent_names.is_empty() {
                None
            } else {
                Some(parent_names.join(" » "))
            };
            result.push(ChapterInfo {
                chapter: ch,
                parents: parents_str,
            });

            let mut new_parents = parent_names.to_vec();
            new_parents.push(&ch.name);
            collect_chapters_from_items(&ch.sub_items, &new_parents, result);
        }
    }
}

fn get_chapter_output_path(chapter: &Chapter) -> String {
    if let Some(path) = &chapter.path {
        let s = path.to_string_lossy();
        let s = s.replace('\\', "/");
        if s.ends_with(".md") {
            format!("{}.html", &s[..s.len()-3])
        } else {
            s.to_string()
        }
    } else {
        String::new()
    }
}

fn collect_search_entries(
    html: &str,
    output_path: &str,
    chapter: &Chapter,
    parent_hierarchy: &str,
    results: &mut Vec<(String, String, String, String)>,
) {
    // Parse headings from the HTML and create search entries
    let mut sections = Vec::new();

    // Find all h1-h6 tags with ids
    let mut i = 0;
    let bytes = html.as_bytes();
    let mut current_section: Option<(String, String, String)> = None; // (id, title, body_acc)
    let mut body_acc = String::new();

    // We need to find headings and collect text between them
    // Simple approach: split on heading tags
    struct Section {
        id: String,
        title: String,
        body: String,
    }

    let mut parsed_sections: Vec<Section> = Vec::new();

    // Simple HTML section parser
    let mut pos = 0;
    let html_chars: Vec<char> = html.chars().collect();
    let mut current_id = String::new();
    let mut current_title = String::new();
    let mut current_body = String::new();
    let mut in_heading = false;
    let mut heading_id = String::new();
    let mut heading_level = 0u8;

    // Actually, let's use a simpler approach: parse line by line
    // Find heading tags and collect content
    for segment in split_by_headings(html) {
        match segment {
            HtmlSegment::Heading(level, id, text) => {
                // Save current section
                if !current_id.is_empty() {
                    parsed_sections.push(Section {
                        id: current_id.clone(),
                        title: current_title.clone(),
                        body: current_body.trim().to_string(),
                    });
                }
                current_id = id;
                current_title = text;
                current_body = String::new();
            }
            HtmlSegment::Content(text) => {
                let stripped = crate::utils::strip_html(&text);
                current_body.push_str(&stripped);
                current_body.push(' ');
            }
        }
    }

    // Save last section
    if !current_id.is_empty() {
        parsed_sections.push(Section {
            id: current_id,
            title: current_title,
            body: current_body.trim().to_string(),
        });
    }

    // Create search entries
    for section in parsed_sections {
        let url = format!("{}#{}", output_path, section.id);
        let breadcrumbs = build_breadcrumbs(parent_hierarchy, &chapter.name, &section.title);
        results.push((url, section.title, section.body, breadcrumbs));
    }

    // If no sections found, create one for the whole chapter
    if results.is_empty() {
        let body = crate::utils::strip_html(html).trim().to_string();
        let first_id = format_first_id(&chapter.name);
        let url = format!("{}#{}", output_path, first_id);
        let breadcrumbs = build_breadcrumbs(parent_hierarchy, &chapter.name, &chapter.name);
        results.push((url, chapter.name.clone(), body, breadcrumbs));
    }
}

fn build_breadcrumbs(parents: &str, chapter_name: &str, section_title: &str) -> String {
    let mut parts = Vec::new();

    if !parents.is_empty() {
        // Add parent chapter names
        for p in parents.split(" » ") {
            parts.push(p.to_string());
        }
    }

    if section_title != chapter_name {
        if !parts.contains(&chapter_name.to_string()) {
            parts.push(chapter_name.to_string());
        }
        parts.push(section_title.to_string());
    } else {
        parts.push(chapter_name.to_string());
        parts.push(section_title.to_string());
    }

    parts.join(" \u{00BB} ")
}

fn format_first_id(title: &str) -> String {
    id_from_content(title)
}

enum HtmlSegment {
    Heading(u8, String, String), // level, id, text
    Content(String),
}

fn split_by_headings(html: &str) -> Vec<HtmlSegment> {
    let mut segments = Vec::new();
    let mut current_content = String::new();
    let mut i = 0;
    let bytes = html.as_bytes();

    while i < html.len() {
        // Check for heading tag
        if html[i..].starts_with("<h") && i + 2 < html.len() {
            let level_char = html.as_bytes().get(i + 2).copied().unwrap_or(0) as char;
            if level_char >= '1' && level_char <= '6' {
                // Check for id attribute  
                if !current_content.is_empty() {
                    segments.push(HtmlSegment::Content(current_content.clone()));
                    current_content.clear();
                }

                // Find the end of the heading tag and extract id
                if let Some(end) = html[i..].find("</h") {
                    let heading_html = &html[i..i+end+5];
                    let level = (level_char as u8) - b'0';
                    let id = extract_id_from_heading(heading_html);
                    let text = extract_text_from_heading(heading_html);
                    segments.push(HtmlSegment::Heading(level, id, text));

                    // Find the complete closing tag
                    if let Some(close_end) = html[i+end..].find('>') {
                        i += end + close_end + 1;
                    } else {
                        i += end + 5;
                    }
                    continue;
                }
            }
        }

        current_content.push(html.as_bytes()[i] as char);
        i += 1;
    }

    if !current_content.is_empty() {
        segments.push(HtmlSegment::Content(current_content));
    }

    segments
}

fn extract_id_from_heading(html: &str) -> String {
    // Extract id="..." attribute
    if let Some(id_pos) = html.find("id=\"") {
        let start = id_pos + 4;
        if let Some(end) = html[start..].find('"') {
            return html[start..start+end].to_string();
        }
    }
    String::new()
}

fn extract_text_from_heading(html: &str) -> String {
    // Extract the text content of the heading (strip HTML tags)
    crate::utils::strip_html(html)
