}

fn do_test(
    book_dir: &Path,
    dest_dir_override: Option<&str>,
    chapter: Option<&str>,
    library_path: Option<&str>,
) -> Result<(), String> {
    let config = load_config(book_dir)?;
    let src_dir = book_dir.join(&config.book.src);

    let mut book = load_book(book_dir, &config, None)?;
    preprocess(&mut book, &src_dir, config.build.use_default_preprocessors)?;

    // Find all rust code blocks and test them
    let chapters = crate::book::flatten_book(&book.sections);

    for ch in chapters {
        if let Some(filter) = chapter {
            if ch.name != filter {
                continue;
            }
        }

        test_chapter(ch, book_dir, library_path)?;
    }

    Ok(())
}

fn test_chapter(chapter: &crate::book::Chapter, book_dir: &Path, library_path: Option<&str>) -> Result<(), String> {
    // Extract rust code blocks
    let content = &chapter.content;
    let mut in_rust_block = false;
    let mut current_block = Vec::new();
    let mut block_attrs = String::new();

    for line in content.lines() {
        if !in_rust_block {
            if line.trim_start().starts_with("```") {
                let rest = line.trim_start().trim_start_matches('`');
                let attrs: Vec<&str> = rest.split(',').collect();
                let base_lang = attrs[0].trim();
                if base_lang == "rust" {
                    let has_ignore = attrs.iter().any(|&a| a.trim() == "ignore");
                    let has_no_run = attrs.iter().any(|&a| a.trim() == "no_run");
                    if !has_ignore {
                        in_rust_block = true;
                        block_attrs = rest.to_string();
                        current_block.clear();
                    }
                }
            }
        } else {
            if line.trim_start().starts_with("```") {
                // End of block
                in_rust_block = false;
                // Test this block
                let attrs: Vec<&str> = block_attrs.split(',').collect();
                let has_no_run = attrs.iter().any(|&a| a.trim() == "no_run");

                let code = process_rust_test_block(&current_block);

                let result = run_rustdoc_test(&code, book_dir, library_path, has_no_run);
                match result {
                    Ok(_) => {}
                    Err(e) => {
                        eprintln!("Error testing chapter '{}': {}", chapter.name, e);
                    }
                }

                current_block.clear();
            } else {
                current_block.push(line.to_string());
            }
        }
    }

    Ok(())
}

fn process_rust_test_block(lines: &[String]) -> String {
    // Process hidden lines (# prefix)
    let mut code = String::new();
    for line in lines {
        if line.starts_with("# ") {
            code.push_str(&line[2..]);
            code.push('\n');
        } else if line == "#" {
            code.push('\n');
        } else {
            code.push_str(line);
            code.push('\n');
        }
    }
    code
}

fn run_rustdoc_test(code: &str, book_dir: &Path, library_path: Option<&str>, no_run: bool) -> Result<(), String> {
    // Write code to temp file and run rustdoc test
    use std::io::Write;

    let tmp = std::env::temp_dir().join(format!("mdbook_test_{}.rs", 
        std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_nanos()));

    std::fs::write(&tmp, code).map_err(|e| e.to_string())?;

    let mut cmd = std::process::Command::new("rustdoc");
    cmd.arg("--test").arg(&tmp);

    if let Some(lp) = library_path {
        for path in lp.split(',') {
            cmd.arg("-L").arg(path.trim());
        }
    }

    if no_run {
        // Just compile, don't run
        cmd.arg("--no-run");
    }

    let output = cmd.output().map_err(|e| e.to_string())?;

    // Clean up
    let _ = std::fs::remove_file(&tmp);

    if !output.status.success() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        return Err(format!("Test failed: {}", stderr));
    }

    Ok(())
}

pub fn cmd_clean(args: &[String]) -> Result<(), String> {
    let parser = ArgParser::new(args);

    if parser.has_flag(&["-h", "--help"]) {
        println!("{}", CLEAN_HELP);
        return Ok(());
    }
    if parser.has_flag(&["-V", "--version"]) {
        println!("mdbook v0.5.0-alpha.1");
        return Ok(());
    }

    let dir = parser.get_positional().unwrap_or(".");
