struct ArgParser<'a> {
    args: &'a [String],
    pos: usize,
}

impl<'a> ArgParser<'a> {
    fn new(args: &'a [String]) -> Self {
        ArgParser { args, pos: 0 }
    }

    fn has_flag(&self, flags: &[&str]) -> bool {
        self.args.iter().any(|a| flags.contains(&a.as_str()))
    }

    fn get_value(&self, flags: &[&str]) -> Option<&str> {
        for i in 0..self.args.len() {
            let a = &self.args[i];
            for flag in flags {
                if a == flag {
                    return self.args.get(i + 1).map(|s| s.as_str());
                }
                if let Some(val) = a.strip_prefix(&format!("{}=", flag)) {
                    return Some(val);
                }
            }
        }
        None
    }

    fn get_positional(&self) -> Option<&str> {
        self.args.iter().find(|a| !a.starts_with('-')).map(|s| s.as_str())
    }

    fn check_help_version(&self) -> bool {
        if self.has_flag(&["-h", "--help"]) || self.has_flag(&["-V", "--version"]) {
            true
        } else {
            false
        }
    }
}

pub fn cmd_init(args: &[String]) -> Result<(), String> {
    let parser = ArgParser::new(args);

    if parser.has_flag(&["-h", "--help"]) {
        println!("{}", INIT_HELP);
        return Ok(());
    }
    if parser.has_flag(&["-V", "--version"]) {
        println!("mdbook v0.5.0-alpha.1");
        return Ok(());
    }

    let dir = parser.get_positional().unwrap_or(".");
    let book_dir = PathBuf::from(dir);

    let copy_theme = parser.has_flag(&["--theme"]);
    let force = parser.has_flag(&["--force"]);
    let title = parser.get_value(&["--title"]);
    let ignore = parser.get_value(&["--ignore"]);

    do_init(&book_dir, copy_theme, force, title, ignore)
}

fn do_init(
    book_dir: &Path,
    copy_theme: bool,
    force: bool,
    title: Option<&str>,
    ignore: Option<&str>,
) -> Result<(), String> {
    // Determine title
    let book_title = if let Some(t) = title {
        t.to_string()
    } else if force {
        // Use default
        std::env::var("USER").unwrap_or_else(|_| "mini-swe-agent".to_string())
        // Actually the default title in force mode uses the git author
        // Let's just use a fallback
    } else {
        // Interactive prompt
        print!("What title would you like to give the book? ");
        io::stdout().flush().ok();
        let mut input = String::new();
        io::stdin().read_line(&mut input).ok();
        input.trim().to_string()
    };

    // Create directories
    std::fs::create_dir_all(book_dir).map_err(|e| e.to_string())?;

    let src_dir = book_dir.join("src");
    std::fs::create_dir_all(&src_dir).map_err(|e| e.to_string())?;

    let book_output_dir = book_dir.join("book");
    std::fs::create_dir_all(&book_output_dir).map_err(|e| e.to_string())?;

    // Create book.toml if it doesn't exist
    let toml_path = book_dir.join("book.toml");
    if !toml_path.exists() {
        // Get system username for authors
        let author = std::env::var("USER")
            .or_else(|_| std::env::var("USERNAME"))
            .unwrap_or_else(|_| "mini-swe-agent".to_string());

        let toml_content = format!(
            "[book]\nauthors = [\"{author}\"]\nlanguage = \"en\"\nsrc = \"src\"\ntitle = \"{title}\"\n",
            author = author,
            title = book_title.replace('"', "\\\""),
        );
        std::fs::write(&toml_path, &toml_content).map_err(|e| e.to_string())?;
    }

    // Create SUMMARY.md if it doesn't exist
    let summary_path = src_dir.join("SUMMARY.md");
    if !summary_path.exists() {
        std::fs::write(&summary_path, "# Summary\n\n- [Chapter 1](./chapter_1.md)\n")
            .map_err(|e| e.to_string())?;
    } else {
        // Parse existing SUMMARY.md and create missing files
        let summary = std::fs::read_to_string(&summary_path).map_err(|e| e.to_string())?;
        let book = parse_summary_v2(&summary)?;
        crate::book::create_missing_from_summary(&book.sections, &src_dir)?;
    }

    // Create chapter_1.md if it doesn't exist
    let ch1_path = src_dir.join("chapter_1.md");
    if !ch1_path.exists() {
        std::fs::write(&ch1_path, "# Chapter 1\n").map_err(|e| e.to_string())?;
    }

    // Copy theme if requested
    if copy_theme {
        let theme_dir = src_dir.join("theme");
        eprintln!("\nCopying the default theme to {}", theme_dir.display());
        crate::theme::copy_theme_to_dir(&theme_dir)?;
    }

    // Handle gitignore
    let should_create_gitignore = if let Some(ig) = ignore {
        ig == "git"
    } else if force {
        false
    } else {
        // Interactive prompt
        print!("Do you want a .gitignore to be created? (y/n) ");
        io::stdout().flush().ok();
        let mut input = String::new();
        io::stdin().read_line(&mut input).ok();
        input.trim().to_lowercase() == "y"
    };

    if should_create_gitignore {
        let gitignore_path = book_dir.join(".gitignore");
        let gitignore_content = "book\n";
        std::fs::write(&gitignore_path, gitignore_content).map_err(|e| e.to_string())?;
    }

    log_info("mdbook_driver::init", "Creating a new book with stub content");
    println!("\nAll done, no errors...");

    Ok(())
}

