pub fn resolve_dest_dir(book_dir: &Path, config: &Config, override_dir: Option<&str>) -> PathBuf {
    if let Some(d) = override_dir {
        let p = PathBuf::from(d);
        if p.is_absolute() {
            p
        } else {
            book_dir.join(p)
        }
    } else {
        let p = &config.build.build_dir;
        if p.is_absolute() {
            p.clone()
        } else {
            book_dir.join(p)
        }
    }
}
