    let port = parser.get_value(&["-p", "--port"]).unwrap_or("3000");
    let watcher = parser.get_value(&["--watcher"]).unwrap_or("poll");

    crate::serve::do_serve(&book_dir, dest_dir_override, open_browser, hostname, port, watcher)
}

pub fn load_config(book_dir: &Path) -> Result<Config, String> {
    let toml_path = book_dir.join("book.toml");
    if toml_path.exists() {
        Config::from_file(&toml_path)
    } else {
        Ok(Config::default())
    }
}

pub fn resolve_dest_dir(book_dir: &Path, config: &Config, override_dir: Option<&str>) -> PathBuf {
    if let Some(d) = override_dir {
        let p = PathBuf::from(d);
        if p.is_absolute() {
            p
        } else {
            book_dir.join(p)
        }
    } else {
        let p = &config.build.build_dir;
        if p.is_absolute() {
            p.clone()
        } else {
            book_dir.join(p)
        }
    }
}
