pub fn build_book(book_dir: &Path, config: &Config, dest_dir: &Path) -> Result<(), String> {
    let src_dir = book_dir.join(&config.book.src);

    // Load book
    let mut book = load_book(book_dir, config, Some(dest_dir))?;

    // Apply preprocessors
    preprocess(&mut book, &src_dir, config.build.use_default_preprocessors)?;

    // Assign section numbers
    number_book(&mut book);
    set_parent_names(&mut book);

    let html_config = config.get_html_config();
    let theme_dir = html_config.theme.as_deref().map(|p| {
        if p.is_absolute() { p.to_path_buf() } else { book_dir.join(p) }
    });

    let renderer = HtmlRenderer::new(html_config, theme_dir.as_deref());

    let book_title = config.book.title.as_deref().unwrap_or("");
    renderer.render(&book, dest_dir, book_title, config)?;

    // Copy non-MD source files
    copy_source_files(&src_dir, dest_dir)?;

    Ok(())
}

fn open_book(dest_dir: &Path) {
    let index = dest_dir.join("index.html");
    let path = index.to_string_lossy().to_string();

    #[cfg(target_os = "linux")]
    let _ = std::process::Command::new("xdg-open").arg(&path).spawn();
    #[cfg(target_os = "macos")]
    let _ = std::process::Command::new("open").arg(&path).spawn();
    #[cfg(target_os = "windows")]
    let _ = std::process::Command::new("cmd").args(&["/c", "start", &path]).spawn();
}

