    build_book(book_dir, &config, &dest_dir)?;
    log_info("mdbook_html::html_handlebars::hbs_renderer", 
        &format!("HTML book written to `{}`", dest_dir.display()));

    if open_browser {
        crate::cli::open_book_pub(&dest_dir);
    }

    eprintln!("Watching for changes...");

    // Poll for changes
    let src_dir = book_dir.join(&config.book.src);
    let mut file_times: HashMap<PathBuf, SystemTime> = HashMap::new();

    // Initialize file times
    collect_file_times(&src_dir, &mut file_times);
    collect_file_times(book_dir, &mut file_times);

    loop {
        std::thread::sleep(Duration::from_millis(500));

        let mut changed = false;
        let mut new_times: HashMap<PathBuf, SystemTime> = HashMap::new();
        collect_file_times(&src_dir, &mut new_times);
        if let Ok(_) = book_dir.join("book.toml").metadata() {
            if let Ok(mtime) = book_dir.join("book.toml").metadata().map(|m| m.modified().unwrap_or(SystemTime::UNIX_EPOCH)) {
                if file_times.get(&book_dir.join("book.toml")).copied() != Some(mtime) {
                    changed = true;
                }
                new_times.insert(book_dir.join("book.toml"), mtime);
            }
        }

        for (path, time) in &new_times {
            if file_times.get(path) != Some(time) {
                changed = true;
                break;
            }
        }

        if changed {
            file_times = new_times;

            // Rebuild
            match load_config(book_dir) {
                Ok(new_config) => {
                    let new_dest = resolve_dest_dir(book_dir, &new_config, dest_dir_override);
                    log_info("mdbook_driver::mdbook", "Book building has started");
                    log_info("mdbook_driver::mdbook", "Running the html backend");
                    match build_book(book_dir, &new_config, &new_dest) {
                        Ok(_) => {
                            log_info("mdbook_html::html_handlebars::hbs_renderer",
                                &format!("HTML book written to `{}`", new_dest.display()));
                        }
                        Err(e) => eprintln!("Build error: {}", e),
                    }
                }
                Err(e) => eprintln!("Config error: {}", e),
            }
        }
    }
}

fn collect_file_times(dir: &Path, times: &mut HashMap<PathBuf, SystemTime>) {
    if let Ok(entries) = std::fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                if name != "book" && name != ".git" && !name.starts_with('.') {
                    collect_file_times(&path, times);
                }
            } else {
                if let Ok(meta) = path.metadata() {
                    if let Ok(mtime) = meta.modified() {
                        times.insert(path, mtime);
                    }
                }
            }
        }
    }
}
