use std::path::{Path, PathBuf};
use std::net::{TcpListener, TcpStream};
use std::io::{Read, Write, BufRead, BufReader};
use std::time::{Duration, SystemTime};
use std::collections::HashMap;
use crate::config::Config;
use crate::cli::{load_config, resolve_dest_dir, build_book};
use crate::utils::log_info;

pub fn do_serve(
    book_dir: &Path,
    dest_dir_override: Option<&str>,
    open_browser: bool,
    hostname: &str,
    port: &str,
    watcher: &str,
) -> Result<(), String> {
    let config = load_config(book_dir)?;
    let dest_dir = resolve_dest_dir(book_dir, &config, dest_dir_override);

    // Initial build
    log_info("mdbook_driver::mdbook", "Book building has started");
    log_info("mdbook_driver::mdbook", "Running the html backend");
    build_book(book_dir, &config, &dest_dir)?;
    log_info("mdbook_html::html_handlebars::hbs_renderer",
        &format!("HTML book written to `{}`", dest_dir.display()));

    let addr = format!("{}:{}", hostname, port);
    let listener = TcpListener::bind(&addr)
        .map_err(|e| format!("Failed to bind to {}: {}", addr, e))?;

    eprintln!("Serving on: http://{}", addr);

    if open_browser {
        let url = format!("http://{}", addr);
        #[cfg(target_os = "linux")]
        let _ = std::process::Command::new("xdg-open").arg(&url).spawn();
        #[cfg(target_os = "macos")]
        let _ = std::process::Command::new("open").arg(&url).spawn();
    }

    let dest_dir_arc = dest_dir.clone();
    let book_dir_arc = book_dir.to_path_buf();

    // Start file watcher thread
    let book_dir_watch = book_dir.to_path_buf();
    let dest_dir_watch = dest_dir.clone();
    let dest_dir_override_str = dest_dir_override.map(|s| s.to_string());

    std::thread::spawn(move || {
        let src_dir = book_dir_watch.join(
            load_config(&book_dir_watch).map(|c| c.book.src.clone())
                .unwrap_or_else(|_| "src".to_string())
        );
        let mut file_times: HashMap<PathBuf, SystemTime> = HashMap::new();
        collect_file_times(&src_dir, &mut file_times);

        loop {
            std::thread::sleep(Duration::from_millis(500));

            let mut new_times: HashMap<PathBuf, SystemTime> = HashMap::new();
            collect_file_times(&src_dir, &mut new_times);

            let changed = new_times.iter().any(|(p, t)| file_times.get(p) != Some(t))
                || file_times.iter().any(|(p, _)| !new_times.contains_key(p));

            if changed {
                file_times = new_times;

                if let Ok(new_config) = load_config(&book_dir_watch) {
                    let new_dest = resolve_dest_dir(
                        &book_dir_watch, &new_config, 
                        dest_dir_override_str.as_deref()
                    );
                    log_info("mdbook_driver::mdbook", "Book building has started");
                    log_info("mdbook_driver::mdbook", "Running the html backend");
                    match build_book(&book_dir_watch, &new_config, &new_dest) {
                        Ok(_) => log_info("mdbook_html::html_handlebars::hbs_renderer",
                            &format!("HTML book written to `{}`", new_dest.display())),
                        Err(e) => eprintln!("Build error: {}", e),
                    }
                }
            }
        }
    });

    // Handle connections
    for stream in listener.incoming() {
        match stream {
            Ok(stream) => {
                let dest = dest_dir_arc.clone();
                std::thread::spawn(move || {
                    handle_connection(stream, &dest);
                });
            }
            Err(e) => eprintln!("Connection error: {}", e),
        }
    }

    Ok(())
}

fn handle_connection(mut stream: TcpStream, serve_dir: &Path) {
    let mut reader = BufReader::new(stream.try_clone().unwrap());
    let mut request_line = String::new();

    if reader.read_line(&mut request_line).is_err() {
        return;
    }

    // Parse request
    let parts: Vec<&str> = request_line.trim().split(' ').collect();
    if parts.len() < 2 {
        return;
    }

    let method = parts[0];
    let raw_path = parts[1];

    // Read headers
    loop {
        let mut line = String::new();
        if reader.read_line(&mut line).is_err() { break; }
        if line.trim().is_empty() { break; }
    }

    // Handle WebSocket upgrade for live reload
    if raw_path == "/ws" || raw_path.starts_with("/ws") {
        // Live reload WebSocket - simplified
        let response = "HTTP/1.1 400 Bad Request\r\nContent-Length: 0\r\n\r\n";
        let _ = stream.write_all(response.as_bytes());
        return;
    }

    // Decode URL
    let path = decode_url(raw_path);
    let path = if path == "/" { "/index.html".to_string() } else { path };

    // Strip leading /
    let file_path = serve_dir.join(path.trim_start_matches('/'));

    // Try to serve the file
    let (status, content_type, body) = if file_path.is_dir() {
        let index = file_path.join("index.html");
        if index.exists() {
            match std::fs::read(&index) {
                Ok(data) => ("200 OK", "text/html", data),
                Err(_) => ("500 Internal Server Error", "text/plain", b"Error".to_vec()),
            }
        } else {
            ("404 Not Found", "text/plain", b"Not Found".to_vec())
        }
    } else if file_path.exists() {
        match std::fs::read(&file_path) {
            Ok(data) => {
                let ct = content_type_for_path(&file_path);
                ("200 OK", ct, data)
            }
            Err(_) => ("500 Internal Server Error", "text/plain", b"Error".to_vec()),
        }
    } else {
        // Try 404.html
        let not_found = serve_dir.join("404.html");
        if not_found.exists() {
            match std::fs::read(&not_found) {
                Ok(data) => ("404 Not Found", "text/html", data),
                Err(_) => ("404 Not Found", "text/plain", b"Not Found".to_vec()),
            }
        } else {
            ("404 Not Found", "text/plain", b"Not Found".to_vec())
        }
    };

    let response = format!(
        "HTTP/1.1 {}\r\nContent-Type: {}\r\nContent-Length: {}\r\nConnection: close\r\n\r\n",
        status, content_type, body.len()
    );

    let _ = stream.write_all(response.as_bytes());
    let _ = stream.write_all(&body);
}

fn content_type_for_path(path: &Path) -> &'static str {
    match path.extension().and_then(|e| e.to_str()) {
        Some("html") => "text/html; charset=utf-8",
        Some("css") => "text/css",
        Some("js") => "application/javascript",
        Some("json") => "application/json",
        Some("png") => "image/png",
        Some("svg") => "image/svg+xml",
        Some("ico") => "image/x-icon",
        Some("woff") => "font/woff",
        Some("woff2") => "font/woff2",
        Some("ttf") => "font/ttf",
        Some("eot") => "application/vnd.ms-fontobject",
        Some("txt") => "text/plain",
        _ => "application/octet-stream",
    }
}

fn decode_url(s: &str) -> String {
    let mut result = String::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            if let Ok(hex) = std::str::from_utf8(&bytes[i+1..i+3]) {
                if let Ok(b) = u8::from_str_radix(hex, 16) {
                    result.push(b as char);
                    i += 3;
                    continue;
                }
            }
        }
        if bytes[i] == b'?' {
            break; // Stop at query string
        }
        result.push(bytes[i] as char);
        i += 1;
    }
    result
}

fn collect_file_times(dir: &Path, times: &mut HashMap<PathBuf, SystemTime>) {
    if let Ok(entries) = std::fs::read_dir(dir) {
