        Some("html") => "text/html; charset=utf-8",
        Some("css") => "text/css",
        Some("js") => "application/javascript",
        Some("json") => "application/json",
        Some("png") => "image/png",
        Some("svg") => "image/svg+xml",
        Some("ico") => "image/x-icon",
        Some("woff") => "font/woff",
        Some("woff2") => "font/woff2",
        Some("ttf") => "font/ttf",
        Some("eot") => "application/vnd.ms-fontobject",
        Some("txt") => "text/plain",
        _ => "application/octet-stream",
    }
}

fn decode_url(s: &str) -> String {
    let mut result = String::new();
    let bytes = s.as_bytes();
    let mut i = 0;
    while i < bytes.len() {
        if bytes[i] == b'%' && i + 2 < bytes.len() {
            if let Ok(hex) = std::str::from_utf8(&bytes[i+1..i+3]) {
                if let Ok(b) = u8::from_str_radix(hex, 16) {
                    result.push(b as char);
                    i += 3;
                    continue;
                }
            }
        }
        if bytes[i] == b'?' {
            break; // Stop at query string
        }
        result.push(bytes[i] as char);
        i += 1;
    }
    result
}

fn collect_file_times(dir: &Path, times: &mut HashMap<PathBuf, SystemTime>) {
    if let Ok(entries) = std::fs::read_dir(dir) {
        for entry in entries.flatten() {
            let path = entry.path();
            if path.is_dir() {
                let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
                if name != "book" && name != ".git" && !name.starts_with('.') {
                    collect_file_times(&path, times);
                }
            } else {
                if let Ok(meta) = path.metadata() {
                    if let Ok(mtime) = meta.modified() {
                        times.insert(path, mtime);
                    }
                }
            }
        }
    }
}
