    }

    fn build_toc_html(&self, sections: &[BookItem], with_target: bool) -> String {
        let items_html = self.build_toc_items(sections, with_target);
        format!("<ol class=\"chapter\">{}</ol>", items_html)
    }

    fn build_toc_items(&self, items: &[BookItem], with_target: bool) -> String {
        let mut html = String::new();

        for item in items {
            match item {
                BookItem::Chapter(ch) => {
                    let is_affix = ch.is_prefix || ch.is_suffix;
                    let classes = if is_affix { "chapter-item expanded affix " } else { "chapter-item expanded " };
                    let target_attr = if with_target { " target=\"_parent\"" } else { "" };

                    let link_html = if let Some(path) = &ch.path {
                        let path_str = path.to_string_lossy();
                        let html_path = if path_str.ends_with(".md") {
                            format!("{}.html", &path_str[..path_str.len()-3])
                        } else {
                            path_str.to_string()
                        };
                        let html_path = html_path.replace('\\', "/");

                        if is_affix {
                            format!("<a href=\"{}\"{}>{}</a>", html_path, target_attr, escape_html(&ch.name))
                        } else if let Some(num) = &ch.number {
                            format!("<a href=\"{}\"{} ><strong aria-hidden=\"true\">{}</strong> {}</a>",
                                html_path, target_attr, num_to_display(num), escape_html(&ch.name))
                        } else {
                            format!("<a href=\"{}\"{}>{}</a>", html_path, target_attr, escape_html(&ch.name))
                        }
                    } else {
                        if let Some(num) = &ch.number {
                            format!("<div><strong aria-hidden=\"true\">{}</strong> {}</div>",
                                num_to_display(num), escape_html(&ch.name))
                        } else {
                            format!("<div>{}</div>", escape_html(&ch.name))
                        }
                    };

                    html.push_str(&format!("<li class=\"{}\">{}</li>", classes, link_html));

                    if !ch.sub_items.is_empty() {
                        html.push_str("<li><ol class=\"section\">");
                        html.push_str(&self.build_toc_items(&ch.sub_items, with_target));
                        html.push_str("</ol></li>");
                    }
                }
                BookItem::Separator => {
                    html.push_str("<li class=\"chapter-item expanded affix \">");
                    html.push_str("<li class=\"spacer\"></li>");
                }
                BookItem::PartTitle(title) => {
                    html.push_str("<li class=\"chapter-item expanded affix \">");
                    html.push_str(&format!("<li class=\"part-title\">{}</li>", escape_html(title)));
                }
            }
        }

        html
    }

    fn generate_toc_js(&self, toc_html: &str) -> String {
        let toc_template = include_str!("../theme_default/toc_template.js");
        let toc_escaped = toc_html.replace('\\', "\\\\").replace('\'', "\\'");
        toc_template.replace("MDBOOK_TOC_HTML_PLACEHOLDER", &toc_escaped)
    }
}

fn num_to_display(num: &SectionNumber) -> String {
    format!("{}.", num.display())
}

fn get_text_direction(config: &Config) -> &str {
    config.book.text_direction.as_deref().unwrap_or("ltr")
}

fn collect_chapters<'a>(sections: &'a Vec<BookItem>) -> Vec<ChapterInfo<'a>> {
    let mut result = Vec::new();
    collect_chapters_impl(sections, &[], &mut result);
    result
}

fn collect_chapters_impl<'a>(
    items: &'a Vec<BookItem>,
    parent_names: &[&str],
    result: &mut Vec<ChapterInfo<'a>>
) {
    for item in items {
        if let BookItem::Chapter(ch) = item {
            let parents_str = if parent_names.is_empty() {
                None
            } else {
                Some(parent_names.join(" \u{00BB} "))
            };
            result.push(ChapterInfo { chapter: ch, parents: parents_str });

            let mut new_parents = parent_names.to_vec();
            new_parents.push(&ch.name);
            collect_chapters_impl(&ch.sub_items, &new_parents, result);
        }
    }
}

fn get_chapter_output_path(chapter: &Chapter) -> String {
    if let Some(path) = &chapter.path {
        let s = path.to_string_lossy().replace('\\', "/");
        if s.ends_with(".md") {
            format!("{}.html", &s[..s.len()-3])
        } else {
            s.to_string()
        }
    } else {
        String::new()
    }
}

struct Section {
    id: String,
    title: String,
    body: String,
}

fn collect_search_entries(
    html: &str,
    output_path: &str,
    chapter: &Chapter,
    parent_hierarchy: &str,
    results: &mut Vec<(String, String, String, String)>,
) {
    let mut parsed_sections: Vec<Section> = Vec::new();
    let mut current_id = String::new();
    let mut current_title = String::new();
    let mut current_body = String::new();

    for segment in split_by_headings(html) {
        match segment {
            HtmlSegment::Heading(_level, id, text) => {
                if !current_id.is_empty() {
                    parsed_sections.push(Section {
                        id: current_id.clone(),
                        title: current_title.clone(),
                        body: current_body.trim().to_string(),
                    });
                }
                current_id = id;
                current_title = text;
                current_body = String::new();
            }
            HtmlSegment::Content(text) => {
                let stripped = crate::utils::strip_html(&text);
                current_body.push_str(&stripped);
                current_body.push(' ');
            }
        }
    }

    if !current_id.is_empty() {
        parsed_sections.push(Section {
            id: current_id,
            title: current_title,
            body: current_body.trim().to_string(),
        });
    }

    for section in parsed_sections {
        let url = format!("{}#{}", output_path, section.id);
        let breadcrumbs = build_breadcrumbs(parent_hierarchy, &chapter.name, &section.title);
        results.push((url, section.title, section.body, breadcrumbs));
    }

    if results.is_empty() {
        let first_id = id_from_content(&chapter.name);
        let url = format!("{}#{}", output_path, first_id);
        let bc = build_breadcrumbs(parent_hierarchy, &chapter.name, &chapter.name);
        let body = crate::utils::strip_html(html).trim().to_string();
        results.push((url, chapter.name.clone(), body, bc));
    }
}

fn build_breadcrumbs(parents: &str, chapter_name: &str, section_title: &str) -> String {
    let mut parts = Vec::new();
    if !parents.is_empty() {
        for p in parents.split(" \u{00BB} ") {
            if !p.is_empty() { parts.push(p.to_string()); }
        }
    }
    if section_title != chapter_name {
        if !parts.contains(&chapter_name.to_string()) {
            parts.push(chapter_name.to_string());
        }
        parts.push(section_title.to_string());
    } else {
        parts.push(chapter_name.to_string());
        parts.push(section_title.to_string());
    }
    parts.join(" \u{00BB} ")
}

enum HtmlSegment {
    Heading(u8, String, String),
    Content(String),
}

fn split_by_headings(html: &str) -> Vec<HtmlSegment> {
    let mut segments = Vec::new();
    let mut current_content = String::new();
    let mut i = 0;

    while i < html.len() {
        // Check for heading tag <h1-6 id="...">
        if html.as_bytes().get(i) == Some(&b'<') {
            let remaining = &html[i..];
            if remaining.len() > 3 {
                let level_byte = remaining.as_bytes().get(2);
                if remaining.starts_with("<h") && matches!(level_byte, Some(b'1'..=b'6')) {
                    if let Some(end_pos) = find_heading_end(remaining) {
                        let heading_html = &remaining[..end_pos];
                        if !current_content.is_empty() {
                            segments.push(HtmlSegment::Content(current_content.clone()));
                            current_content.clear();
                        }
                        let level = (level_byte.unwrap() - b'0') as u8;
                        let id = extract_id_attr(heading_html);
                        let text = crate::utils::strip_html(heading_html).trim().to_string();
                        segments.push(HtmlSegment::Heading(level, id, text));
                        i += end_pos;
                        continue;
                    }
                }
            }
        }

        if i < html.len() {
            current_content.push(html.chars().nth(i).unwrap_or(' '));
            i += 1;
        }
    }

    if !current_content.is_empty() {
        segments.push(HtmlSegment::Content(current_content));
    }

    segments
}

fn find_heading_end(html: &str) -> Option<usize> {
    // Find the closing </h?> tag
    let level = html.as_bytes().get(2)? as char;
    let close_tag = format!("</h{}>", level);
    html.find(&close_tag).map(|p| p + close_tag.len())
}

fn extract_id_attr(html: &str) -> String {
    if let Some(pos) = html.find("id=\"") {
        let start = pos + 4;
        if let Some(end) = html[start..].find('"') {
            return html[start..start+end].to_string();
        }
    }
    String::new()
}

fn generate_redirect_html(to_url: &str) -> String {
    format!(
        "<!DOCTYPE html>\n<html>\n  <head>\n    <title>Redirect</title>\n    <meta http-equiv=\"refresh\" content=\"0; URL={}\" />\n  </head>\n  <body>\n    <p><a href=\"{}\">Click here if you are not redirected.</a></p>\n  </body>\n</html>\n",
        escape_html(to_url), escape_html(to_url)
    )
}

pub fn copy_source_files(src_dir: &Path, dest_dir: &Path) -> Result<(), String> {
    copy_dir_files(src_dir, dest_dir, src_dir)
}

fn copy_dir_files(dir: &Path, dest_base: &Path, src_base: &Path) -> Result<(), String> {
    let entries = std::fs::read_dir(dir).map_err(|e| e.to_string())?;
    for entry in entries.flatten() {
        let path = entry.path();
        if path.is_dir() {
            let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("");
            if !name.starts_with('.') {
                copy_dir_files(&path, dest_base, src_base)?;
            }
        } else {
            let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
            if ext != "md" {
                if let Ok(rel) = path.strip_prefix(src_base) {
                    let dest = dest_base.join(rel);
                    if let Some(parent) = dest.parent() {
                        std::fs::create_dir_all(parent).map_err(|e| e.to_string())?;
                    }
                    std::fs::copy(&path, &dest).map_err(|e| e.to_string())?;
                }
            }
        }
    }
    Ok(())
}
