    fn render_chapter(
        &self,
        chapter: &Chapter,
        book_title: &str,
        config: &Config,
        _toc_html: &str,
        path_to_root_str: &str,
        prev: Option<&ChapterInfo>,
        next: Option<&ChapterInfo>,
    ) -> Result<String, String> {
        let content_html = markdown_to_html(&chapter.content, None);

        let title = if book_title.is_empty() {
            chapter.name.clone()
        } else {
            format!("{} - {}", chapter.name, book_title)
        };

        let ptr = path_to_root_str;

        let prev_html = prev.map(|p| {
            let path = get_chapter_output_path(p.chapter);
            format!(
                "<a rel=\"prev\" href=\"{ptr}{path}\" class=\"mobile-nav-chapters previous\" title=\"Previous chapter\" aria-label=\"Previous chapter\" aria-keyshortcuts=\"Left\">\n                                <i class=\"fa fa-angle-left\"></i>\n                            </a>",
                ptr=ptr, path=path
            )
        }).unwrap_or_default();

        let next_html = next.map(|n| {
            let path = get_chapter_output_path(n.chapter);
            format!(
                "<a rel=\"next prefetch\" href=\"{ptr}{path}\" class=\"mobile-nav-chapters next\" title=\"Next chapter\" aria-label=\"Next chapter\" aria-keyshortcuts=\"Right\">\n                                <i class=\"fa fa-angle-right\"></i>\n                            </a>",
                ptr=ptr, path=path
            )
        }).unwrap_or_default();

        let prev_html_wide = prev.map(|p| {
            let path = get_chapter_output_path(p.chapter);
            format!(
                "<a rel=\"prev\" href=\"{ptr}{path}\" class=\"nav-chapters previous\" title=\"Previous chapter\" aria-label=\"Previous chapter\" aria-keyshortcuts=\"Left\">\n                    <i class=\"fa fa-angle-left\"></i>\n                </a>",
                ptr=ptr, path=path
            )
        }).unwrap_or_default();

        let next_html_wide = next.map(|n| {
            let path = get_chapter_output_path(n.chapter);
            format!(
                "<a rel=\"next prefetch\" href=\"{ptr}{path}\" class=\"nav-chapters next\" title=\"Next chapter\" aria-label=\"Next chapter\" aria-keyshortcuts=\"Right\">\n                    <i class=\"fa fa-angle-right\"></i>\n                </a>",
                ptr=ptr, path=path
            )
        }).unwrap_or_default();

        Ok(self.generate_page_html(
            config, ptr, &title, &content_html,
            &prev_html, &next_html, &prev_html_wide, &next_html_wide,
            false, false, None
        ))
    }

    fn render_print_page(
        &self,
        chapters: &[ChapterInfo],
        book_title: &str,
        config: &Config,
    ) -> Result<String, String> {
        let html_config = &self.html_config;
        let mut all_content = String::new();

        for chapter_info in chapters {
            let ch = chapter_info.chapter;
            if ch.path.is_none() { continue; }
            let content_html = markdown_to_html(&ch.content, None);

            if html_config.print.page_break && !all_content.is_empty() {
                all_content.push_str("<div style=\"break-before: page;\"></div>\n");
            }
            all_content.push_str(&content_html);
        }

        Ok(self.generate_page_html(
            config, "", book_title, &all_content,
            "", "", "", "",
            true, false, None
        ))
    }

    fn render_404_page(&self, book_title: &str, config: &Config) -> String {
        let title = format!("Page not found - {}", book_title);
        let content = "<h1 class=\"menu-title\">Document not found (404)</h1>\n<p>This URL is invalid, sorry. Please use the navigation bar or search to continue.</p>";

        self.generate_page_html(
            config, "", &title, content,
            "", "", "", "",
            false, true, None
        )
    }

