use std::collections::HashMap;
use crate::utils::{id_from_content, escape_html, escape_html_code};

/// Convert markdown to HTML
pub fn markdown_to_html(content: &str, _src_dir: Option<&std::path::Path>) -> String {
    let mut parser = MarkdownParser::new();
    parser.parse(content)
}

struct MarkdownParser {
    heading_ids: HashMap<String, usize>,
}

impl MarkdownParser {
    fn new() -> Self {
        MarkdownParser {
            heading_ids: HashMap::new(),
        }
    }

    fn get_heading_id(&mut self, text: &str) -> String {
        let base = id_from_content(text);
        let count = self.heading_ids.entry(base.clone()).or_insert(0);
        let id = if *count == 0 {
            base.clone()
        } else {
            format!("{}-{}", base, count)
        };
        *count += 1;
        id
    }

    fn parse(&mut self, content: &str) -> String {
        let lines: Vec<&str> = content.lines().collect();
        self.parse_blocks(&lines)
    }

    fn parse_blocks(&mut self, lines: &[&str]) -> String {
        let mut output = String::new();
        let mut i = 0;

        while i < lines.len() {
            let line = lines[i];

            // Empty line
            if line.trim().is_empty() {
                i += 1;
                continue;
            }

            // ATX heading
            if let Some((level, text)) = parse_atx_heading(line) {
                let id = self.get_heading_id(&text);
                let html_text = render_inline(&text);
                output.push_str(&format!(
                    "<h{} id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h{}>\n",
                    level, id, id, html_text, level
                ));
                i += 1;
                continue;
            }

            // Setext heading
            if i + 1 < lines.len() {
                let next = lines[i + 1].trim();
                if !next.is_empty() && next.chars().all(|c| c == '=') && !line.trim().is_empty() {
                    let text = line.trim().to_string();
                    let id = self.get_heading_id(&text);
                    let html_text = render_inline(&text);
                    output.push_str(&format!("<h1 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h1>\n", id, id, html_text));
                    i += 2;
                    continue;
                }
                if !next.is_empty() && next.chars().all(|c| c == '-') && next.len() >= 2 && !line.trim().is_empty() {
                    let text = line.trim().to_string();
                    let id = self.get_heading_id(&text);
                    let html_text = render_inline(&text);
                    output.push_str(&format!("<h2 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h2>\n", id, id, html_text));
                    i += 2;
                    continue;
                }
            }

            // Thematic break (horizontal rule)
            if is_thematic_break(line) {
                output.push_str("<hr />\n");
                i += 1;
                continue;
            }

            // Fenced code block
            let trimmed = line.trim_start();
            if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
                let fence_char = if trimmed.starts_with("```") { '`' } else { '~' };
                let fence_count = trimmed.chars().take_while(|&c| c == fence_char).count();
                let fence_str: String = std::iter::repeat(fence_char).take(fence_count).collect();
                let indent = line.len() - trimmed.len();
                let lang = trimmed[fence_count..].trim().to_string();
                let mut code_lines = Vec::new();
                i += 1;
                while i < lines.len() {
                    let cl = lines[i];
                    let cl_trimmed = cl.trim_start();
                    if cl_trimmed.starts_with(&fence_str) {
                        let after = cl_trimmed[fence_str.len()..].trim();
                        if after.is_empty() || (!after.starts_with('`') && fence_char == '`') {
                            i += 1;
                            break;
                        }
                        if after.is_empty() || (!after.starts_with('~') && fence_char == '~') {
                            i += 1;
                            break;
                        }
                    }
                    // Remove block indent
                    let cl_stripped = if indent > 0 && cl.len() >= indent {
                        let avail_spaces = cl.len() - cl.trim_start().len();
                        if avail_spaces >= indent {
                            &cl[indent..]
                        } else {
                            cl.trim_start()
                        }
                    } else {
                        cl
                    };
                    code_lines.push(cl_stripped.to_string());
                    i += 1;
                }
                let code_html = render_code_block(&lang, &code_lines);
                output.push_str(&code_html);
                continue;
            }

            // Indented code block (4+ spaces)
            if (line.starts_with("    ") || line.starts_with("\t")) && !is_list_continuation(line) {
                let mut code_lines = Vec::new();
                while i < lines.len() {
                    let cl = lines[i];
                    if cl.trim().is_empty() {
                        code_lines.push(String::new());
                        i += 1;
                    } else if cl.starts_with("    ") {
                        code_lines.push(cl[4..].to_string());
                        i += 1;
                    } else if cl.starts_with("\t") {
                        code_lines.push(cl[1..].to_string());
                        i += 1;
                    } else {
                        break;
                    }
                }
                // Remove trailing empty lines
                while code_lines.last().map_or(false, |l: &String| l.trim().is_empty()) {
                    code_lines.pop();
                }
                let code_content: String = code_lines.iter()
                    .map(|l| escape_html_code(l))
                    .collect::<Vec<_>>()
                    .join("\n");
                output.push_str(&format!("<pre><code>{}\n</code></pre>\n", code_content));
                continue;
            }

            // HTML block
            if is_html_block_start(line) {
                let (html_content, consumed) = parse_html_block(&lines[i..]);
                output.push_str(&html_content);
                output.push('\n');
                i += consumed;
                continue;
            }

            // Blockquote
            if line.trim_start().starts_with(">") {
                let (bq_html, consumed) = self.parse_blockquote(&lines[i..]);
                output.push_str(&bq_html);
                i += consumed;
                continue;
            }

            // Table
            if i + 1 < lines.len() && is_table_separator(lines[i + 1]) && line.contains('|') {
                let (table_html, consumed) = self.parse_table(&lines[i..]);
                output.push_str(&table_html);
                i += consumed;
                continue;
            }

            // List
            if let Some(list_info) = get_list_info(line) {
                let (list_html, consumed) = self.parse_list_block(&lines[i..]);
                output.push_str(&list_html);
                i += consumed;
                continue;
            }

            // Paragraph
            let (para_html, consumed) = self.parse_paragraph(&lines[i..]);
            output.push_str(&para_html);
            i += consumed;
        }

        output
    }

    fn parse_blockquote<'a>(&mut self, lines: &[&'a str]) -> (String, usize) {
        let mut bq_lines: Vec<String> = Vec::new();
        let mut consumed = 0;

        for line in lines {
            let t = line.trim_start();
            if t.starts_with("> ") {
                bq_lines.push(t[2..].to_string());
                consumed += 1;
            } else if t == ">" {
                bq_lines.push(String::new());
                consumed += 1;
            } else if line.trim().is_empty() && consumed > 0 {
                // Check if next line is a continuation
                consumed += 1;
                break;
            } else {
                break;
            }
        }

        while bq_lines.last().map_or(false, |l| l.trim().is_empty()) {
            bq_lines.pop();
        }

        let refs: Vec<&str> = bq_lines.iter().map(|s| s.as_str()).collect();
        let inner_html = self.parse_blocks(&refs);

        (format!("<blockquote>\n{}</blockquote>\n", inner_html), consumed)
    }

    fn parse_table<'a>(&mut self, lines: &[&'a str]) -> (String, usize) {
        if lines.len() < 2 { return (String::new(), 0); }

        let headers = split_table_cells(lines[0]);
        let _seps = split_table_cells(lines[1]);

        let mut html = String::from("<div class=\"table-wrapper\"><table><thead><tr>");
        for h in &headers {
            html.push_str(&format!("<th>{}</th>", render_inline(h.trim())));
        }
        html.push_str("</tr></thead><tbody>\n");

        let mut consumed = 2;
        for line in &lines[2..] {
            if line.trim().is_empty() || !line.contains('|') { break; }
            let cells = split_table_cells(line);
            html.push_str("<tr>");
            for (idx, cell) in cells.iter().enumerate() {
                if idx < headers.len() {
                    html.push_str(&format!("<td>{}</td>", render_inline(cell.trim())));
                }
            }
            html.push_str("</tr>\n");
            consumed += 1;
        }

        html.push_str("</tbody></table>\n</div>\n");
        (html, consumed)
    }

    fn parse_paragraph<'a>(&mut self, lines: &[&'a str]) -> (String, usize) {
        let mut para_lines = Vec::new();
        let mut consumed = 0;

        for (idx, line) in lines.iter().enumerate() {
            if line.trim().is_empty() {
                consumed += 1;
                break;
            }
            // Setext heading detection
            if idx > 0 {
                let t = line.trim();
                if (t.chars().all(|c| c == '=') || t.chars().all(|c| c == '-')) && !t.is_empty() {
                    // This is a setext heading - handled by parse_blocks
                    para_lines.push(*line);
                    consumed += 1;
                    break;
                }
            }
            if consumed > 0 && (
                parse_atx_heading(line).is_some() ||
                line.trim_start().starts_with("```") ||
                line.trim_start().starts_with("~~~") ||
                line.trim_start().starts_with(">") ||
                is_unordered_list_start(line) ||
                is_ordered_list_start(line) ||
                is_html_block_start(line) ||
                is_thematic_break(line) ||
                (line.starts_with("    ") && !is_list_continuation(line))
            ) {
                break;
            }
            para_lines.push(*line);
            consumed += 1;
        }

        if para_lines.is_empty() {
            return (String::new(), consumed);
        }

        let text = para_lines.join("\n");
        let rendered = render_inline(&text);
        (format!("<p>{}</p>\n", rendered), consumed)
    }

    fn parse_list_block<'a>(&mut self, lines: &[&'a str]) -> (String, usize) {
        // Parse a list (possibly mixed tight/loose)
        let first_list_info = match get_list_info(lines[0]) {
            Some(info) => info,
            None => return (String::new(), 0),
        };

        let is_ordered = first_list_info.is_ordered;
        let base_indent = first_list_info.indent;

        // Collect all list items at this level
        let items = collect_list_items(lines, is_ordered, base_indent);

        let total_consumed: usize = items.iter().map(|item| item.raw_line_count).sum();

        // Determine if this is a loose list (has blank lines between items)
        let is_loose = items.iter().any(|item| item.has_blank_after || item.has_internal_blank);

        let list_tag = if is_ordered { "ol" } else { "ul" };
        let mut html = format!("<{}>\n", list_tag);

        for item in &items {
            let item_html = self.render_list_item(item, is_loose);
            html.push_str(&format!("<li>{}</li>\n", item_html));
        }

        html.push_str(&format!("</{}>\n", list_tag));

        (html, total_consumed)
    }

    fn render_list_item(&mut self, item: &ListItem, loose: bool) -> String {
        // Parse the item content
        let mut content_lines: Vec<&str> = item.content_lines.iter().map(|s| s.as_str()).collect();

        if content_lines.is_empty() {
            return String::new();
        }

        // Check if there are sub-lists
        let has_sublist = content_lines.iter().any(|l| is_unordered_list_start(l) || is_ordered_list_start(l));

        if !has_sublist && !loose && !item.has_internal_blank {
            // Simple tight list item - just render inline
            let text = content_lines.join("\n");
            return render_inline(text.trim());
        }

        if !has_sublist && loose {
            // Loose list item - wrap in <p>
            let text = content_lines.iter()
                .filter(|l| !l.trim().is_empty())
                .cloned()
                .collect::<Vec<_>>()
                .join(" ");
            return format!("<p>{}</p>", render_inline(text.trim()));
        }

        // Complex item with sub-list or multiple paragraphs
        let mut result = String::new();
        let mut para_lines = Vec::new();
        let mut i = 0;

        while i < content_lines.len() {
            let line = content_lines[i];

            if line.trim().is_empty() {
                // Blank line - end current paragraph
                if !para_lines.is_empty() {
                    let text = para_lines.join("\n");
                    if loose {
                        result.push_str(&format!("\n<p>{}</p>\n", render_inline(text.trim())));
                    } else {
                        result.push_str(&render_inline(text.trim()));
                    }
                    para_lines.clear();
                }
                i += 1;
                continue;
            }

            // Check for sub-list
            if is_unordered_list_start(line) || is_ordered_list_start(line) {
                // End current paragraph
                if !para_lines.is_empty() {
                    let text = para_lines.join("\n");
                    if loose {
                        result.push_str(&format!("\n<p>{}</p>\n", render_inline(text.trim())));
                    } else {
                        result.push_str(&render_inline(text.trim()));
                    }
                    para_lines.clear();
                }
                // Parse sub-list
                let remaining: Vec<&str> = content_lines[i..].to_vec();
                let (sublist_html, consumed) = self.parse_list_block(&remaining);
                result.push_str("\n");
                result.push_str(&sublist_html);
                i += consumed;
                continue;
            }

            para_lines.push(line);
            i += 1;
        }

        if !para_lines.is_empty() {
            let text = para_lines.join("\n");
            if loose {
                result.push_str(&format!("\n<p>{}</p>\n", render_inline(text.trim())));
            } else {
                result.push_str(&render_inline(text.trim()));
            }
        }

        result
    }
}

#[derive(Debug)]
struct ListInfo {
    indent: usize,
    is_ordered: bool,
    marker_width: usize,
    content_start: usize,
}

#[derive(Debug)]
struct ListItem {
    content_lines: Vec<String>,
    raw_line_count: usize,
    has_blank_after: bool,
    has_internal_blank: bool,
}

fn get_list_info(line: &str) -> Option<ListInfo> {
    let indent = line.len() - line.trim_start().len();
    let t = line.trim_start();

    if t.starts_with("- ") || t.starts_with("* ") || t.starts_with("+ ") {
        return Some(ListInfo {
            indent,
            is_ordered: false,
            marker_width: 2,
            content_start: indent + 2,
        });
    }

    // Ordered list: digits followed by . or )
    let mut digit_end = 0;
    for c in t.chars() {
        if c.is_ascii_digit() { digit_end += 1; } else { break; }
    }
    if digit_end > 0 && digit_end <= 9 {
        let after_digits = &t[digit_end..];
        if after_digits.starts_with(". ") || after_digits.starts_with(") ") {
            let marker_width = digit_end + 2;
            return Some(ListInfo {
                indent,
                is_ordered: true,
                marker_width,
                content_start: indent + marker_width,
            });
        }
    }

    None
}

fn is_unordered_list_start(line: &str) -> bool {
    let t = line.trim_start();
    t.starts_with("- ") || t.starts_with("* ") || t.starts_with("+ ")
}

fn is_ordered_list_start(line: &str) -> bool {
    let t = line.trim_start();
    let mut digit_end = 0;
    for c in t.chars() {
        if c.is_ascii_digit() { digit_end += 1; } else { break; }
    }
    if digit_end > 0 && digit_end <= 9 {
        let after = &t[digit_end..];
        return after.starts_with(". ") || after.starts_with(") ");
    }
    false
}

fn is_list_continuation(_line: &str) -> bool {
    false
}

fn collect_list_items<'a>(lines: &[&'a str], is_ordered: bool, base_indent: usize) -> Vec<ListItem> {
    let mut items = Vec::new();
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i];

        if line.trim().is_empty() {
            i += 1;
            continue;
        }

        let list_info = match get_list_info(line) {
            Some(info) => info,
            None => break,
        };

        if list_info.indent != base_indent { break; }
        if list_info.is_ordered != is_ordered { break; }

        // Get content of this item (after the marker)
        let first_content = if line.len() > list_info.content_start {
            line[list_info.content_start..].to_string()
        } else {
            String::new()
        };

        let mut content_lines = vec![first_content];
        let mut raw_count = 1;
        let mut has_blank_after = false;
        let mut has_internal_blank = false;
        i += 1;

        // Collect continuation lines
        while i < lines.len() {
            let next = lines[i];

            if next.trim().is_empty() {
                // Blank line - check what follows
                i += 1;
                raw_count += 1;

                // Look ahead
                if i < lines.len() {
                    let peek = lines[i];
                    if peek.trim().is_empty() {
                        // Multiple blank lines - end of item
                        has_blank_after = true;
                        i -= 1;
                        raw_count -= 1;
                        break;
                    }
                    let peek_indent = peek.len() - peek.trim_start().len();
                    if peek_indent <= base_indent {
                        // Next item at same level or outer
                        has_blank_after = true;
                        break;
                    }
                    // Continuation - blank line inside the item
                    has_internal_blank = true;
                    content_lines.push(String::new());
                    // Continue collecting
                }
                continue;
            }

            let next_indent = next.len() - next.trim_start().len();

            if next_indent <= base_indent {
                // New list item or end of list
                break;
            }

            // Continuation (sub-item or continuation text)
            let stripped = if next_indent > base_indent + list_info.marker_width - 1 {
                // Sub-item level - keep appropriate indentation
                let remove_indent = base_indent + list_info.marker_width;
                if next.len() >= remove_indent {
                    next[remove_indent..].to_string()
                } else {
                    next.trim_start().to_string()
                }
            } else {
                next.trim_start().to_string()
            };

            content_lines.push(stripped);
            raw_count += 1;
            i += 1;
        }

        items.push(ListItem {
            content_lines,
            raw_line_count: raw_count,
            has_blank_after,
            has_internal_blank,
        });
    }

    items
}

fn render_code_block(lang: &str, code_lines: &[String]) -> String {
    let parts: Vec<&str> = lang.split(',').collect();
    let base_lang = parts[0].trim();

    let is_rust = base_lang == "rust";
    let has_ignore = parts.iter().any(|&p| p.trim() == "ignore");
    let has_no_playground = parts.iter().any(|&p| p.trim() == "no_playground");

    let is_playground = is_rust && !has_ignore && !has_no_playground;

    if is_rust && !has_ignore {
        render_rust_code_block(lang, parts.as_slice(), code_lines, is_playground)
    } else {
        render_generic_code_block(lang, code_lines)
    }
}

fn render_rust_code_block(lang: &str, parts: &[&str], code_lines: &[String], is_playground: bool) -> String {
    // Check if code has fn main()
    let has_main = code_lines.iter().any(|l| {
        let t = l.trim();
        t == "fn main() {" || t.starts_with("fn main(") || t.starts_with("pub fn main(")
    });

    let has_shebang = code_lines.iter().any(|l| l.starts_with("#!") && !l.starts_with("# "));

    let needs_main_wrapper = !has_main && !has_shebang;

    let hideline_marker = "#"; // Default is "#"

    let mut rendered = String::new();

    if needs_main_wrapper {
        rendered.push_str("<span class=\"boring\">#![allow(unused)]\n</span>");
        rendered.push_str("<span class=\"boring\">fn main() {\n</span>");
    }

    for line in code_lines {
        if is_hidden_line(line, hideline_marker) {
            let content = strip_hidden_marker(line, hideline_marker);
            rendered.push_str(&format!("<span class=\"boring\">{}\n</span>", escape_html_code(content)));
        } else {
            rendered.push_str(&escape_html_code(line));
            rendered.push('\n');
        }
    }

    if needs_main_wrapper {
        rendered.push_str("<span class=\"boring\">}</span>");
    }

    let lang_class = build_lang_class(lang);

    if is_playground {
        format!("<pre><pre class=\"playground\"><code class=\"language-{}\">{}</code></pre></pre>\n", lang_class, rendered)
    } else {
        format!("<pre><code class=\"language-{}\">{}</code></pre>\n", lang_class, rendered)
    }
}

fn is_hidden_line(line: &str, marker: &str) -> bool {
    if marker == "#" {
        // Hidden if starts with "# " or is just "#"
        // But NOT if it starts with "#!" (shebang) or "##" (double hash)
        if line == "#" { return true; }
        if line.starts_with("# ") { return true; }
        if line.starts_with('#') && !line.starts_with("#!") && !line.starts_with("##") {
            return true;
        }
        false
    } else {
        line.starts_with(marker)
    }
}

fn strip_hidden_marker(line: &str, marker: &str) -> &str {
    if marker == "#" {
        if line == "#" { return ""; }
        if line.starts_with("# ") { return &line[2..]; }
        if line.starts_with('#') { return &line[1..]; }
    }
    line
}

fn render_generic_code_block(lang: &str, code_lines: &[String]) -> String {
    let code_content: String = code_lines.iter()
        .map(|l| escape_html_code(l))
        .collect::<Vec<_>>()
        .join("\n");

    if lang.is_empty() {
        format!("<pre><code>{}\n</code></pre>\n", code_content)
    } else {
        let lang_class = build_lang_class(lang);
        format!("<pre><code class=\"language-{}\">{}\n</code></pre>\n", lang_class, code_content)
    }
}

fn build_lang_class(lang: &str) -> String {
    // Convert comma-separated annotations to space-separated CSS classes
    lang.split(',')
        .map(|p| p.trim())
        .filter(|p| !p.is_empty())
        .collect::<Vec<_>>()
        .join(" ")
}

fn parse_atx_heading(line: &str) -> Option<(u8, String)> {
    let t = line.trim_start();
    if !t.starts_with('#') { return None; }

    let mut level = 0u8;
    for c in t.chars() {
        if c == '#' { level += 1; } else { break; }
    }
    if level > 6 { return None; }

    let rest = &t[level as usize..];
    if !rest.is_empty() && !rest.starts_with(' ') && !rest.starts_with('\t') {
        return None;
    }

    let text = rest.trim().trim_end_matches('#').trim().to_string();
    Some((level, text))
}

fn is_thematic_break(line: &str) -> bool {
    let t = line.trim();

    let chars: Vec<char> = t.chars().collect();
    if chars.is_empty() { return false; }

    let marker = chars[0];
    if marker != '-' && marker != '*' && marker != '_' { return false; }

    let mut count = 0;
    for c in &chars {
        if *c == marker { count += 1; }
        else if *c != ' ' { return false; }
    }

    count >= 3
}

fn is_html_block_start(line: &str) -> bool {
    let t = line.trim_start();
    if !t.starts_with('<') { return false; }

    // Check for block-level HTML tags
    let block_tags = ["address", "article", "aside", "base", "basefont", "blockquote",
                     "body", "caption", "center", "col", "colgroup", "dd", "details",
                     "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure",
                     "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6",
                     "head", "header", "hr", "html", "iframe", "legend", "li", "link",
                     "main", "menu", "menuitem", "meta", "nav", "noframes", "ol", "optgroup",
                     "option", "p", "param", "search", "section", "summary", "table", "tbody",
