fn parse_html_block<'a>(lines: &[&'a str]) -> (String, usize) {
    let mut html = String::new();
    let mut consumed = 0;

    for line in lines {
        if line.trim().is_empty() && consumed > 0 {
            consumed += 1;
            break;
        }
        html.push_str(line);
        html.push('\n');
        consumed += 1;
    }

    (html, consumed)
}

fn is_table_separator(line: &str) -> bool {
    let t = line.trim();
    t.contains('|') && t.chars().all(|c| c == '|' || c == '-' || c == ':' || c == ' ')
}

fn split_table_cells(line: &str) -> Vec<&str> {
