    let line = if line.starts_with('|') { &line[1..] } else { line };
    let line = if line.ends_with('|') { &line[..line.len()-1] } else { line };
    line.split('|').collect()
}

/// Render inline markdown markup
pub fn render_inline(text: &str) -> String {
    render_inline_str(text)
}

fn render_inline_str(text: &str) -> String {
    let mut result = String::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        // Escape sequences
        if c == '\\' && i + 1 < chars.len() {
            let next = chars[i + 1];
            let escapable = "\\`*_{}[]()#+-.!|~\"'<>";
            if escapable.contains(next) {
                result.push_str(&html_char(next));
                i += 2;
                continue;
            }
        }

        // HTML passthrough / entities
        if c == '&' {
            // Check for HTML entity
            let rest: String = chars[i..].iter().collect();
            if let Some(semi_pos) = rest.find(';') {
                if semi_pos < 20 {
                    let entity = &rest[..semi_pos+1];
                    // Valid entity starts with &# or &letter
                    if entity.len() > 2 && (entity.chars().nth(1) == Some('#') || 
                        entity.chars().nth(1).map_or(false, |c| c.is_alphabetic())) {
                        result.push_str(entity);
                        i += entity.chars().count();
                        continue;
                    }
                }
            }
            result.push_str("&amp;");
            i += 1;
            continue;
        }

        // HTML tag passthrough
        if c == '<' {
            let rest: String = chars[i..].iter().collect();
            // Autolink
            if let Some(end) = rest.find('>') {
                let tag = &rest[..end+1];
                if is_inline_html(tag) {
                    result.push_str(tag);
                    i += tag.chars().count();
                    continue;
                }
                // Autolink: <url> or <email>
                let inner = &tag[1..tag.len()-1];
                if inner.contains("://") || (inner.contains('@') && !inner.contains(' ')) {
                    let href = if inner.contains("://") { inner.to_string() } 
                        else { format!("mailto:{}", inner) };
                    result.push_str(&format!("<a href=\"{}\">{}</a>", escape_html(&href), escape_html(inner)));
                    i += tag.chars().count();
                    continue;
                }
            }
            result.push_str("&lt;");
            i += 1;
            continue;
        }

        if c == '>' {
            result.push_str("&gt;");
            i += 1;
            continue;
        }

        // Code span
        if c == '`' {
            let mut bt = 0;
            while i + bt < chars.len() && chars[i + bt] == '`' { bt += 1; }
            let bt_str: String = std::iter::repeat('`').take(bt).collect();
            let search_start = i + bt;
            let remaining: String = chars[search_start..].iter().collect();

            if let Some(close_pos) = find_code_span_close(&remaining, &bt_str) {
                let code_content = &remaining[..close_pos];
                let collapsed = collapse_whitespace(code_content);
                result.push_str(&format!("<code>{}</code>", escape_html_code(&collapsed)));
                i = search_start + close_pos + bt;
                continue;
            }

            result.push_str(&bt_str);
            i += bt;
            continue;
        }

        // Strikethrough ~~text~~
        if c == '~' && i + 1 < chars.len() && chars[i + 1] == '~' {
            let remaining: String = chars[i+2..].iter().collect();
            if let Some(end) = remaining.find("~~") {
                let content = &remaining[..end];
                result.push_str(&format!("<del>{}</del>", render_inline_str(content)));
                i += 2 + end + 2;
                continue;
            }
        }

        // Bold/Italic with * or _
        if (c == '*' || c == '_') {
            if let Some((rendered, skip)) = try_strong_em(&chars, i) {
                result.push_str(&rendered);
                i += skip;
                continue;
            }
        }

        // Images ![alt](src)
        if c == '!' && i + 1 < chars.len() && chars[i + 1] == '[' {
            if let Some((alt, href, title, skip)) = parse_link_or_img(&chars, i + 1) {
                let title_attr = title.as_deref().map(|t| format!(" title=\"{}\"", escape_html(t))).unwrap_or_default();
                result.push_str(&format!("<img src=\"{}\" alt=\"{}\"{}  />", 
                    escape_html(&href), escape_html(&alt), title_attr));
                // Remove the extra space
                let last = result.len();
                if result.ends_with("\"  />") {
                    result.truncate(last - 5);
                    result.push_str("\" />");
                }
                i += 1 + skip;
                continue;
            }
            result.push('!');
            i += 1;
            continue;
        }

        // Links [text](href)
        if c == '[' {
            if let Some((text, href, title, skip)) = parse_link_or_img(&chars, i) {
                let rendered_text = render_inline_str(&text);
                let href = convert_md_link(&href);
                let title_attr = title.as_deref().map(|t| format!(" title=\"{}\"", escape_html(t))).unwrap_or_default();
                result.push_str(&format!("<a href=\"{}\"{}>{}</a>",
                    escape_html(&href), title_attr, rendered_text));
                i += skip;
                continue;
            }
        }

        result.push_str(&html_char(c));
        i += 1;
    }

    result
}

fn html_char(c: char) -> String {
    match c {
        '&' => "&amp;".to_string(),
        '<' => "&lt;".to_string(),
        '>' => "&gt;".to_string(),
        _ => c.to_string(),
    }
}

fn is_inline_html(s: &str) -> bool {
    // Check if it's a valid inline HTML tag
    s.starts_with('<') && s.ends_with('>') && {
        let inner = &s[1..s.len()-1];
        // Must start with letter or /
        inner.starts_with(|c: char| c.is_alphabetic() || c == '/')
    }
}

fn find_code_span_close(text: &str, marker: &str) -> Option<usize> {
    text.find(marker)
}

fn collapse_whitespace(s: &str) -> String {
    // Trim and collapse newlines to spaces
    let s = s.replace('\n', " ");
    // Remove single space padding if both sides have spaces
    let s = s.trim();
    s.to_string()
}

fn try_strong_em(chars: &[char], start: usize) -> Option<(String, usize)> {
    let marker = chars[start];

    // Count markers
    let mut count = 0;
    while start + count < chars.len() && chars[start + count] == marker {
        count += 1;
    }

    if count >= 3 {
        // Try ***text***
        let content_start = start + 3;
        let remaining: String = chars[content_start..].iter().collect();
        let close: String = std::iter::repeat(marker).take(3).collect();
        if let Some(end) = remaining.find(&close) {
            let content = &remaining[..end];
            // Check it's not empty and doesn't start/end with space
            if !content.is_empty() && !content.starts_with(' ') && !content.ends_with(' ') {
                let rendered = render_inline_str(content);
                return Some((format!("<em><strong>{}</strong></em>", rendered), 3 + end + 3));
            }
        }
    }

    if count >= 2 {
        // Try **text**
        let content_start = start + 2;
        let remaining: String = chars[content_start..].iter().collect();
        let close: String = std::iter::repeat(marker).take(2).collect();
        if let Some(end) = remaining.find(&close) {
            let content = &remaining[..end];
            if !content.is_empty() && !content.starts_with(' ') && !content.ends_with(' ') {
                let rendered = render_inline_str(content);
                return Some((format!("<strong>{}</strong>", rendered), 2 + end + 2));
            }
        }
    }

    if count >= 1 {
        // Try *text*
        let content_start = start + 1;
        let remaining: String = chars[content_start..].iter().collect();
        let close = marker.to_string();
        if let Some(end) = remaining.find(marker) {
            let content = &remaining[..end];
            if !content.is_empty() && !content.starts_with(' ') && !content.ends_with(' ') {
                let rendered = render_inline_str(content);
                return Some((format!("<em>{}</em>", rendered), 1 + end + 1));
            }
        }
    }

    None
}

fn parse_link_or_img(chars: &[char], start: usize) -> Option<(String, String, Option<String>, usize)> {
    if start >= chars.len() || chars[start] != '[' { return None; }

    // Find closing ]
    let mut depth = 0;
    let mut text_end = None;
    let mut j = start;
    while j < chars.len() {
        match chars[j] {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 { text_end = Some(j); break; }
            }
            _ => {}
        }
        j += 1;
    }

    let text_end = text_end?;
    let text: String = chars[start+1..text_end].iter().collect();

    // Check for (href...)
    let after = text_end + 1;
    if after >= chars.len() || chars[after] != '(' { return None; }

    // Find closing )
    let mut paren_depth = 1;
    let mut k = after + 1;
    while k < chars.len() && paren_depth > 0 {
        match chars[k] {
            '(' => paren_depth += 1,
            ')' => {
                paren_depth -= 1;
                if paren_depth == 0 { break; }
            }
            _ => {}
        }
        k += 1;
    }

    if k >= chars.len() { return None; }

    let href_content: String = chars[after+1..k].iter().collect();
    let (href, title) = parse_href_and_title(&href_content);

    Some((text, href, title, k + 1 - start))
}

fn parse_href_and_title(s: &str) -> (String, Option<String>) {
    let s = s.trim();

    // Handle <href>
    if s.starts_with('<') {
        if let Some(end) = s.find('>') {
            let href = s[1..end].to_string();
            let rest = s[end+1..].trim();
            if !rest.is_empty() {
                let title = parse_title(rest);
                return (href, title);
            }
            return (href, None);
        }
    }

    // Find href (up to whitespace or end)
    let mut href = String::new();
    let mut chars = s.chars().peekable();

    for c in &mut chars {
        if c == ' ' || c == '\t' || c == '\n' {
            break;
        }
        href.push(c);
    }

    let rest: String = chars.collect();
    let title = if !rest.trim().is_empty() {
        parse_title(rest.trim())
    } else {
        None
    };

    (href, title)
}

fn parse_title(s: &str) -> Option<String> {
    let s = s.trim();
    if (s.starts_with('"') && s.ends_with('"')) ||
       (s.starts_with('\'') && s.ends_with('\'')) {
        return Some(s[1..s.len()-1].to_string());
    }
    if s.starts_with('(') && s.ends_with(')') {
        return Some(s[1..s.len()-1].to_string());
    }
    None
}

fn convert_md_link(href: &str) -> String {
    if href.ends_with(".md") && !href.starts_with("http") && !href.starts_with('#') {
        let base = &href[..href.len()-3];
        // Check if there's a fragment
        if let Some(hash_pos) = base.find('#') {
            format!("{}.html{}", &base[..hash_pos], &href[href.len()-3+hash_pos+1-href.len()+base.len()..])
        } else {
            format!("{}.html", base)
        }
    } else {
        href.to_string()
    }
}
