        let mut html = format!("<{}>\n", list_tag);

        for item in &items {
            let item_html = self.render_list_item(item, is_loose);
            html.push_str(&format!("<li>{}</li>\n", item_html));
        }

        html.push_str(&format!("</{}>\n", list_tag));

        (html, total_consumed)
    }

    fn render_list_item(&mut self, item: &ListItem, loose: bool) -> String {
        // Parse the item content
        let mut content_lines: Vec<&str> = item.content_lines.iter().map(|s| s.as_str()).collect();

        if content_lines.is_empty() {
            return String::new();
        }

        // Check if there are sub-lists
        let has_sublist = content_lines.iter().any(|l| is_unordered_list_start(l) || is_ordered_list_start(l));

        if !has_sublist && !loose && !item.has_internal_blank {
            // Simple tight list item - just render inline
            let text = content_lines.join("\n");
            return render_inline(text.trim());
        }

        if !has_sublist && loose {
            // Loose list item - wrap in <p>
            let text = content_lines.iter()
                .filter(|l| !l.trim().is_empty())
                .cloned()
                .collect::<Vec<_>>()
                .join(" ");
            return format!("<p>{}</p>", render_inline(text.trim()));
        }

        // Complex item with sub-list or multiple paragraphs
        let mut result = String::new();
        let mut para_lines = Vec::new();
        let mut i = 0;

        while i < content_lines.len() {
            let line = content_lines[i];

            if line.trim().is_empty() {
                // Blank line - end current paragraph
                if !para_lines.is_empty() {
                    let text = para_lines.join("\n");
                    if loose {
                        result.push_str(&format!("\n<p>{}</p>\n", render_inline(text.trim())));
                    } else {
                        result.push_str(&render_inline(text.trim()));
                    }
                    para_lines.clear();
                }
                i += 1;
                continue;
            }

            // Check for sub-list
            if is_unordered_list_start(line) || is_ordered_list_start(line) {
                // End current paragraph
                if !para_lines.is_empty() {
                    let text = para_lines.join("\n");
                    if loose {
                        result.push_str(&format!("\n<p>{}</p>\n", render_inline(text.trim())));
                    } else {
                        result.push_str(&render_inline(text.trim()));
                    }
                    para_lines.clear();
                }
                // Parse sub-list
                let remaining: Vec<&str> = content_lines[i..].to_vec();
                let (sublist_html, consumed) = self.parse_list_block(&remaining);
                result.push_str("\n");
                result.push_str(&sublist_html);
                i += consumed;
                continue;
            }

            para_lines.push(line);
            i += 1;
        }

        if !para_lines.is_empty() {
            let text = para_lines.join("\n");
            if loose {
                result.push_str(&format!("\n<p>{}</p>\n", render_inline(text.trim())));
            } else {
                result.push_str(&render_inline(text.trim()));
            }
        }

        result
    }
}

#[derive(Debug)]
struct ListInfo {
    indent: usize,
    is_ordered: bool,
    marker_width: usize,
    content_start: usize,
}

#[derive(Debug)]
struct ListItem {
    content_lines: Vec<String>,
    raw_line_count: usize,
    has_blank_after: bool,
    has_internal_blank: bool,
}

fn get_list_info(line: &str) -> Option<ListInfo> {
    let indent = line.len() - line.trim_start().len();
    let t = line.trim_start();

    if t.starts_with("- ") || t.starts_with("* ") || t.starts_with("+ ") {
        return Some(ListInfo {
            indent,
            is_ordered: false,
            marker_width: 2,
            content_start: indent + 2,
        });
    }

    // Ordered list: digits followed by . or )
    let mut digit_end = 0;
    for c in t.chars() {
        if c.is_ascii_digit() { digit_end += 1; } else { break; }
    }
    if digit_end > 0 && digit_end <= 9 {
        let after_digits = &t[digit_end..];
        if after_digits.starts_with(". ") || after_digits.starts_with(") ") {
            let marker_width = digit_end + 2;
            return Some(ListInfo {
                indent,
                is_ordered: true,
                marker_width,
                content_start: indent + marker_width,
            });
        }
    }

    None
}

fn is_unordered_list_start(line: &str) -> bool {
    let t = line.trim_start();
    t.starts_with("- ") || t.starts_with("* ") || t.starts_with("+ ")
}

fn is_ordered_list_start(line: &str) -> bool {
    let t = line.trim_start();
    let mut digit_end = 0;
    for c in t.chars() {
        if c.is_ascii_digit() { digit_end += 1; } else { break; }
    }
    if digit_end > 0 && digit_end <= 9 {
        let after = &t[digit_end..];
        return after.starts_with(". ") || after.starts_with(") ");
    }
    false
}

fn is_list_continuation(_line: &str) -> bool {
    false
}

fn collect_list_items<'a>(lines: &[&'a str], is_ordered: bool, base_indent: usize) -> Vec<ListItem> {
    let mut items = Vec::new();
    let mut i = 0;

    while i < lines.len() {
        let line = lines[i];

        if line.trim().is_empty() {
            i += 1;
            continue;
        }

        let list_info = match get_list_info(line) {
            Some(info) => info,
            None => break,
        };

        if list_info.indent != base_indent { break; }
        if list_info.is_ordered != is_ordered { break; }

        // Get content of this item (after the marker)
        let first_content = if line.len() > list_info.content_start {
            line[list_info.content_start..].to_string()
        } else {
            String::new()
        };

        let mut content_lines = vec![first_content];
        let mut raw_count = 1;
        let mut has_blank_after = false;
        let mut has_internal_blank = false;
        i += 1;

        // Collect continuation lines
        while i < lines.len() {
            let next = lines[i];

            if next.trim().is_empty() {
                // Blank line - check what follows
                i += 1;
                raw_count += 1;

                // Look ahead
                if i < lines.len() {
                    let peek = lines[i];
                    if peek.trim().is_empty() {
                        // Multiple blank lines - end of item
                        has_blank_after = true;
                        i -= 1;
                        raw_count -= 1;
                        break;
                    }
                    let peek_indent = peek.len() - peek.trim_start().len();
                    if peek_indent <= base_indent {
                        // Next item at same level or outer
                        has_blank_after = true;
                        break;
                    }
                    // Continuation - blank line inside the item
                    has_internal_blank = true;
                    content_lines.push(String::new());
                    // Continue collecting
                }
                continue;
            }

            let next_indent = next.len() - next.trim_start().len();

            if next_indent <= base_indent {
                // New list item or end of list
                break;
            }

            // Continuation (sub-item or continuation text)
            let stripped = if next_indent > base_indent + list_info.marker_width - 1 {
                // Sub-item level - keep appropriate indentation
                let remove_indent = base_indent + list_info.marker_width;
                if next.len() >= remove_indent {
                    next[remove_indent..].to_string()
                } else {
                    next.trim_start().to_string()
                }
            } else {
                next.trim_start().to_string()
            };

            content_lines.push(stripped);
            raw_count += 1;
            i += 1;
        }

        items.push(ListItem {
            content_lines,
            raw_line_count: raw_count,
            has_blank_after,
            has_internal_blank,
        });
    }

    items
}

fn render_code_block(lang: &str, code_lines: &[String]) -> String {
    let parts: Vec<&str> = lang.split(',').collect();
    let base_lang = parts[0].trim();

    let is_rust = base_lang == "rust";
    let has_ignore = parts.iter().any(|&p| p.trim() == "ignore");
    let has_no_playground = parts.iter().any(|&p| p.trim() == "no_playground");

    let is_playground = is_rust && !has_ignore && !has_no_playground;

    if is_rust && !has_ignore {
        render_rust_code_block(lang, parts.as_slice(), code_lines, is_playground)
    } else {
        render_generic_code_block(lang, code_lines)
    }
}

fn render_rust_code_block(lang: &str, parts: &[&str], code_lines: &[String], is_playground: bool) -> String {
    // Check if code has fn main()
    let has_main = code_lines.iter().any(|l| {
        let t = l.trim();
        t == "fn main() {" || t.starts_with("fn main(") || t.starts_with("pub fn main(")
    });

    let has_shebang = code_lines.iter().any(|l| l.starts_with("#!") && !l.starts_with("# "));

    let needs_main_wrapper = !has_main && !has_shebang;

    let hideline_marker = "#"; // Default is "#"

    let mut rendered = String::new();

    if needs_main_wrapper {
        rendered.push_str("<span class=\"boring\">#![allow(unused)]\n</span>");
        rendered.push_str("<span class=\"boring\">fn main() {\n</span>");
    }

    for line in code_lines {
        if is_hidden_line(line, hideline_marker) {
            let content = strip_hidden_marker(line, hideline_marker);
            rendered.push_str(&format!("<span class=\"boring\">{}\n</span>", escape_html_code(content)));
        } else {
            rendered.push_str(&escape_html_code(line));
            rendered.push('\n');
        }
    }

    if needs_main_wrapper {
        rendered.push_str("<span class=\"boring\">}</span>");
    }

    let lang_class = build_lang_class(lang);

    if is_playground {
        format!("<pre><pre class=\"playground\"><code class=\"language-{}\">{}</code></pre></pre>\n", lang_class, rendered)
    } else {
        format!("<pre><code class=\"language-{}\">{}</code></pre>\n", lang_class, rendered)
    }
}

fn is_hidden_line(line: &str, marker: &str) -> bool {
    if marker == "#" {
        // Hidden if starts with "# " or is just "#"
        // But NOT if it starts with "#!" (shebang) or "##" (double hash)
        if line == "#" { return true; }
        if line.starts_with("# ") { return true; }
        if line.starts_with('#') && !line.starts_with("#!") && !line.starts_with("##") {
            return true;
        }
        false
    } else {
        line.starts_with(marker)
    }
}

fn strip_hidden_marker(line: &str, marker: &str) -> &str {
    if marker == "#" {
        if line == "#" { return ""; }
        if line.starts_with("# ") { return &line[2..]; }
        if line.starts_with('#') { return &line[1..]; }
    }
    line
}

fn render_generic_code_block(lang: &str, code_lines: &[String]) -> String {
    let code_content: String = code_lines.iter()
        .map(|l| escape_html_code(l))
        .collect::<Vec<_>>()
        .join("\n");

    if lang.is_empty() {
        format!("<pre><code>{}\n</code></pre>\n", code_content)
    } else {
        let lang_class = build_lang_class(lang);
        format!("<pre><code class=\"language-{}\">{}\n</code></pre>\n", lang_class, code_content)
    }
}

fn build_lang_class(lang: &str) -> String {
    // Convert comma-separated annotations to space-separated CSS classes
    lang.split(',')
        .map(|p| p.trim())
        .filter(|p| !p.is_empty())
        .collect::<Vec<_>>()
        .join(" ")
}

fn parse_atx_heading(line: &str) -> Option<(u8, String)> {
    let t = line.trim_start();
    if !t.starts_with('#') { return None; }

    let mut level = 0u8;
    for c in t.chars() {
        if c == '#' { level += 1; } else { break; }
    }
    if level > 6 { return None; }

    let rest = &t[level as usize..];
    if !rest.is_empty() && !rest.starts_with(' ') && !rest.starts_with('\t') {
        return None;
    }

    let text = rest.trim().trim_end_matches('#').trim().to_string();
    Some((level, text))
}

fn is_thematic_break(line: &str) -> bool {
    let t = line.trim();

    let chars: Vec<char> = t.chars().collect();
    if chars.is_empty() { return false; }

    let marker = chars[0];
    if marker != '-' && marker != '*' && marker != '_' { return false; }

    let mut count = 0;
    for c in &chars {
        if *c == marker { count += 1; }
        else if *c != ' ' { return false; }
    }

    count >= 3
}

fn is_html_block_start(line: &str) -> bool {
    let t = line.trim_start();
    if !t.starts_with('<') { return false; }

    // Check for block-level HTML tags
    let block_tags = ["address", "article", "aside", "base", "basefont", "blockquote",
                     "body", "caption", "center", "col", "colgroup", "dd", "details",
                     "dialog", "dir", "div", "dl", "dt", "fieldset", "figcaption", "figure",
                     "footer", "form", "frame", "frameset", "h1", "h2", "h3", "h4", "h5", "h6",
                     "head", "header", "hr", "html", "iframe", "legend", "li", "link",
                     "main", "menu", "menuitem", "meta", "nav", "noframes", "ol", "optgroup",
                     "option", "p", "param", "search", "section", "summary", "table", "tbody",
                     "td", "tfoot", "th", "thead", "title", "tr", "track", "ul"];

    if t.starts_with("<!--") { return true; }
    if t.starts_with("</") {
        let tag_end = t[2..].find(|c: char| !c.is_alphanumeric()).unwrap_or(t.len()-2);
        let tag = t[2..2+tag_end].to_lowercase();
        return block_tags.contains(&tag.as_str());
    }

    let tag_end = t[1..].find(|c: char| !c.is_alphanumeric() && c != '-').unwrap_or(t.len()-1);
    let tag = t[1..1+tag_end].to_lowercase();
    block_tags.contains(&tag.as_str())
}

fn parse_html_block<'a>(lines: &[&'a str]) -> (String, usize) {
    let mut html = String::new();
    let mut consumed = 0;

    for line in lines {
        if line.trim().is_empty() && consumed > 0 {
            consumed += 1;
            break;
        }
        html.push_str(line);
        html.push('\n');
        consumed += 1;
    }

    (html, consumed)
}

fn is_table_separator(line: &str) -> bool {
    let t = line.trim();
    t.contains('|') && t.chars().all(|c| c == '|' || c == '-' || c == ':' || c == ' ')
}

fn split_table_cells(line: &str) -> Vec<&str> {
    let line = line.trim();
    let line = if line.starts_with('|') { &line[1..] } else { line };
    let line = if line.ends_with('|') { &line[..line.len()-1] } else { line };
    line.split('|').collect()
}

/// Render inline markdown markup
pub fn render_inline(text: &str) -> String {
    render_inline_str(text)
}

fn render_inline_str(text: &str) -> String {
    let mut result = String::new();
    let chars: Vec<char> = text.chars().collect();
    let mut i = 0;

    while i < chars.len() {
        let c = chars[i];

        // Escape sequences
        if c == '\\' && i + 1 < chars.len() {
            let next = chars[i + 1];
            let escapable = "\\`*_{}[]()#+-.!|~\"'<>";
            if escapable.contains(next) {
                result.push_str(&html_char(next));
                i += 2;
                continue;
            }
        }

        // HTML passthrough / entities
        if c == '&' {
            // Check for HTML entity
            let rest: String = chars[i..].iter().collect();
            if let Some(semi_pos) = rest.find(';') {
                if semi_pos < 20 {
                    let entity = &rest[..semi_pos+1];
                    // Valid entity starts with &# or &letter
                    if entity.len() > 2 && (entity.chars().nth(1) == Some('#') || 
                        entity.chars().nth(1).map_or(false, |c| c.is_alphabetic())) {
                        result.push_str(entity);
                        i += entity.chars().count();
                        continue;
                    }
                }
            }
            result.push_str("&amp;");
            i += 1;
            continue;
        }

        // HTML tag passthrough
        if c == '<' {
            let rest: String = chars[i..].iter().collect();
            // Autolink
            if let Some(end) = rest.find('>') {
                let tag = &rest[..end+1];
                if is_inline_html(tag) {
                    result.push_str(tag);
                    i += tag.chars().count();
                    continue;
                }
                // Autolink: <url> or <email>
                let inner = &tag[1..tag.len()-1];
                if inner.contains("://") || (inner.contains('@') && !inner.contains(' ')) {
                    let href = if inner.contains("://") { inner.to_string() } 
                        else { format!("mailto:{}", inner) };
                    result.push_str(&format!("<a href=\"{}\">{}</a>", escape_html(&href), escape_html(inner)));
                    i += tag.chars().count();
                    continue;
                }
            }
            result.push_str("&lt;");
            i += 1;
            continue;
        }

        if c == '>' {
            result.push_str("&gt;");
            i += 1;
            continue;
        }

        // Code span
        if c == '`' {
            let mut bt = 0;
            while i + bt < chars.len() && chars[i + bt] == '`' { bt += 1; }
            let bt_str: String = std::iter::repeat('`').take(bt).collect();
            let search_start = i + bt;
            let remaining: String = chars[search_start..].iter().collect();

            if let Some(close_pos) = find_code_span_close(&remaining, &bt_str) {
                let code_content = &remaining[..close_pos];
                let collapsed = collapse_whitespace(code_content);
                result.push_str(&format!("<code>{}</code>", escape_html_code(&collapsed)));
                i = search_start + close_pos + bt;
                continue;
            }

            result.push_str(&bt_str);
            i += bt;
            continue;
        }

        // Strikethrough ~~text~~
        if c == '~' && i + 1 < chars.len() && chars[i + 1] == '~' {
            let remaining: String = chars[i+2..].iter().collect();
            if let Some(end) = remaining.find("~~") {
                let content = &remaining[..end];
                result.push_str(&format!("<del>{}</del>", render_inline_str(content)));
                i += 2 + end + 2;
                continue;
            }
        }

        // Bold/Italic with * or _
        if (c == '*' || c == '_') {
            if let Some((rendered, skip)) = try_strong_em(&chars, i) {
                result.push_str(&rendered);
                i += skip;
                continue;
            }
        }

        // Images ![alt](src)
        if c == '!' && i + 1 < chars.len() && chars[i + 1] == '[' {
            if let Some((alt, href, title, skip)) = parse_link_or_img(&chars, i + 1) {
                let title_attr = title.as_deref().map(|t| format!(" title=\"{}\"", escape_html(t))).unwrap_or_default();
                result.push_str(&format!("<img src=\"{}\" alt=\"{}\"{}  />", 
                    escape_html(&href), escape_html(&alt), title_attr));
                // Remove the extra space
                let last = result.len();
                if result.ends_with("\"  />") {
                    result.truncate(last - 5);
                    result.push_str("\" />");
                }
                i += 1 + skip;
                continue;
            }
            result.push('!');
            i += 1;
            continue;
        }

        // Links [text](href)
        if c == '[' {
            if let Some((text, href, title, skip)) = parse_link_or_img(&chars, i) {
                let rendered_text = render_inline_str(&text);
                let href = convert_md_link(&href);
                let title_attr = title.as_deref().map(|t| format!(" title=\"{}\"", escape_html(t))).unwrap_or_default();
                result.push_str(&format!("<a href=\"{}\"{}>{}</a>",
                    escape_html(&href), title_attr, rendered_text));
                i += skip;
                continue;
            }
        }

        result.push_str(&html_char(c));
        i += 1;
    }

    result
}

fn html_char(c: char) -> String {
    match c {
        '&' => "&amp;".to_string(),
        '<' => "&lt;".to_string(),
        '>' => "&gt;".to_string(),
        _ => c.to_string(),
    }
}

fn is_inline_html(s: &str) -> bool {
    // Check if it's a valid inline HTML tag
    s.starts_with('<') && s.ends_with('>') && {
        let inner = &s[1..s.len()-1];
        // Must start with letter or /
        inner.starts_with(|c: char| c.is_alphabetic() || c == '/')
    }
}

fn find_code_span_close(text: &str, marker: &str) -> Option<usize> {
    text.find(marker)
}

fn collapse_whitespace(s: &str) -> String {
    // Trim and collapse newlines to spaces
    let s = s.replace('\n', " ");
    // Remove single space padding if both sides have spaces
    let s = s.trim();
    s.to_string()
}

fn try_strong_em(chars: &[char], start: usize) -> Option<(String, usize)> {
    let marker = chars[start];

    // Count markers
    let mut count = 0;
    while start + count < chars.len() && chars[start + count] == marker {
        count += 1;
    }

    if count >= 3 {
        // Try ***text***
        let content_start = start + 3;
        let remaining: String = chars[content_start..].iter().collect();
        let close: String = std::iter::repeat(marker).take(3).collect();
        if let Some(end) = remaining.find(&close) {
            let content = &remaining[..end];
            // Check it's not empty and doesn't start/end with space
            if !content.is_empty() && !content.starts_with(' ') && !content.ends_with(' ') {
                let rendered = render_inline_str(content);
                return Some((format!("<em><strong>{}</strong></em>", rendered), 3 + end + 3));
            }
        }
    }

    if count >= 2 {
        // Try **text**
        let content_start = start + 2;
        let remaining: String = chars[content_start..].iter().collect();
        let close: String = std::iter::repeat(marker).take(2).collect();
        if let Some(end) = remaining.find(&close) {
            let content = &remaining[..end];
            if !content.is_empty() && !content.starts_with(' ') && !content.ends_with(' ') {
                let rendered = render_inline_str(content);
                return Some((format!("<strong>{}</strong>", rendered), 2 + end + 2));
            }
        }
    }

    if count >= 1 {
        // Try *text*
        let content_start = start + 1;
        let remaining: String = chars[content_start..].iter().collect();
        let close = marker.to_string();
        if let Some(end) = remaining.find(marker) {
            let content = &remaining[..end];
            if !content.is_empty() && !content.starts_with(' ') && !content.ends_with(' ') {
                let rendered = render_inline_str(content);
                return Some((format!("<em>{}</em>", rendered), 1 + end + 1));
            }
        }
    }

    None
}

fn parse_link_or_img(chars: &[char], start: usize) -> Option<(String, String, Option<String>, usize)> {
    if start >= chars.len() || chars[start] != '[' { return None; }

    // Find closing ]
    let mut depth = 0;
    let mut text_end = None;
    let mut j = start;
    while j < chars.len() {
        match chars[j] {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 { text_end = Some(j); break; }
            }
            _ => {}
        }
        j += 1;
    }

    let text_end = text_end?;
    let text: String = chars[start+1..text_end].iter().collect();

    // Check for (href...)
    let after = text_end + 1;
    if after >= chars.len() || chars[after] != '(' { return None; }

    // Find closing )
    let mut paren_depth = 1;
    let mut k = after + 1;
    while k < chars.len() && paren_depth > 0 {
        match chars[k] {
            '(' => paren_depth += 1,
            ')' => {
                paren_depth -= 1;
                if paren_depth == 0 { break; }
            }
            _ => {}
        }
        k += 1;
    }

    if k >= chars.len() { return None; }

    let href_content: String = chars[after+1..k].iter().collect();
    let (href, title) = parse_href_and_title(&href_content);

    Some((text, href, title, k + 1 - start))
}

fn parse_href_and_title(s: &str) -> (String, Option<String>) {
    let s = s.trim();

    // Handle <href>
    if s.starts_with('<') {
        if let Some(end) = s.find('>') {
            let href = s[1..end].to_string();
            let rest = s[end+1..].trim();
            if !rest.is_empty() {
                let title = parse_title(rest);
                return (href, title);
            }
            return (href, None);
        }
    }

    // Find href (up to whitespace or end)
    let mut href = String::new();
    let mut chars = s.chars().peekable();

    for c in &mut chars {
        if c == ' ' || c == '\t' || c == '\n' {
            break;
        }
        href.push(c);
    }

    let rest: String = chars.collect();
    let title = if !rest.trim().is_empty() {
        parse_title(rest.trim())
    } else {
        None
    };

    (href, title)
}

fn parse_title(s: &str) -> Option<String> {
    let s = s.trim();
    if (s.starts_with('"') && s.ends_with('"')) ||
       (s.starts_with('\'') && s.ends_with('\'')) {
        return Some(s[1..s.len()-1].to_string());
    }
    if s.starts_with('(') && s.ends_with(')') {
        return Some(s[1..s.len()-1].to_string());
    }
    None
}

fn convert_md_link(href: &str) -> String {
    if href.ends_with(".md") && !href.starts_with("http") && !href.starts_with('#') {
        let base = &href[..href.len()-3];
        // Check if there's a fragment
        if let Some(hash_pos) = base.find('#') {
            format!("{}.html{}", &base[..hash_pos], &href[href.len()-3+hash_pos+1-href.len()+base.len()..])
        } else {
            format!("{}.html", base)
        }
    } else {
        href.to_string()
    }
}
