                    level, id, id, html_text, level
                ));
                i += 1;
                continue;
            }

            // Setext heading
            if i + 1 < lines.len() {
                let next = lines[i + 1].trim();
                if !next.is_empty() && next.chars().all(|c| c == '=') && !line.trim().is_empty() {
                    let text = line.trim().to_string();
                    let id = self.get_heading_id(&text);
                    let html_text = render_inline(&text);
                    output.push_str(&format!("<h1 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h1>\n", id, id, html_text));
                    i += 2;
                    continue;
                }
                if !next.is_empty() && next.chars().all(|c| c == '-') && next.len() >= 2 && !line.trim().is_empty() {
                    let text = line.trim().to_string();
                    let id = self.get_heading_id(&text);
                    let html_text = render_inline(&text);
                    output.push_str(&format!("<h2 id=\"{}\"><a class=\"header\" href=\"#{}\">{}</a></h2>\n", id, id, html_text));
                    i += 2;
                    continue;
                }
            }

            // Thematic break (horizontal rule)
            if is_thematic_break(line) {
                output.push_str("<hr />\n");
                i += 1;
                continue;
            }

            // Fenced code block
            let trimmed = line.trim_start();
            if trimmed.starts_with("```") || trimmed.starts_with("~~~") {
                let fence_char = if trimmed.starts_with("```") { '`' } else { '~' };
                let fence_count = trimmed.chars().take_while(|&c| c == fence_char).count();
                let fence_str: String = std::iter::repeat(fence_char).take(fence_count).collect();
                let indent = line.len() - trimmed.len();
                let lang = trimmed[fence_count..].trim().to_string();
                let mut code_lines = Vec::new();
                i += 1;
                while i < lines.len() {
                    let cl = lines[i];
                    let cl_trimmed = cl.trim_start();
