            if let Some(list_info) = get_list_info(line) {
                let (list_html, consumed) = self.parse_list_block(&lines[i..]);
                output.push_str(&list_html);
                i += consumed;
                continue;
            }

            // Paragraph
            let (para_html, consumed) = self.parse_paragraph(&lines[i..]);
            output.push_str(&para_html);
            i += consumed;
        }

        output
    }

    fn parse_blockquote<'a>(&mut self, lines: &[&'a str]) -> (String, usize) {
        let mut bq_lines: Vec<String> = Vec::new();
        let mut consumed = 0;

        for line in lines {
            let t = line.trim_start();
            if t.starts_with("> ") {
                bq_lines.push(t[2..].to_string());
                consumed += 1;
            } else if t == ">" {
                bq_lines.push(String::new());
                consumed += 1;
            } else if line.trim().is_empty() && consumed > 0 {
                // Check if next line is a continuation
                consumed += 1;
                break;
            } else {
                break;
            }
        }

        while bq_lines.last().map_or(false, |l| l.trim().is_empty()) {
            bq_lines.pop();
        }

        let refs: Vec<&str> = bq_lines.iter().map(|s| s.as_str()).collect();
        let inner_html = self.parse_blocks(&refs);

        (format!("<blockquote>\n{}</blockquote>\n", inner_html), consumed)
    }

    fn parse_table<'a>(&mut self, lines: &[&'a str]) -> (String, usize) {
        if lines.len() < 2 { return (String::new(), 0); }

        let headers = split_table_cells(lines[0]);
        let _seps = split_table_cells(lines[1]);

        let mut html = String::from("<div class=\"table-wrapper\"><table><thead><tr>");
        for h in &headers {
            html.push_str(&format!("<th>{}</th>", render_inline(h.trim())));
        }
        html.push_str("</tr></thead><tbody>\n");

        let mut consumed = 2;
        for line in &lines[2..] {
            if line.trim().is_empty() || !line.contains('|') { break; }
            let cells = split_table_cells(line);
            html.push_str("<tr>");
            for (idx, cell) in cells.iter().enumerate() {
                if idx < headers.len() {
                    html.push_str(&format!("<td>{}</td>", render_inline(cell.trim())));
                }
            }
            html.push_str("</tr>\n");
            consumed += 1;
        }

        html.push_str("</tbody></table>\n</div>\n");
        (html, consumed)
    }

    fn parse_paragraph<'a>(&mut self, lines: &[&'a str]) -> (String, usize) {
        let mut para_lines = Vec::new();
        let mut consumed = 0;

        for (idx, line) in lines.iter().enumerate() {
            if line.trim().is_empty() {
                consumed += 1;
                break;
            }
            // Setext heading detection
            if idx > 0 {
                let t = line.trim();
                if (t.chars().all(|c| c == '=') || t.chars().all(|c| c == '-')) && !t.is_empty() {
                    // This is a setext heading - handled by parse_blocks
                    para_lines.push(*line);
                    consumed += 1;
                    break;
                }
            }
            if consumed > 0 && (
                parse_atx_heading(line).is_some() ||
                line.trim_start().starts_with("```") ||
                line.trim_start().starts_with("~~~") ||
                line.trim_start().starts_with(">") ||
                is_unordered_list_start(line) ||
                is_ordered_list_start(line) ||
                is_html_block_start(line) ||
                is_thematic_break(line) ||
                (line.starts_with("    ") && !is_list_continuation(line))
            ) {
                break;
            }
            para_lines.push(*line);
            consumed += 1;
        }

        if para_lines.is_empty() {
            return (String::new(), consumed);
        }

        let text = para_lines.join("\n");
        let rendered = render_inline(&text);
        (format!("<p>{}</p>\n", rendered), consumed)
    }

    fn parse_list_block<'a>(&mut self, lines: &[&'a str]) -> (String, usize) {
        // Parse a list (possibly mixed tight/loose)
        let first_list_info = match get_list_info(lines[0]) {
            Some(info) => info,
            None => return (String::new(), 0),
        };

        let is_ordered = first_list_info.is_ordered;
        let base_indent = first_list_info.indent;

        // Collect all list items at this level
        let items = collect_list_items(lines, is_ordered, base_indent);

        let total_consumed: usize = items.iter().map(|item| item.raw_line_count).sum();

        // Determine if this is a loose list (has blank lines between items)
        let is_loose = items.iter().any(|item| item.has_blank_after || item.has_internal_blank);

        let list_tag = if is_ordered { "ol" } else { "ul" };
        let mut html = format!("<{}>\n", list_tag);

        for item in &items {
            let item_html = self.render_list_item(item, is_loose);
            html.push_str(&format!("<li>{}</li>\n", item_html));
        }

        html.push_str(&format!("</{}>\n", list_tag));

        (html, total_consumed)
    }

    fn render_list_item(&mut self, item: &ListItem, loose: bool) -> String {
        // Parse the item content
        let mut content_lines: Vec<&str> = item.content_lines.iter().map(|s| s.as_str()).collect();

        if content_lines.is_empty() {
            return String::new();
        }

        // Check if there are sub-lists
        let has_sublist = content_lines.iter().any(|l| is_unordered_list_start(l) || is_ordered_list_start(l));

        if !has_sublist && !loose && !item.has_internal_blank {
            // Simple tight list item - just render inline
            let text = content_lines.join("\n");
            return render_inline(text.trim());
        }

        if !has_sublist && loose {
            // Loose list item - wrap in <p>
            let text = content_lines.iter()
                .filter(|l| !l.trim().is_empty())
                .cloned()
                .collect::<Vec<_>>()
                .join(" ");
            return format!("<p>{}</p>", render_inline(text.trim()));
        }

        // Complex item with sub-list or multiple paragraphs
        let mut result = String::new();
        let mut para_lines = Vec::new();
        let mut i = 0;

        while i < content_lines.len() {
            let line = content_lines[i];

            if line.trim().is_empty() {
                // Blank line - end current paragraph
                if !para_lines.is_empty() {
                    let text = para_lines.join("\n");
                    if loose {
                        result.push_str(&format!("\n<p>{}</p>\n", render_inline(text.trim())));
                    } else {
                        result.push_str(&render_inline(text.trim()));
                    }
                    para_lines.clear();
                }
                i += 1;
                continue;
            }

            // Check for sub-list
            if is_unordered_list_start(line) || is_ordered_list_start(line) {
                // End current paragraph
                if !para_lines.is_empty() {
                    let text = para_lines.join("\n");
                    if loose {
                        result.push_str(&format!("\n<p>{}</p>\n", render_inline(text.trim())));
                    } else {
                        result.push_str(&render_inline(text.trim()));
                    }
                    para_lines.clear();
                }
                // Parse sub-list
                let remaining: Vec<&str> = content_lines[i..].to_vec();
                let (sublist_html, consumed) = self.parse_list_block(&remaining);
                result.push_str("\n");
                result.push_str(&sublist_html);
                i += consumed;
                continue;
            }

            para_lines.push(line);
            i += 1;
        }

        if !para_lines.is_empty() {
            let text = para_lines.join("\n");
            if loose {
                result.push_str(&format!("\n<p>{}</p>\n", render_inline(text.trim())));
            } else {
                result.push_str(&render_inline(text.trim()));
            }
        }

        result
    }
