}

fn parse_link_or_img(chars: &[char], start: usize) -> Option<(String, String, Option<String>, usize)> {
    if start >= chars.len() || chars[start] != '[' { return None; }

    // Find closing ]
    let mut depth = 0;
    let mut text_end = None;
    let mut j = start;
    while j < chars.len() {
        match chars[j] {
            '[' => depth += 1,
            ']' => {
                depth -= 1;
                if depth == 0 { text_end = Some(j); break; }
            }
            _ => {}
        }
        j += 1;
    }

    let text_end = text_end?;
    let text: String = chars[start+1..text_end].iter().collect();

    // Check for (href...)
    let after = text_end + 1;
    if after >= chars.len() || chars[after] != '(' { return None; }

    // Find closing )
    let mut paren_depth = 1;
    let mut k = after + 1;
    while k < chars.len() && paren_depth > 0 {
        match chars[k] {
            '(' => paren_depth += 1,
            ')' => {
                paren_depth -= 1;
                if paren_depth == 0 { break; }
            }
            _ => {}
        }
        k += 1;
    }

    if k >= chars.len() { return None; }

    let href_content: String = chars[after+1..k].iter().collect();
    let (href, title) = parse_href_and_title(&href_content);

    Some((text, href, title, k + 1 - start))
}

fn parse_href_and_title(s: &str) -> (String, Option<String>) {
    let s = s.trim();

    // Handle <href>
    if s.starts_with('<') {
        if let Some(end) = s.find('>') {
            let href = s[1..end].to_string();
            let rest = s[end+1..].trim();
            if !rest.is_empty() {
                let title = parse_title(rest);
                return (href, title);
            }
            return (href, None);
        }
    }

    // Find href (up to whitespace or end)
    let mut href = String::new();
    let mut chars = s.chars().peekable();

    for c in &mut chars {
        if c == ' ' || c == '\t' || c == '\n' {
            break;
        }
        href.push(c);
    }

    let rest: String = chars.collect();
    let title = if !rest.trim().is_empty() {
        parse_title(rest.trim())
    } else {
        None
    };

    (href, title)
}

fn parse_title(s: &str) -> Option<String> {
    let s = s.trim();
    if (s.starts_with('"') && s.ends_with('"')) ||
       (s.starts_with('\'') && s.ends_with('\'')) {
        return Some(s[1..s.len()-1].to_string());
    }
    if s.starts_with('(') && s.ends_with(')') {
        return Some(s[1..s.len()-1].to_string());
    }
    None
}

fn convert_md_link(href: &str) -> String {
    if href.ends_with(".md") && !href.starts_with("http") && !href.starts_with('#') {
        let base = &href[..href.len()-3];
        // Check if there's a fragment
        if let Some(hash_pos) = base.find('#') {
            format!("{}.html{}", &base[..hash_pos], &href[href.len()-3+hash_pos+1-href.len()+base.len()..])
        } else {
            format!("{}.html", base)
        }
    } else {
        href.to_string()
    }
}
