# Original has "}\ncode" (no extra newline after last line)
# My output has "}\n\ncode" (extra newline after last line)
# 
# The issue: in render_rust_code_block, I push each line followed by \n
# The last line "}" gets "\n" appended, so the code ends with "}\n"
# But the original ends with "}" (no trailing \n before </code>).

# Actually looking at it again:
# Original: "}}</code></pre></pre>" - closing } followed immediately by </code>
# Mine: "}\n</code>" - extra newline before </code>

# The fix: in render_rust_code_block, don't add \n after the last line
# OR when building the rendered string, trim the trailing \n

python3 << 'EOF'
with open('/workspace/src/markdown.rs', 'r') as f:
    content = f.read()

# In render_rust_code_block, after building rendered, trim trailing \n
old = '''    if is_playground {
        format!("<pre><pre class=\\"playground\\"><code class=\\"language-{}\\">{}</code></pre></pre>\\n", lang_class, rendered)
    } else {
        format!("<pre><code class=\\"language-{}\\">{}</code></pre>\\n", lang_class, rendered)
    }'''

new = '''    // Trim trailing newline from rendered content
    let rendered = rendered.trim_end_matches('\\n').to_string();
    if is_playground {
        format!("<pre><pre class=\\"playground\\"><code class=\\"language-{}\\">{}</code></pre></pre>\\n", lang_class, rendered)
    } else {
        format!("<pre><code class=\\"language-{}\\">{}</code></pre>\\n", lang_class, rendered)
    }'''

if old in content:
    content = content.replace(old, new)
    print("Fixed trailing newline")
else:
    print("Not found")

with open('/workspace/src/markdown.rs', 'w') as f:
    f.write(content)
EOF

