# <code>code</code>. -> strip tags -> "code." no extra space
# But my strip adds a space after >
# 
# Looking at my strip_html: "result.push(' ');" after > 
# This adds a space after EVERY tag including </code>
# So "paragraph <code>code</code>." becomes "paragraph  code ." (spaces around code)
# But original has "code." not "code ."

# Fix: only add space after block-level tags, not inline tags
# Or even better: just don't add spaces in strip_html, let the text flow naturally

# Let me update strip_html to NOT add spaces for inline tags
python3 << 'EOF'
with open('/workspace/src/utils.rs', 'r') as f:
    content = f.read()

# Replace the strip_html function that adds space after >
old_strip = '''        let c = bytes[i] as char;
        if c == '<' {
            // Skip to end of tag
            if let Some(end) = s[i..].find('>') {
                result.push(' ');
                i += end + 1;
            } else {
                i += 1;
            }
        } else {
            result.push(c);
            i += 1;
        }'''

new_strip = '''        let c = bytes[i] as char;
        if c == '<' {
            // Skip to end of tag, add space only for block-level tags
            if let Some(end) = s[i..].find('>') {
                let tag = s[i..i+end+1].to_lowercase();
                let is_block = tag.contains("</p>") || tag.contains("</h") || 
                    tag.contains("</li>") || tag.contains("</td>") ||
                    tag.contains("<br") || tag.contains("<p>") || tag.contains("<h") ||
                    tag.contains("<li>") || tag.contains("<td>") ||
