                    tag.contains("<blockquote") || tag.contains("</blockquote") ||
                    tag.contains("<table") || tag.contains("</table") ||
                    tag.contains("<tr>") || tag.contains("</tr>") ||
                    tag.contains("<th>") || tag.contains("<th ") ||
                    tag.contains("<thead") || tag.contains("</thead") ||
                    tag.contains("<tbody") || tag.contains("</tbody") ||
                    tag.contains("<hr");
                if is_block {
                    result.push(' ');
                }
                i += end + 1;
            } else {
                i += 1;
            }
        } else {
            result.push(c);
            i += 1;
        }'''

