with open('/workspace/src/preprocessor.rs', 'r') as f:
    content = f.read()

# Make include failures non-fatal
old = '''fn process_include(args: &str, chapter_dir: &Path) -> Result<String, String> {
    // Parse: filename or filename:start or filename:start:end or filename::end
    let (file_path, range) = parse_include_args(args);
    let full_path = chapter_dir.join(file_path);

    let content = std::fs::read_to_string(&full_path)
        .map_err(|e| format!("Failed to read include file {:?}: {}", full_path, e))?;

    let lines: Vec<&str> = content.lines().collect();
    let selected = apply_line_range(&lines, range);

    Ok(selected.join("\\n"))
}'''

new = '''fn process_include(args: &str, chapter_dir: &Path) -> Result<String, String> {
    // Parse: filename or filename:start or filename:start:end or filename::end
    let (file_path, range) = parse_include_args(args);
    let full_path = chapter_dir.join(file_path);

    match std::fs::read_to_string(&full_path) {
        Ok(content) => {
            let lines: Vec<&str> = content.lines().collect();
            let selected = apply_line_range(&lines, range);
            Ok(selected.join("\\n"))
        }
        Err(e) => {
            // Non-fatal - just return empty string and log warning
            eprintln!("Error: Failed to read include file {:?}: {}", full_path, e);
