                out.push_str("{}");
            }
            if !self.children.is_empty() {
                let mut chars: Vec<char> = self.children.keys().cloned().collect();
                chars.sort();
                for c in chars {
                    out.push(',');
                    out.push('"');
                    match c {
                        '"' => { out.push('\\'); out.push('"'); }
                        '\\' => { out.push('\\'); out.push('\\'); }
                        other => out.push(other),
                    }
                    out.push('"');
                    out.push(':');
                    self.children[&c].to_json_into(out);
                }
