def parse_search(filepath):
    with open(filepath) as f:
        content = f.read()
    start = content.find("JSON.parse('") + len("JSON.parse('")
    i, escape, chars = start, False, []
    while i < len(content):
        c = content[i]
        if escape:
            if c == "'": chars.append("'")
            elif c == '\\': chars.append('\\')
            else: chars.append('\\'); chars.append(c)
            escape = False
        elif c == '\\': escape = True
        elif c == "'": break
        else: chars.append(c)
        i += 1
    import json
    return json.loads(''.join(chars))

o = parse_search('/tmp/testbook/book/searchindex.js')
m = parse_search('/tmp/testbook_mine/book/searchindex.js')

# Compare
print("doc_urls:", o['doc_urls'] == m['doc_urls'])
print("docs:", o['index']['documentStore']['docs'] == m['index']['documentStore']['docs'])
print("docInfo:", o['index']['documentStore']['docInfo'] == m['index']['documentStore']['docInfo'])
print("length:", o['index']['documentStore']['length'] == m['index']['documentStore']['length'])
print("results_options:", o['results_options'] == m['results_options'])
print("search_options:", o['search_options'] == m['search_options'])

# Compare inverted index
o_title = o['index']['index']['title']
m_title = m['index']['index']['title']
print("title index root keys equal:", set(o_title['root'].keys()) == set(m_title['root'].keys()))

# The tf values might differ slightly
def compare_index(oi, mi, depth=0):
    for k in oi:
        if k == 'docs':
            for doc_id in oi[k]:
                if doc_id not in mi.get(k, {}):
                    print(f"{'  '*depth}Missing doc {doc_id} in mine")
                elif abs(oi[k][doc_id]['tf'] - mi.get(k, {}).get(doc_id, {}).get('tf', 0)) > 0.0001:
                    print(f"{'  '*depth}tf diff for doc {doc_id}: {oi[k][doc_id]['tf']} vs {mi.get(k,{}).get(doc_id,{}).get('tf',0)}")
        elif k == 'df':
            if oi[k] != mi.get(k, 0):
                print(f"{'  '*depth}df diff: {oi[k]} vs {mi.get(k, 0)}")
        elif k not in ('df', 'docs'):
            if k in mi:
                compare_index(oi[k], mi[k], depth+1)
            else:
                print(f"{'  '*depth}Missing key '{k}' in mine")

print("\nChecking title index differences:")
compare_index(o_title['root'], m_title['root'])
